const FOLDED_MODULE_IDS = new Set(['catchfn', 'contentfn', 'logfn']);

export function enabledNavigationModules(registry: RegistryViewModel): AdminModuleViewModel[] {
  return registry.modules
    .filter(
      (module) =>
        module.enabled &&
        module.visibleInNavigation !== false &&
        !module.parentModuleId &&
        !FOLDED_MODULE_IDS.has(module.id.toLowerCase())
    )
    .sort((left, right) => {
      const groupOrder = (left.group ?? '').localeCompare(right.group ?? '');
      return groupOrder || left.name.localeCompare(right.name);
    });
}

export function moduleById(
  registry: RegistryViewModel,
  moduleId: string
): AdminModuleViewModel | undefined {
  return registry.modules.find(
    (module) => module.enabled && module.id.toLowerCase() === moduleId.toLowerCase()
  );
}

export function formatValue(
  value: unknown,
  format: ResourceColumnViewModel['format'] = 'text'
): string {
  if (value === null || value === undefined || value === '') return '—';
  if (format === 'datetime') {
    const date = new Date(String(value));
    return Number.isNaN(date.valueOf()) ? String(value) : date.toLocaleString();
  }
  if (format === 'number' && typeof value === 'number') return value.toLocaleString();
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}

export function statusTone(status: string | undefined): ResourceTone {
  switch (status?.toLowerCase()) {
    case 'healthy':
    case 'active':
    case 'enabled':
    case 'success':
    case 'succeeded':
    case 'completed':
      return 'success';
    case 'queued':
    case 'pending':
    case 'running':
    case 'degraded':
    case 'warning':
      return 'warning';
    case 'critical':
    case 'error':
    case 'failed':
    case 'failure':
    case 'disabled':
      return 'danger';
    case 'info':
      return 'info';
    default:
      return 'neutral';
  }
}
import type {
  AdminErrorViewModel,
  AdminModuleViewModel,
  OverviewViewModel,
  RegistryViewModel,
  ShellViewModel,
} from './view-models';

export const ADMIN_API_PREFIX = '/api/admin/v1';

export type AdminFetch = (
  input: RequestInfo | URL,
  init?: RequestInit
) => Promise<Response>;

export type AdminApiResult<T> =
  | { ok: true; data: T; requestId?: string }
  | { ok: false; error: AdminErrorViewModel };

interface ApiEnvelope<T> {
  ok?: boolean;
  data?: T;
  error?: {
    code?: string;
    message?: string;
    details?: Record<string, unknown>;
  };
  requestId?: string;
}

function requestIdFrom(response: Response, body: unknown): string | undefined {
  if (body && typeof body === 'object' && 'requestId' in body) {
    const value = (body as { requestId?: unknown }).requestId;
    if (typeof value === 'string') return value;
  }
  return response.headers.get('x-request-id') ?? undefined;
}

export async function fetchAdmin<T>(
  fetcher: AdminFetch,
  path: string,
  init: RequestInit = {}
): Promise<AdminApiResult<T>> {
  const headers = new Headers(init.headers);
  headers.set('accept', 'application/json');
  const method = (init.method ?? 'GET').toUpperCase();
  if (method !== 'GET' && method !== 'HEAD' && !headers.has('content-type')) {
    headers.set('content-type', 'application/json');
  }

  try {
    const response = await fetcher(path, {
      ...init,
      headers,
      credentials: 'same-origin',
      cache: 'no-store',
    });
    const contentType = response.headers.get('content-type') ?? '';
    const body: unknown = contentType.includes('application/json')
      ? await response.json()
      : await response.text();
    const envelope =
      body && typeof body === 'object' ? (body as ApiEnvelope<T>) : undefined;
    const requestId = requestIdFrom(response, body);

    if (!response.ok || envelope?.ok === false) {
      return {
        ok: false,
        error: {
          status: response.status,
          code:
            envelope?.error?.code ??
            (response.status === 401
              ? 'AUTHENTICATION_REQUIRED'
              : response.status === 403
                ? 'PERMISSION_DENIED'
                : response.status === 404
                  ? 'NOT_FOUND'
                  : 'ADMIN_API_ERROR'),
          message:
            envelope?.error?.message ??
            (typeof body === 'string' && body.trim()
              ? body
              : `The administration API returned HTTP ${response.status}.`),
          requestId,
          details: envelope?.error?.details,
        },
      };
    }

    return {
      ok: true,
      data: (envelope && 'data' in envelope ? envelope.data : body) as T,
      requestId,
    };
  } catch (cause) {
    return {
      ok: false,
      error: {
        status: 503,
        code: 'ADMIN_API_UNAVAILABLE',
        message: cause instanceof Error ? cause.message : 'The administration API is unavailable.',
      },
    };
  }
}

function normalizeModule(candidate: AdminModuleViewModel): AdminModuleViewModel {
  return {
    ...candidate,
    name: candidate.name || candidate.id,
    description: candidate.description || `Operate ${candidate.name || candidate.id}.`,
    href: candidate.href || `/modules/${candidate.id}`,
    enabled: candidate.enabled !== false,
    resources: candidate.resources ?? [],
    actions: candidate.actions ?? [],
  };
}

export function normalizeRegistry(candidate: unknown): RegistryViewModel {
  const source = candidate && typeof candidate === 'object' ? candidate : {};
  const rawModules = Array.isArray((source as { modules?: unknown[] }).modules)
    ? (source as { modules: AdminModuleViewModel[] }).modules
    : [];
  return {
    ...(source as Partial<RegistryViewModel>),
    modules: rawModules.map(normalizeModule).filter((module) => module.enabled),
  };
}

export function normalizeOverview(candidate: unknown): OverviewViewModel {
  const source = candidate && typeof candidate === 'object' ? candidate : {};
  const overview = source as Partial<OverviewViewModel>;
  return {
    metrics: Array.isArray(overview.metrics) ? overview.metrics : [],
    alerts: Array.isArray(overview.alerts) ? overview.alerts : [],
    activity: Array.isArray(overview.activity) ? overview.activity : [],
    health: Array.isArray(overview.health) ? overview.health : [],
  };
}

export async function loadShellViewModel(fetcher: AdminFetch): Promise<ShellViewModel> {
  const [registryResult, overviewResult] = await Promise.all([
    fetchAdmin<RegistryViewModel>(fetcher, `${ADMIN_API_PREFIX}/registry`),
    fetchAdmin<OverviewViewModel>(fetcher, `${ADMIN_API_PREFIX}/overview`),
  ]);

  const primaryError = !registryResult.ok
    ? registryResult.error
    : !overviewResult.ok
      ? overviewResult.error
      : undefined;
  const registry = registryResult.ok ? normalizeRegistry(registryResult.data) : { modules: [] };
  const overview = overviewResult.ok
    ? normalizeOverview(overviewResult.data)
    : { metrics: [], alerts: [], activity: [], health: [] };

  const registryData = registryResult.ok && registryResult.data && typeof registryResult.data === 'object'
    ? (registryResult.data as Record<string, unknown>)
    : {};
  const overviewData = overviewResult.ok && overviewResult.data && typeof overviewResult.data === 'object'
    ? (overviewResult.data as Record<string, unknown>)
    : {};

  return {
    session: (registryData.session ?? overviewData.session) as ShellViewModel['session'],
    context: ((registryData.context ?? overviewData.context ?? {}) as ShellViewModel['context']),
    registry,
    overview,
    error: primaryError,
  };
}
