  actionOutput: actionOutputSchema
} as const satisfies Record<string, AdminJsonSchema>;

function resourceOperations(resource: ApiFnAdminResourceDefinition): AdminOperationDefinition[] {
  const baseId = 'apifn.' + resource.id;
  const basePath = '/resources/' + resource.id;
  return [
    {
      id: baseId + '.list',
      title: 'List ' + resource.label,
      description: 'List permitted ' + resource.label.toLowerCase() + ' in the active administration scope.',
      inputSchema: listInputSchema,
      outputSchema: listOutputSchema,
      route: { method: 'GET', path: basePath },
      permission: 'apifn.' + resource.id + '.read',
      safety: { classification: 'read', idempotent: true, requiresConfirmation: false, audit: 'optional' },
      pagination: { mode: 'cursor', defaultLimit: 50, maxLimit: 200 },
      mcp: { readOnlyHint: true, destructiveHint: false, idempotentHint: true }
    },
    {
      id: baseId + '.get',
      title: 'Get ' + resource.label,
      description: 'Get one permitted ' + resource.label.toLowerCase() + ' resource.',
      inputSchema: getInputSchema,
      outputSchema: getOutputSchema,
      route: { method: 'GET', path: basePath + '/:id' },
      permission: 'apifn.' + resource.id + '.read',
      safety: { classification: 'read', idempotent: true, requiresConfirmation: false, audit: 'optional' },
      mcp: { readOnlyHint: true, destructiveHint: false, idempotentHint: true }
    }
  ];
}

function actionOperation(action: ApiFnAdminActionDefinition): AdminOperationDefinition {
  return {
    id: 'apifn.' + action.resource + '.' + action.id,
    title: action.title,
    description: action.description,
    inputSchema: actionInputSchema,
    outputSchema: actionOutputSchema,
    route: { method: 'POST', path: '/resources/' + action.resource + '/actions/' + action.id },
    permission: 'apifn.' + action.resource + '.' + action.id,
    safety: {
      classification: action.classification,
      idempotent: action.idempotent,
      requiresConfirmation: action.requiresConfirmation,
      audit: 'required'
    },
    mcp: {
      readOnlyHint: false,
      destructiveHint: action.classification === 'destructive',
      idempotentHint: action.idempotent
    }
  };
}

const operations: AdminOperationDefinition[] = [
  ...apiFnAdminResources.flatMap(resourceOperations),
  ...apiFnAdminActions.map(actionOperation)
];

export const apiFnAdminCapability = defineAdminCapability({
  schemaVersion: '1.0',
  id: 'apifn',
  displayName: 'ApiFn',
  version: '1.0.0',
  description: 'Commercial-grade, function-owned operator capabilities for ApiFn.',
  category: 'optional',
  dependencies: [],
  navigation: [
    {
      id: 'apifn',
      label: 'ApiFn',
      path: '/modules/apifn',
      icon: 'apifn',
      description: 'Operate ApiFn in the active scope.',
      order: 100
    }
  ],
  operations
});

export type ApiFnAdminOperationId = (typeof apiFnAdminCapability.operations)[number]['id'];

export interface ApiFnAdminServiceRequest {
  operationId: ApiFnAdminOperationId;
  input: unknown;
  context: AdminOperationContext;
}

export interface ApiFnAdminService {
  execute(
    request: ApiFnAdminServiceRequest
  ): Promise<AdminOperationResult<Record<string, unknown>>> | AdminOperationResult<Record<string, unknown>>;
}

export function createApiFnAdminAdapter(service: ApiFnAdminService): AdminCapabilityAdapter {
  const handlers: Record<string, (request: { input: unknown; context: AdminOperationContext }) =>
    Promise<AdminOperationResult<Record<string, unknown>>> | AdminOperationResult<Record<string, unknown>>> = {};

  for (const operation of apiFnAdminCapability.operations) {
    handlers[operation.id] = (request) => service.execute({
      operationId: operation.id,
      input: request.input,
      context: request.context
    });
  }

  return createKernelAdminCapabilityAdapter(apiFnAdminCapability, handlers);
}

export const adminCapability = apiFnAdminCapability;
export const createAdminAdapter = createApiFnAdminAdapter;

