export function adminInputFingerprint(input: unknown): string { return stableSerialize(input); }

export class MemoryAdminIdempotencyStore implements AdminIdempotencyStore {
  private readonly records = new Map<string, AdminIdempotencyRecord>();
  get(identity: AdminIdempotencyIdentity): AdminIdempotencyRecord | undefined {
    return this.records.get(adminIdempotencyStorageKey(identity));
  }
  set(record: AdminIdempotencyRecord): void {
    const key = adminIdempotencyStorageKey(record.identity);
    const existing = this.records.get(key);
    if (existing && existing.fingerprint !== record.fingerprint) {
      throw new AdminError("conflict", "The idempotency key was already used with different input.");
    }
    this.records.set(key, structuredClone(record));
  }
}

export async function readAdminIdempotency<T>(
  store: AdminIdempotencyStore,
  identity: AdminIdempotencyIdentity,
  input: unknown,
): Promise<AdminIdempotencyRecord<T> | undefined> {
  const record = await store.get(identity) as AdminIdempotencyRecord<T> | undefined;
  if (record && record.fingerprint !== adminInputFingerprint(input)) {
    throw new AdminError("conflict", "The idempotency key was already used with different input.");
  }
  return record;
}
