  const handlers: Record<string, (request: { input: unknown; context: AdminOperationContext }) => Promise<AdminOperationResult<Record<string, unknown>>> | AdminOperationResult<Record<string, unknown>>> = {};
  for (const operation of ciFnAdminCapability.operations) handlers[operation.id] = (request) => service.execute({ operationId: operation.id, input: request.input, context: request.context });
  return createKernelAdminCapabilityAdapter(ciFnAdminCapability, handlers);
}
