import type {
  AdminCapabilityAdapter,
  AdminCapabilityManifest,
  AdminOperationContext,
  AdminOperationHandlers,
  AdminOperationResult,
} from "./types.js";

export interface CreateAdminCapabilityAdapterOptions<
  TManifest extends AdminCapabilityManifest = AdminCapabilityManifest,
> {
  manifest: TManifest;
  handlers: AdminOperationHandlers;
}

function isResult(value: unknown): value is AdminOperationResult {
  return Boolean(value && typeof value === "object" && "data" in value && (value as { ok?: unknown }).ok !== false);
}

export function createAdminCapabilityAdapter<
  const TManifest extends AdminCapabilityManifest,
>(
  manifestOrOptions: TManifest | CreateAdminCapabilityAdapterOptions<TManifest>,
  providedHandlers?: AdminOperationHandlers,
): AdminCapabilityAdapter<TManifest> {
  const manifest = ("manifest" in manifestOrOptions
    ? manifestOrOptions.manifest
    : manifestOrOptions) as TManifest;
  const handlers = ("manifest" in manifestOrOptions
    ? manifestOrOptions.handlers
    : providedHandlers) ?? {};

  const invoke = async <T = unknown>(
    operationId: string,
    input: unknown,
    context: AdminOperationContext,
  ): Promise<AdminOperationResult<T>> => {
    const operation = manifest.operations.find((candidate) => candidate.id === operationId);
    if (!operation) {
      throw new Error(`Unknown admin operation: ${manifest.id}.${operationId}`);
    }
    const handler = handlers[operationId];
    if (!handler) {
      throw new Error(`No handler registered for admin operation: ${manifest.id}.${operationId}`);
    }
    const value = await handler({ input, context });
    return (isResult(value)
      ? value
      : {
          ok: true,
          data: value,
          requestId: context.requestId,
          correlationId: context.correlationId,
        }) as AdminOperationResult<T>;
  };

  return { manifest, handlers, invoke, execute: invoke };
}

export const createAdminAdapter = createAdminCapabilityAdapter;
import { describe, expect, it } from "vitest";
import { createAdminCapabilityAdapter } from "./adapter.js";
import { AdminError } from "./errors.js";
import { createAdminRegistry } from "./registry.js";
import { testAdapter, testManifest } from "./test-fixtures.js";
import { validateAdminCapabilityManifest } from "./validator.js";

describe("AdminCapabilityRegistry", () => {
  it("exposes only explicitly enabled modules and permits a shell-only install", () => {
    const first = testAdapter("firstfn");
    const second = testAdapter("secondfn");
    const registry = createAdminRegistry({ adapters: [first, second], enabledModules: ["secondfn"] });
    expect(registry.enabledModuleIds).toEqual(["secondfn"]);
    expect(registry.operations.every((entry) => entry.moduleId === "secondfn")).toBe(true);
    expect(registry.navigation.map((entry) => entry.moduleId)).toEqual(["secondfn"]);
    expect(createAdminRegistry({ adapters: [first], enabledModules: [] }).operations).toEqual([]);
  });

  it("fails closed when the explicit allowlist is missing at runtime", () => {
    expect(() => createAdminRegistry({ adapters: [] } as never)).toThrowError(/explicit enabledModules/);
  });

  it("orders dependencies before dependents and requires nested owners", () => {
    const owner = testAdapter("ownerfn");
    const nested = testAdapter("nestedfn", {
      availability: "nested",
      owner: { moduleId: "ownerfn", mountPath: "nested" },
      dependencies: ["ownerfn"],
    });
    expect(() => createAdminRegistry({ adapters: [owner, nested], enabledModules: ["nestedfn"] })).toThrowError(/requires enabled module ownerfn/);
    const registry = createAdminRegistry({ adapters: [nested, owner], enabledModules: ["nestedfn", "ownerfn"] });
    expect(registry.enabledModuleIds).toEqual(["ownerfn", "nestedfn"]);
    expect(registry.navigation.find((entry) => entry.moduleId === "nestedfn")?.ownerModuleId).toBe("ownerfn");
  });

  it("detects dependency cycles", () => {
    const first = testAdapter("firstfn", { dependencies: ["secondfn"] });
    const second = testAdapter("secondfn", { dependencies: ["firstfn"] });
    expect(() => createAdminRegistry({ adapters: [first, second], enabledModules: ["firstfn", "secondfn"] })).toThrowError(/dependency cycle/);
  });

  it("detects operation and parameter-equivalent route collisions", () => {
    const manifest = testManifest("examplefn");
    const operation = manifest.operations[0]!;
    const invalid = testManifest("examplefn", {
      operations: [
        { ...operation, id: "examplefn.records.first", route: { method: "GET", path: "/records/:id" } },
        { ...operation, id: "examplefn.records.second", route: { method: "GET", path: "/records/{recordId}" } },
      ],
    });
    expect(validateAdminCapabilityManifest(invalid)).toContainEqual(expect.objectContaining({ message: "duplicates another route" }));
    expect(() => createAdminRegistry({
      adapters: [createAdminCapabilityAdapter(invalid, {})],
      enabledModules: ["examplefn"],
    })).toThrow(AdminError);
  });

  it("matches concrete paths against parameterized registry routes", () => {
    const manifest = testManifest("examplefn");
    const operation = manifest.operations[0]!;
    const adapter = createAdminCapabilityAdapter(testManifest("examplefn", {
      operations: [{ ...operation, route: { method: "GET", path: "/records/:id" } }],
    }), { [operation.id]: async () => ({ data: { items: [] } }) });
    const registry = createAdminRegistry({ adapters: [adapter], enabledModules: ["examplefn"] });
    expect(registry.matchRoute("GET", "/api/admin/v1/modules/examplefn/records/record-1")?.operation.id).toBe(operation.id);
  });
});

describe("manifest validation", () => {
  it("rejects unsafe destructive operations", () => {
    const manifest = testManifest("examplefn");
    const invalid = testManifest("examplefn", {
      operations: [{
        ...manifest.operations[0]!,
        safety: { classification: "destructive", idempotent: true, audit: "optional", requiresConfirmation: false },
      }],
    });
    const issues = validateAdminCapabilityManifest(invalid);
    expect(issues.map((issue) => issue.message)).toEqual(expect.arrayContaining([
      "mutations must require audit",
      "destructive operations must require confirmation",
    ]));
  });
});
import { describe, expect, it, vi } from "vitest";
import { createAdminCapabilityAdapter } from "./adapter.js";
import { MemoryAdminAuditSink } from "./audit.js";
import { createAdminDispatcher } from "./dispatcher.js";
import { MemoryAdminIdempotencyStore } from "./idempotency.js";
import { createAdminRegistry } from "./registry.js";
import { testManifest } from "./test-fixtures.js";
import type { AdminOperationContext } from "./types.js";

const context = (overrides: Partial<AdminOperationContext> = {}): AdminOperationContext => ({
  scope: {
    organizationId: "org_1",
    workspaceId: "ws_1",
    projectId: "project_1",
    environmentId: "env_1",
    namespace: "tenant_1",
    region: "in-south",
  },
  actor: { id: "user_1", permissions: ["examplefn.records.read"] },
  requestId: "req_1",
  correlationId: "corr_1",
  source: "rest",
  ...overrides,
});

describe("AdminDispatcher", () => {
  it("validates input, permissions, and output without throwing unsafe domain errors", async () => {
    const manifest = testManifest();
    const handler = vi.fn(async () => ({ data: { items: [] } }));
    const registry = createAdminRegistry({
      adapters: [createAdminCapabilityAdapter(manifest, { [manifest.operations[0]!.id]: handler })],
      enabledModules: [manifest.id],
    });
    const dispatcher = createAdminDispatcher({ registry });

    expect(await dispatcher.dispatch({ operationId: "examplefn.records.list", input: { limit: 20 }, context: context() })).toMatchObject({ ok: true, data: { items: [] }, requestId: "req_1" });
    expect(handler).toHaveBeenCalledWith(expect.objectContaining({ input: { limit: 20 }, context: expect.objectContaining({ scope: expect.objectContaining({ environmentId: "env_1" }) }) }));

    expect(await dispatcher.dispatch({ operationId: "examplefn.records.list", input: { limit: 1000 }, context: context() })).toMatchObject({ ok: false, error: { code: "invalid_argument" } });
    expect(await dispatcher.dispatch({ operationId: "examplefn.records.list", input: {}, context: context({ actor: { id: "denied", permissions: [] } }) })).toMatchObject({ ok: false, error: { code: "forbidden" } });
  });

  it("enforces confirmation, required audit, idempotency replay, conflict, and redaction", async () => {
    const read = testManifest().operations[0]!;
    const manifest = testManifest("examplefn", {
      operations: [{
        ...read,
        id: "examplefn.records.delete",
        title: "Delete record",
        inputSchema: { type: "object", properties: { id: { type: "string" }, apiToken: { type: "string" } }, required: ["id", "apiToken"], additionalProperties: false },
        outputSchema: { type: "object", properties: { deleted: { type: "boolean" } }, required: ["deleted"], additionalProperties: false },
        route: { method: "DELETE", path: "/records/:id" },
        permission: "examplefn.records.delete",
        safety: { classification: "destructive", idempotent: true, requiresConfirmation: true, audit: "required" },
      }],
    });
    const handler = vi.fn(async () => ({ data: { deleted: true } }));
    const registry = createAdminRegistry({
      adapters: [createAdminCapabilityAdapter(manifest, { "examplefn.records.delete": handler })],
      enabledModules: ["examplefn"],
    });
    const noInfrastructure = createAdminDispatcher({ registry });
    const baseContext = context({
      actor: { id: "user_1", permissions: ["examplefn.records.delete"] },
      confirmationToken: "confirmed",
      idempotencyKey: "idem_1",
    });
    expect(await noInfrastructure.dispatch({ operationId: "examplefn.records.delete", input: { id: "1", apiToken: "raw-secret" }, context: baseContext })).toMatchObject({ ok: false, error: { code: "dependency_unavailable" } });

    const audit = new MemoryAdminAuditSink();
    const idempotency = new MemoryAdminIdempotencyStore();
    const dispatcher = createAdminDispatcher({ registry, audit, idempotency, confirmation: { verify: ({ token }) => token === "confirmed" }, createAuditId: () => "audit_1" });
    expect(await dispatcher.dispatch({ operationId: "examplefn.records.delete", input: { id: "1", apiToken: "raw-secret" }, context: { ...baseContext, confirmationToken: undefined } })).toMatchObject({ ok: false, error: { code: "precondition_failed" } });
    const first = await dispatcher.dispatch({ operationId: "examplefn.records.delete", input: { id: "1", apiToken: "raw-secret" }, context: baseContext });
    const replay = await dispatcher.dispatch({ operationId: "examplefn.records.delete", input: { id: "1", apiToken: "raw-secret" }, context: { ...baseContext, requestId: "req_2" } });
    expect(first).toMatchObject({ ok: true, data: { deleted: true }, auditId: "audit_1" });
    expect(replay).toMatchObject({ ok: true, meta: { idempotencyReplay: true } });
    expect(handler).toHaveBeenCalledTimes(1); // missing required infrastructure fails before domain execution
    expect(audit.events.at(-1)?.input).toEqual({ id: "1", apiToken: "[REDACTED]" });
    expect(await dispatcher.dispatch({ operationId: "examplefn.records.delete", input: { id: "2", apiToken: "different" }, context: baseContext })).toMatchObject({ ok: false, error: { code: "conflict" } });
  });

