export type KnownModuleId = (typeof KNOWN_MODULE_IDS)[number];
export type ModuleAvailability = 'required-product' | 'optional-product' | 'nested';

export interface ModuleCatalogEntry {
  id: KnownModuleId;
  displayName: string;
  availability: ModuleAvailability;
  owner?: KnownModuleId;
}

const REQUIRED_SET = new Set<string>(REQUIRED_MODULE_IDS);
const OPTIONAL_SET = new Set<string>(OPTIONAL_MODULE_IDS);

const DISPLAY_NAMES: Record<KnownModuleId, string> = {
  apifn: 'ApiFn',
  authfn: 'AuthFn',
  billfn: 'BillFn',
  botfn: 'BotFn',
  browsefn: 'BrowseFn',
  cachefn: 'CacheFn',
  catchfn: 'CatchFn',
  cifn: 'CiFn',
  cmsfn: 'CmsFn',
  compfn: 'CompFn',
  contentfn: 'ContentFn',
  datafn: 'DataFn',
  docsfn: 'DocsFn',
  filefn: 'FileFn',
  flowfn: 'FlowFn',
  hostfn: 'HostFn',
  langfn: 'LangFn',
  logfn: 'LogFn',
  mailfn: 'MailFn',
  memoryfn: 'MemoryFn',
  plugfn: 'PlugFn',
  probefn: 'ProbeFn',
  recfn: 'RecFn',
  searchfn: 'SearchFn',
  secfn: 'SecFn',
  sendfn: 'SendFn',
  testfn: 'TestFn',
  userfn: 'UserFn',
  watchfn: 'WatchFn',
};

export const NESTED_OWNERS = {
  catchfn: 'watchfn',
  contentfn: 'cmsfn',
  logfn: 'watchfn',
} as const satisfies Record<(typeof NESTED_MODULE_IDS)[number], KnownModuleId>;

export const MODULE_CATALOG: readonly ModuleCatalogEntry[] = KNOWN_MODULE_IDS.map((id) => {
  const owner = NESTED_OWNERS[id as keyof typeof NESTED_OWNERS];
  return {
    id,
    displayName: DISPLAY_NAMES[id],
    availability: owner
      ? 'nested'
      : OPTIONAL_SET.has(id)
        ? 'optional-product'
        : 'required-product',
    ...(owner ? { owner } : {}),
  };
});

const KNOWN_SET = new Set<string>(KNOWN_MODULE_IDS);

export class ModuleSelectionError extends Error {
  readonly code = 'SUPERCONSOLE_INVALID_MODULE_SELECTION';

  constructor(message: string, readonly details: Record<string, unknown>) {
    super(message);
    this.name = 'ModuleSelectionError';
  }
}

export function isKnownModuleId(value: string): value is KnownModuleId {
  return KNOWN_SET.has(value);
}

export function parseModuleSelection(value: string | readonly string[] | undefined): KnownModuleId[] {
  if (value === undefined) return [];

  const candidates = (typeof value === 'string' ? value.split(',') : value)
    .map((candidate) => candidate.trim().toLowerCase())
    .filter(Boolean);
  const unknown = [...new Set(candidates.filter((candidate) => !isKnownModuleId(candidate)))];
  if (unknown.length > 0) {
    throw new ModuleSelectionError('The module selection contains unknown Superfunctions.', {
      unknown,
      known: KNOWN_MODULE_IDS,
    });
  }

  const selected = [...new Set(candidates)] as KnownModuleId[];
  const selectedSet = new Set<KnownModuleId>(selected);
  const missingOwners = selected
    .filter((id): id is keyof typeof NESTED_OWNERS => id in NESTED_OWNERS)
    .map((id) => ({ moduleId: id, ownerId: NESTED_OWNERS[id] }))
    .filter(({ ownerId }) => !selectedSet.has(ownerId));
  if (missingOwners.length > 0) {
    throw new ModuleSelectionError('Nested modules require their owning module to be selected.', {
      missingOwners,
    });
  }

  const missingNestedDependencies = selected
    .filter((id) => id === 'watchfn' || id === 'cmsfn')
    .flatMap((ownerId) => {
      const requiredNested = ownerId === 'watchfn'
