  ];
}

function authActionOperation(action: AuthFnAdminActionDefinition): AdminOperationDefinition {
  return {
    id: `authfn.${action.resource}.${action.id}`,
    title: action.title,
    description: action.description,
    inputSchema: authActionInputSchema,
    outputSchema: authActionOutputSchema,
    route: { method: 'POST', path: `/resources/${action.resource}/actions/${action.id}` },
    permission: `authfn.${action.resource}.${action.id}`,
    safety: {
      classification: action.classification,
      idempotent: action.idempotent,
      requiresConfirmation: action.requiresConfirmation,
      audit: 'required'
    },
    mcp: {
      readOnlyHint: false,
      destructiveHint: action.classification === 'destructive',
      idempotentHint: action.idempotent
    }
  };
}

