function appendHeaders(target: Headers, bundle: Record<string, string>): void {
  Object.values(bundle).forEach((cookie) => target.append('set-cookie', cookie));
}

/**
 * Adapts AuthFn's real password, session, API-key, cookie and CSRF primitives to
 * Super Console. The membership-aware operator/scope callbacks remain an
 * application concern and must resolve against the deployment's AuthFn grants.
 */
export function createAuthFnOperatorAuth(options: AuthFnOperatorAuthOptions): SuperConsoleOperatorAuth {
  const config: AuthFnConfig = {
    ...options.config,
    database: wrapWithSchema(options.config.database, getSchema(options.config)),
  };

  return {
    async authenticate(request) {
      const session = await authenticateRequest(config, request);
      return session ? options.resolveOperator({ session, request }) : null;
    },
    async authorizeScope(input) {
      return options.authorizeScope(input);
    },
    async authorizeMutation({ request }) {
      const state = await getCookieSessionState(config, request);
      if (state.session) assertValidCsrf(request, state);
    },
    async signIn({ email, password, request }) {
      const { user } = await signInWithPassword(config, { email, password }, {
        request,
        requireEmailVerifiedForSignIn: options.requireEmailVerifiedForSignIn,
      });
      const issued = await issueSession(config, config.hooks ?? {}, {
        request,
        userId: user.id,
        primaryEmail: user.primaryEmail,
        methods: ['password'],
      });
      const principal = await options.resolveOperator({ session: issued.session, request });
      if (!principal) {
        await revokeSessionById(config, issued.session.id, { userId: user.id });
        throw new Error('The authenticated AuthFn identity is not an authorized Super Console operator.');
      }
      if (!issued.cookiePolicy) throw new Error('AuthFn did not resolve a cookie policy for this request.');
      const headers = new Headers();
      appendHeaders(headers, issueSessionCookies(issued.cookiePolicy, issued.sessionToken, issued.csrfToken));
      return { principal, headers };
    },
    async signOut({ request }) {
      const state = await getCookieSessionState(config, request);
      const headers = new Headers();
      if (state.session) {
        assertValidCsrf(request, state);
        await revokeSessionById(config, state.session.id, { userId: state.session.actorId });
      }
      appendHeaders(headers, clearSessionCookies(state.cookiePolicy));
      return { headers };
    },
  };
}
import type { SuperConsole } from './super-console';

const INSTALLATION = Symbol.for('superfunctions.superconsole.installation.v1');

type InstallationGlobal = typeof globalThis & { [INSTALLATION]?: SuperConsole };

/** Configure one process-local, explicitly composed self-hosted installation. */
export function configureSuperConsole(console: SuperConsole): SuperConsole {
  (globalThis as InstallationGlobal)[INSTALLATION] = console;
  return console;
}

export function getSuperConsole(): SuperConsole | undefined {
  return (globalThis as InstallationGlobal)[INSTALLATION];
}

export function requireSuperConsole(): SuperConsole {
  const console = getSuperConsole();
  if (!console) {
    throw new Error('Super Console is not configured. Call configureSuperConsole(createSuperConsole(...)) during server startup.');
  }
  return console;
}

export function clearSuperConsoleForTesting(): void {
  delete (globalThis as InstallationGlobal)[INSTALLATION];
}

