import {
  AdminError,
  createAdminDispatcher,
  createAdminOpenApiDocument,
  createAdminRegistry,
  normalizeAdminPageLimit,
  normalizeAdminError,
  projectAdminMcpTools,
  type AdminCapabilityManifest,
