import { AdminError } from "./errors.js";
import { stableSerialize } from "./validator.js";
import type { AdminResult, AdminScope } from "./types.js";

export interface AdminIdempotencyIdentity {
  key: string;
  actorId: string;
  scope: AdminScope;
  operationId: string;
}

export interface AdminIdempotencyRecord<T = unknown> {
  identity: AdminIdempotencyIdentity;
  fingerprint: string;
  result: AdminResult<T>;
  auditId?: string;
  createdAt: string;
}

export interface AdminIdempotencyClaim {
  identity: AdminIdempotencyIdentity;
  fingerprint: string;
  token: string;
}

export type AdminIdempotencyBeginResult<T = unknown> =
  | { status: "acquired"; claim: AdminIdempotencyClaim }
  | { status: "replay"; record: AdminIdempotencyRecord<T> }
  | {
      status: "in-progress";
      /** In-process stores may provide completion notification. Distributed stores normally return retryAfterMs. */
      wait?: Promise<AdminIdempotencyRecord<T> | undefined>;
      retryAfterMs?: number;
    };

/**
 * Atomic reservation contract. Durable implementations must make `begin` a
 * compare-and-create operation on the full identity and must fence `complete`
 * with the claim token. Cross-process stores should use a renewable lease or a
 * documented stale-claim recovery policy.
 */
export interface AdminIdempotencyStore {
  begin<T = unknown>(input: {
    identity: AdminIdempotencyIdentity;
    fingerprint: string;
  }): Promise<AdminIdempotencyBeginResult<T>> | AdminIdempotencyBeginResult<T>;
  complete<T = unknown>(
    claim: AdminIdempotencyClaim,
    record: AdminIdempotencyRecord<T>,
  ): Promise<void> | void;
}

export function adminIdempotencyStorageKey(identity: AdminIdempotencyIdentity): string {
  return stableSerialize(identity);
}

export function adminInputFingerprint(input: unknown): string { return stableSerialize(input); }

interface MemoryPendingEntry {
  status: "in-progress";
  fingerprint: string;
  token: string;
  wait: Promise<AdminIdempotencyRecord | undefined>;
  resolve: (record: AdminIdempotencyRecord | undefined) => void;
}

interface MemoryCompletedEntry {
  status: "completed";
  fingerprint: string;
  record: AdminIdempotencyRecord;
}

/** Process-local atomic test/development store. It is not durable or multi-process safe. */
export class MemoryAdminIdempotencyStore implements AdminIdempotencyStore {
  private readonly entries = new Map<string, MemoryPendingEntry | MemoryCompletedEntry>();

  begin<T = unknown>(input: {
    identity: AdminIdempotencyIdentity;
    fingerprint: string;
  }): AdminIdempotencyBeginResult<T> {
    const key = adminIdempotencyStorageKey(input.identity);
    const existing = this.entries.get(key);
    if (existing && existing.fingerprint !== input.fingerprint) {
      throw new AdminError("conflict", "The idempotency key was already used with different input.");
    }
    if (existing?.status === "completed") {
      return { status: "replay", record: structuredClone(existing.record) as AdminIdempotencyRecord<T> };
    }
    if (existing?.status === "in-progress") {
      return { status: "in-progress", wait: existing.wait as Promise<AdminIdempotencyRecord<T> | undefined> };
    }

    let resolve!: (record: AdminIdempotencyRecord | undefined) => void;
    const wait = new Promise<AdminIdempotencyRecord | undefined>((complete) => { resolve = complete; });
    const token = `claim_${crypto.randomUUID()}`;
    this.entries.set(key, { status: "in-progress", fingerprint: input.fingerprint, token, wait, resolve });
    return { status: "acquired", claim: { identity: input.identity, fingerprint: input.fingerprint, token } };
  }

  complete<T = unknown>(claim: AdminIdempotencyClaim, record: AdminIdempotencyRecord<T>): void {
    const key = adminIdempotencyStorageKey(claim.identity);
    const existing = this.entries.get(key);
    if (!existing || existing.status !== "in-progress" || existing.token !== claim.token) {
      throw new AdminError("conflict", "The idempotency reservation is no longer owned by this operation.");
    }
    if (existing.fingerprint !== claim.fingerprint || record.fingerprint !== claim.fingerprint) {
      throw new AdminError("conflict", "The idempotency completion fingerprint does not match its reservation.");
    }
    const snapshot = structuredClone(record) as AdminIdempotencyRecord;
    this.entries.set(key, { status: "completed", fingerprint: claim.fingerprint, record: snapshot });
    existing.resolve(structuredClone(snapshot));
  }
}

export async function beginAdminIdempotency<T>(
  store: AdminIdempotencyStore,
  identity: AdminIdempotencyIdentity,
  input: unknown,
): Promise<
  | { status: "acquired"; claim: AdminIdempotencyClaim }
  | { status: "replay"; record: AdminIdempotencyRecord<T> }
> {
  const fingerprint = adminInputFingerprint(input);
  // A released in-process claim may resolve without a record; retry its atomic begin once observed.
  for (;;) {
    const reservation = await store.begin<T>({ identity, fingerprint });
    if (reservation.status === "acquired" || reservation.status === "replay") return reservation;
    if (!reservation.wait) {
      throw new AdminError("conflict", "An operation with this idempotency key is already in progress.", {
        details: { retryAfterMs: reservation.retryAfterMs },
        retryable: true,
      });
    }
    const record = await reservation.wait;
    if (record) return { status: "replay", record };
  }
}
import type { McpFnObjectSchema, McpFnToolDefinition } from "@mcpfn/core";
import { AdminError } from "./errors.js";
import type { AdminDispatcher } from "./dispatcher.js";
import type { AdminCapabilityRegistry } from "./registry.js";
import type { AdminOperationContext, AdminResult } from "./types.js";

export interface AdminMcpProjectionOptions {
  registry: AdminCapabilityRegistry;
  dispatcher: AdminDispatcher;
}

export interface McpFnCompatibleRegistry<TContext> {
  register(definition: McpFnToolDefinition<TContext>): unknown;
}

function isMcpEnabled(value: unknown): boolean {
  return value !== false && !(value && typeof value === "object" && "enabled" in value && (value as { enabled?: boolean }).enabled === false);
}

function structuredResult(result: AdminResult): { content: { type: "text"; text: string }[]; structuredContent: Record<string, unknown>; isError?: boolean } {
  return {
    content: [{ type: "text", text: JSON.stringify(result) }],
    structuredContent: { result },
    ...(result.ok === false ? { isError: true } : {}),
  };
}

function mcpInputSchema(entry: Parameters<typeof projectAdminMcpTools>[0]["registry"]["operations"][number]): McpFnObjectSchema {
  const input = entry.operation.inputSchema;
  if (!input || input.type !== "object") throw new AdminError("invalid_argument", `MCP operation ${entry.operation.id} requires an object input schema.`);
  if (entry.operation.safety.classification === "read") return input as McpFnObjectSchema;
  if (input.properties?._admin) throw new AdminError("conflict", `Operation ${entry.operation.id} uses the reserved MCP _admin input field.`);
  const required: string[] = [];
  const properties: Record<string, unknown> = {};
  if (entry.operation.safety.idempotent) {
    properties.idempotencyKey = { type: "string", minLength: 1, description: "Unique key for exactly-once administration execution." };
    required.push("idempotencyKey");
  }
  if (entry.operation.safety.requiresConfirmation) {
    properties.confirmationToken = { type: "string", minLength: 1, description: "Explicit confirmation token issued for this destructive operation." };
    required.push("confirmationToken");
  }
  return {
    ...input,
    properties: {
      ...(input.properties ?? {}),
      _admin: {
        type: "object",
        description: "Reserved Super Console mutation controls; removed before domain validation.",
        properties,
        required,
        additionalProperties: false,
      },
    },
    required: [...new Set([...(input.required ?? []), ...(required.length ? ["_admin"] : [])])],
  } as McpFnObjectSchema;
}

export function projectAdminMcpTools(
  options: AdminMcpProjectionOptions,
): McpFnToolDefinition<AdminOperationContext>[] {
  return options.registry.operations.filter((entry) => isMcpEnabled(entry.operation.mcp)).map((entry) => {
    const input = mcpInputSchema(entry);
    const output = entry.operation.outputSchema;
    const configured = typeof entry.operation.mcp === "object" ? entry.operation.mcp : undefined;
    const readOnly = entry.operation.safety.classification === "read";
    return {
      name: configured?.name ?? entry.mcpToolName,
      title: entry.operation.title,
      description: configured?.description ?? `${entry.operation.description} Requires ${entry.operation.permission}; safety=${entry.operation.safety.classification}${entry.operation.safety.requiresConfirmation ? "; explicit confirmation required" : ""}.`,
      inputSchema: input,
      ...(output?.type === "object" ? { outputSchema: output as McpFnObjectSchema } : {}),
      annotations: {
        readOnlyHint: configured?.readOnlyHint ?? readOnly,
        destructiveHint: configured?.destructiveHint ?? entry.operation.safety.classification === "destructive",
        idempotentHint: configured?.idempotentHint ?? Boolean(entry.operation.safety.idempotent),
        openWorldHint: false,
      },
      metadata: {
        "mcpfn/superconsole": {
          moduleId: entry.moduleId,
          operationId: entry.operation.id,
          permission: entry.operation.permission,
          safety: entry.operation.safety,
          capabilityVersion: entry.manifest.version,
        },
      },
      handler: async (args, context) => {
        const { _admin, ...domainInput } = args;
        const controls = _admin && typeof _admin === "object" && !Array.isArray(_admin)
          ? _admin as { idempotencyKey?: unknown; confirmationToken?: unknown }
          : {};
        return structuredResult(await options.dispatcher.dispatch({
          operationId: entry.operation.id,
          input: domainInput,
          context: {
            ...context,
            source: "mcp",
            idempotencyKey: typeof controls.idempotencyKey === "string" ? controls.idempotencyKey : undefined,
            confirmationToken: typeof controls.confirmationToken === "string" ? controls.confirmationToken : undefined,
          },
        }));
      },
    };
  });
}

export function registerAdminMcpTools(
  target: McpFnCompatibleRegistry<AdminOperationContext>,
  options: AdminMcpProjectionOptions,
): McpFnToolDefinition<AdminOperationContext>[] {
  const tools = projectAdminMcpTools(options);
  tools.forEach((tool) => target.register(tool));
  return tools;
}

