  let {
    action,
    compact = false,
  }: { action: AdminActionViewModel; compact?: boolean } = $props();

  let running = $state(false);
  let result = $state<{ ok: boolean; message: string } | undefined>();
  let dialogOpen = $state(false);

  async function runAction() {
    const endpoint = action.apiHref ?? action.href;
    if (!endpoint || action.disabled || running) return;
    running = true;
    result = undefined;
    try {
      const response = await fetchConsole(endpoint, {
        method: action.method ?? 'POST',
        headers: { accept: 'application/json', 'content-type': 'application/json' },
        body: ['GET', 'HEAD'].includes(action.method ?? 'POST') ? undefined : '{}',
      });
      const body = await response.json().catch(() => undefined) as
        | { error?: { message?: string }; message?: string }
        | undefined;
      if (!response.ok) throw new Error(body?.error?.message ?? `HTTP ${response.status}`);
      result = { ok: true, message: body?.message ?? `${action.label} completed.` };
      dialogOpen = false;
      await invalidateAll();
    } catch (cause) {
      result = {
        ok: false,
        message: cause instanceof Error ? cause.message : `${action.label} failed.`,
      };
    } finally {
      running = false;
    }
  }
</script>

