}
<script lang="ts">
  import {
    AlertDialogAction,
    AlertDialogBackdrop,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogPortal,
    AlertDialogPositioner,
    AlertDialogRoot,
    AlertDialogTitle,
    AlertDialogTrigger,
  } from '@uifn/components-svelte/alert-dialog';
  import {
    ButtonLabel,
    ButtonRoot,
    ButtonSpinner,
  } from '@uifn/components-svelte/button';
  import { invalidateAll } from '$app/navigation';
  import { fetchConsole } from './admin-api';
  import type { AdminActionViewModel } from './view-models';

  let {
    action,
    compact = false,
  }: { action: AdminActionViewModel; compact?: boolean } = $props();

  let running = $state(false);
  let result = $state<{ ok: boolean; message: string } | undefined>();
  let dialogOpen = $state(false);

  async function runAction() {
    const endpoint = action.apiHref ?? action.href;
    if (!endpoint || action.disabled || running) return;
    running = true;
    result = undefined;
    try {
      const response = await fetchConsole(endpoint, {
        method: action.method ?? 'POST',
        headers: { accept: 'application/json', 'content-type': 'application/json' },
        body: ['GET', 'HEAD'].includes(action.method ?? 'POST') ? undefined : '{}',
      });
      const body = await response.json().catch(() => undefined) as
        | { error?: { message?: string }; message?: string }
        | undefined;
      if (!response.ok) throw new Error(body?.error?.message ?? `HTTP ${response.status}`);
      result = { ok: true, message: body?.message ?? `${action.label} completed.` };
      dialogOpen = false;
      await invalidateAll();
    } catch (cause) {
      result = {
        ok: false,
        message: cause instanceof Error ? cause.message : `${action.label} failed.`,
      };
    } finally {
      running = false;
    }
  }
</script>

{#if action.requiresConfirmation || action.tone === 'danger'}
  <AlertDialogRoot open={dialogOpen} onOpenChange={(open: boolean) => (dialogOpen = open)}>
    <AlertDialogTrigger
      class={`action-trigger ${action.tone === 'danger' ? 'action-trigger--danger' : ''}`}
      disabled={action.disabled}
    >
      {action.label}
    </AlertDialogTrigger>
    <AlertDialogPortal>
      <AlertDialogBackdrop />
      <AlertDialogPositioner>
        <AlertDialogContent class="confirm-dialog">
          <AlertDialogTitle>{action.label}?</AlertDialogTitle>
          <AlertDialogDescription>
            {action.description ?? 'This operator action is audited and may affect production resources.'}
          </AlertDialogDescription>
          <div class="confirm-dialog__actions">
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onclick={runAction} disabled={running}>
              {running ? 'Working…' : action.label}
            </AlertDialogAction>
          </div>
        </AlertDialogContent>
      </AlertDialogPositioner>
    </AlertDialogPortal>
  </AlertDialogRoot>
{:else}
  <ButtonRoot
    variant="outline"
    size={compact ? 'sm' : 'md'}
    disabled={action.disabled || running}
    loading={running}
    onclick={runAction}
  >
    <ButtonSpinner />
    <ButtonLabel>{action.label}</ButtonLabel>
  </ButtonRoot>
{/if}

{#if result}
  <span class:action-result--error={!result.ok} class="action-result" role="status">
    {result.message}
  </span>
{/if}
