    }
    if (dispatched.ok !== false && moduleId === 'cifn' && rest.at(-1) === 'logs') {
      return response({ ...dispatched, data: { lines: (dispatched.data as { items?: unknown[] }).items ?? [] } }, 200);
    }
    return resultResponse(dispatched);
  }

  private requirePermission(principal: SuperConsolePrincipal, permission: string): void {
    const permissions = principal.actor.permissions ?? [];
    if (!permissions.includes('*') && !permissions.includes(permission)) {
      throw new SuperConsoleHttpError('The active operator lacks the required permission.', { status: 403, code: 'PERMISSION_DENIED' });
    }
  }

  private buildOpenApi() {
    const document = createAdminOpenApiDocument(this.registry, {
      title: `${this.options.serverName ?? 'Super Console'} Administration API`,
      version: '1.0.0',
      description: 'Self-hosted operator administration powered by enabled Superfunctions.',
    });
    Object.assign(document.paths, {
      [`${this.registry.apiBasePath}/registry`]: { get: { operationId: 'superconsole.registry.get', summary: 'Discover enabled modules', responses: { '200': { description: 'Enabled registry' } } } },
      [`${this.registry.apiBasePath}/overview`]: { get: { operationId: 'superconsole.overview.get', summary: 'Read operator overview', responses: { '200': { description: 'Overview' } } } },
      [`${this.registry.apiBasePath}/search`]: { get: { operationId: 'superconsole.search.query', summary: 'Search through SearchFn', responses: { '200': { description: 'Search results' } } } },
  }>;
  permission?: string;
}

