export interface CreateAdminDispatcherOptions {
  registry: AdminCapabilityRegistry;
  policy?: AdminPolicyEvaluator;
  confirmation?: AdminConfirmationVerifier;
  audit?: AdminAuditSink;
  idempotency?: AdminIdempotencyStore;
  createAuditId?: AdminAuditIdFactory;
  now?: () => Date;
}

export interface AdminDispatchRequest {
  operationId: string;
  input: unknown;
  context: AdminOperationContext;
}

export class AdminDispatcher {
  private readonly registry: AdminCapabilityRegistry;
  private readonly policy?: AdminPolicyEvaluator;
  private readonly confirmation?: AdminConfirmationVerifier;
  private readonly audit?: AdminAuditSink;
  private readonly idempotency?: AdminIdempotencyStore;
  private readonly createAuditId: AdminAuditIdFactory;
  private readonly now: () => Date;

  constructor(options: CreateAdminDispatcherOptions) {
    this.registry = options.registry;
    this.policy = options.policy;
    this.confirmation = options.confirmation;
    this.audit = options.audit;
    this.idempotency = options.idempotency;
    this.createAuditId = options.createAuditId ?? createAdminAuditId;
    this.now = options.now ?? (() => new Date());
  }

  async dispatch<T = unknown>(request: AdminDispatchRequest): Promise<AdminResult<T>> {
    const startedAt = this.now();
    let entry: AdminRegistryOperation | undefined;
    let auditId: string | undefined;
    let idempotencyClaim: AdminIdempotencyClaim | undefined;
    let idempotencyIdentity: AdminIdempotencyIdentity | undefined;
    let idempotencyInput: unknown;
    let policyMetadata: Readonly<Record<string, unknown>> | undefined;
    try {
      this.assertContext(request.context);
      entry = this.registry.requireOperation(request.operationId);
      const inputSchema = entry.operation.inputSchema;
      if (!inputSchema) throw new AdminError("internal", `Operation ${entry.operation.id} has no input schema.`);
      assertAdminValue(inputSchema, request.input);

      if (!entry.manifest.scopeLevels.some((level) => this.scopeSupports(level, request.context))) {
        throw new AdminError("forbidden", "The operation is unavailable at the active scope.");
      }
      const decision = this.policy
        ? await this.policy.authorize({ entry, input: request.input, context: request.context })
        : this.defaultPolicy(entry, request.context);
      policyMetadata = decision.metadata;
      if (!decision.allowed) throw new AdminError("forbidden", decision.reason || "The active actor cannot perform this operation.");

      if (entry.operation.safety.requiresConfirmation) {
        const token = request.context.confirmationToken;
        if (!token) throw new AdminError("precondition_failed", "This operation requires explicit confirmation.");
        if (!this.confirmation) {
          throw new AdminError("dependency_unavailable", "Administration confirmation verification is unavailable.");
        }
        if (!(await this.confirmation.verify({ entry, input: request.input, context: request.context, token }))) {
          throw new AdminError("precondition_failed", "The operation confirmation is invalid or expired.");
        }
      }

      if (entry.operation.safety.audit === "required" && !this.audit) {
        throw new AdminError("dependency_unavailable", "A required administration audit sink is unavailable.");
      }

      const identity = this.idempotencyIdentity(entry, request.context);
      if (entry.operation.safety.classification !== "read" && entry.operation.safety.idempotent && !identity) {
        throw new AdminError("precondition_failed", "This operation requires an idempotency key.");
      }
      if (identity && !this.idempotency) {
        throw new AdminError("dependency_unavailable", "Durable administration idempotency storage is unavailable.");
      }
      if (identity && this.idempotency) {
        const reservation = await beginAdminIdempotency<T>(this.idempotency, identity, request.input);
        if (reservation.status === "replay") {
          const prior = reservation.record.result;
          return prior.ok === false
            ? { ...prior, auditId: reservation.record.auditId }
            : { ...prior, auditId: reservation.record.auditId, meta: { ...prior.meta, idempotencyReplay: true } };
        }
        idempotencyClaim = reservation.claim;
        idempotencyIdentity = identity;
        idempotencyInput = request.input;
      }

      const result = await entry.adapter.invoke<T>(entry.operation.id, request.input, request.context);
      const outputSchema = entry.operation.outputSchema;
      if (!outputSchema) throw new AdminError("internal", `Operation ${entry.operation.id} has no output schema.`);
      if (validateAdminValue(outputSchema, result.data).length > 0) {
        throw new AdminError("internal", "The administration service returned an invalid response.");
      }
      const externalData = redactAdminValue(result.data, entry.operation.redaction?.outputFields ?? []) as T;

      if (this.shouldAudit(entry)) {
        auditId = this.createAuditId();
        try {
          await this.writeAudit(entry, request, startedAt, auditId, "succeeded", undefined, policyMetadata);
        } catch (error) {
          if (entry.operation.safety.audit === "required") throw error;
          auditId = undefined;
        }
      }
      const response: AdminOperationResult<T> = {
        ...result,
        data: externalData,
        ok: true,
        requestId: request.context.requestId,
        correlationId: request.context.correlationId,
        ...(auditId ? { auditId } : {}),
      };
      if (idempotencyClaim && idempotencyIdentity && this.idempotency) {
        await this.idempotency.complete(idempotencyClaim, {
          identity: idempotencyIdentity,
          fingerprint: adminInputFingerprint(idempotencyInput),
          result: response,
          auditId,
          createdAt: this.now().toISOString(),
        });
      }
      return response;
    } catch (error) {
      const normalized = normalizeAdminError(error, {
        requestId: request.context?.requestId,
        correlationId: request.context?.correlationId,
      });
      if (entry && this.shouldAudit(entry) && this.audit) {
        const failureAuditId = auditId ?? this.createAuditId();
        try {
          await this.writeAudit(
            entry,
            request,
            startedAt,
            failureAuditId,
            normalized.error.code === "forbidden" ? "denied" : "failed",
            normalized.error.code,
            policyMetadata,
          );
          auditId = failureAuditId;
        } catch {
          // The original safe error remains authoritative; deployments observe audit sink failures separately.
        }
      }
      const failedResult = auditId ? { ...normalized, auditId } : normalized;
      if (idempotencyClaim && idempotencyIdentity && this.idempotency) {
        try {
          await this.idempotency.complete(idempotencyClaim, {
            identity: idempotencyIdentity,
            fingerprint: adminInputFingerprint(idempotencyInput),
            result: failedResult,
            auditId,
            createdAt: this.now().toISOString(),
          });
        } catch {
          // Preserve the operation error. Durable stores retain/fence unresolved claims for recovery.
        }
      }
      return failedResult;
    }
  }

  private assertContext(context: AdminOperationContext): void {
    if (!context?.actor?.id) throw new AdminError("unauthenticated", "An authenticated administration actor is required.");
    if (!context.requestId || !context.source) throw new AdminError("invalid_argument", "Request identity and source are required.");
    const required = ["organizationId", "workspaceId", "projectId", "environmentId"] as const;
    for (const key of required) if (!context.scope?.[key]) throw new AdminError("invalid_argument", `Administration scope requires ${key}.`);
  }

  private scopeSupports(level: "organization" | "workspace" | "project" | "environment", context: AdminOperationContext): boolean {
    return level === "organization" ? Boolean(context.scope.organizationId)
      : level === "workspace" ? Boolean(context.scope.workspaceId)
      : level === "project" ? Boolean(context.scope.projectId)
      : Boolean(context.scope.environmentId);
  }

  private defaultPolicy(entry: AdminRegistryOperation, context: AdminOperationContext): AdminPolicyDecision {
    const permissions = context.actor.permissions ?? [];
    return { allowed: permissions.includes("*") || permissions.includes(entry.operation.permission) };
  }

  private idempotencyIdentity(entry: AdminRegistryOperation, context: AdminOperationContext): AdminIdempotencyIdentity | undefined {
    if (!context.idempotencyKey || !entry.operation.safety.idempotent) return undefined;
    return { key: context.idempotencyKey, actorId: context.actor.id, scope: context.scope, operationId: entry.operation.id };
  }

  private shouldAudit(entry: AdminRegistryOperation): boolean {
    return entry.operation.safety.audit === "required" || (entry.operation.safety.audit === "optional" && Boolean(this.audit));
  }

  private async writeAudit(
    entry: AdminRegistryOperation,
    request: AdminDispatchRequest,
    startedAt: Date,
    auditId: string,
    outcome: "succeeded" | "failed" | "denied" | "replayed",
    errorCode?: string,
    metadata?: Readonly<Record<string, unknown>>,
  ): Promise<void> {
    if (!this.audit) {
      if (entry.operation.safety.audit === "required") throw new AdminError("dependency_unavailable", "A required administration audit sink is unavailable.");
      return;
    }
    await this.audit.write({
      id: auditId,
      timestamp: this.now().toISOString(),
      actorId: request.context.actor.id,
      actorType: request.context.actor.type,
      scope: request.context.scope,
      moduleId: entry.moduleId,
      operationId: entry.operation.id,
      classification: entry.operation.safety.classification,
      permission: entry.operation.permission,
      source: request.context.source,
      requestId: request.context.requestId,
      correlationId: request.context.correlationId,
      idempotencyKey: request.context.idempotencyKey,
      input: redactAdminValue(request.input, entry.operation.redaction?.inputFields ?? []),
      outcome,
      errorCode,
      durationMs: Math.max(0, this.now().getTime() - startedAt.getTime()),
      metadata,
    });
  }
}

export function createAdminDispatcher(options: CreateAdminDispatcherOptions): AdminDispatcher {
  return new AdminDispatcher(options);
}
import { AdminError } from "./errors.js";
import type {
  AdminCapabilityManifest,
  AdminJsonSchema,
  AdminOperationDefinition,
} from "./types.js";

export interface AdminValidationIssue {
  path: string;
  message: string;
  keyword?: string;
}

const ID_PATTERN = /^[a-z][a-z0-9-]*(?:\.[a-z0-9-]+)*$/;
const MODULE_PATTERN = /^[a-z][a-z0-9-]*$/;

function valueType(value: unknown): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  if (Number.isInteger(value)) return "integer";
  return typeof value;
}

function allowedTypes(schema: AdminJsonSchema): string[] {
  if (!schema.type) return [];
  return typeof schema.type === "string" ? [schema.type] : [...schema.type];
}

export function validateAdminValue(
  schema: AdminJsonSchema,
  value: unknown,
  path = "$",
): AdminValidationIssue[] {
  const issues: AdminValidationIssue[] = [];
  if (schema.const !== undefined && !Object.is(schema.const, value)) {
    issues.push({ path, message: "must equal the declared constant", keyword: "const" });
  }
  if (schema.enum && !schema.enum.some((candidate) => Object.is(candidate, value))) {
    issues.push({ path, message: "must be one of the declared values", keyword: "enum" });
  }

  const types = allowedTypes(schema);
  if (types.length > 0) {
    const actual = valueType(value);
    const matches = types.includes(actual) || (actual === "integer" && types.includes("number"));
    if (!matches) {
      return [{ path, message: `must be ${types.join(" or ")}`, keyword: "type" }];
    }
  }

  if (typeof value === "string") {
    if (schema.minLength !== undefined && value.length < schema.minLength) {
      issues.push({ path, message: `must contain at least ${schema.minLength} characters`, keyword: "minLength" });
    }
    if (schema.maxLength !== undefined && value.length > schema.maxLength) {
      issues.push({ path, message: `must contain at most ${schema.maxLength} characters`, keyword: "maxLength" });
    }
    if (schema.pattern && !new RegExp(schema.pattern).test(value)) {
      issues.push({ path, message: "does not match the required pattern", keyword: "pattern" });
    }
  }

  if (typeof value === "number") {
    if (schema.minimum !== undefined && value < schema.minimum) {
      issues.push({ path, message: `must be at least ${schema.minimum}`, keyword: "minimum" });
    }
    if (schema.maximum !== undefined && value > schema.maximum) {
      issues.push({ path, message: `must be at most ${schema.maximum}`, keyword: "maximum" });
    }
  }

  if (Array.isArray(value)) {
    if (schema.minItems !== undefined && value.length < schema.minItems) {
      issues.push({ path, message: `must contain at least ${schema.minItems} items`, keyword: "minItems" });
    }
    if (schema.maxItems !== undefined && value.length > schema.maxItems) {
      issues.push({ path, message: `must contain at most ${schema.maxItems} items`, keyword: "maxItems" });
    }
    if (schema.uniqueItems) {
      const keys = value.map(stableSerialize);
      if (new Set(keys).size !== keys.length) issues.push({ path, message: "must contain unique items", keyword: "uniqueItems" });
    }
    if (schema.items && !Array.isArray(schema.items)) {
      value.forEach((item, index) => issues.push(...validateAdminValue(schema.items as AdminJsonSchema, item, `${path}[${index}]`)));
    }
  }

  if (value !== null && typeof value === "object" && !Array.isArray(value)) {
    const object = value as Record<string, unknown>;
    for (const key of schema.required ?? []) {
      if (!(key in object)) issues.push({ path: `${path}.${key}`, message: "is required", keyword: "required" });
    }
    for (const [key, item] of Object.entries(object)) {
      const propertySchema = schema.properties?.[key];
      if (propertySchema) {
        issues.push(...validateAdminValue(propertySchema, item, `${path}.${key}`));
      } else if (schema.additionalProperties === false) {
        issues.push({ path: `${path}.${key}`, message: "is not allowed", keyword: "additionalProperties" });
      } else if (schema.additionalProperties && typeof schema.additionalProperties === "object") {
        issues.push(...validateAdminValue(schema.additionalProperties, item, `${path}.${key}`));
      }
    }
  }

  if (schema.allOf) for (const candidate of schema.allOf) issues.push(...validateAdminValue(candidate, value, path));
  if (schema.anyOf && !schema.anyOf.some((candidate) => validateAdminValue(candidate, value, path).length === 0)) {
    issues.push({ path, message: "must match at least one allowed schema", keyword: "anyOf" });
  }
  if (schema.oneOf && schema.oneOf.filter((candidate) => validateAdminValue(candidate, value, path).length === 0).length !== 1) {
    issues.push({ path, message: "must match exactly one allowed schema", keyword: "oneOf" });
  }
  return issues;
}

export function assertAdminValue(schema: AdminJsonSchema, value: unknown, label = "input"): void {
  const issues = validateAdminValue(schema, value);
  if (issues.length > 0) {
    throw new AdminError("invalid_argument", `Invalid administration ${label}.`, { details: { issues } });
  }
}

function stableSerialize(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stableSerialize).join(",")}]`;
  if (value && typeof value === "object") {
    return `{${Object.entries(value as Record<string, unknown>).sort(([a], [b]) => a.localeCompare(b)).map(([key, item]) => `${JSON.stringify(key)}:${stableSerialize(item)}`).join(",")}}`;
  }
  return JSON.stringify(value) ?? "undefined";
}

function operationSchemas(operation: AdminOperationDefinition): [AdminJsonSchema, AdminJsonSchema] {
  const input = operation.inputSchema;
  const output = operation.outputSchema;
  if (!input || !output) throw new AdminError("invalid_argument", `Operation ${operation.id} must declare inputSchema and outputSchema.`);
  return [input, output];
}

function normalizedRoute(operation: AdminOperationDefinition): string {
  const raw = typeof operation.route === "string"
    ? operation.route.trim()
    : `${operation.route.method} ${operation.route.path}`;
  return raw
    .replace(/:([A-Za-z_][A-Za-z0-9_]*)/g, ":param")
    .replace(/\{([A-Za-z_][A-Za-z0-9_]*)\}/g, ":param");
}

export function validateAdminCapabilityManifest(manifest: AdminCapabilityManifest): AdminValidationIssue[] {
  const issues: AdminValidationIssue[] = [];
  if (manifest.schemaVersion !== "1.0") issues.push({ path: "$.schemaVersion", message: "must be 1.0" });
  if (!MODULE_PATTERN.test(manifest.id)) issues.push({ path: "$.id", message: "must be a stable lowercase module identifier" });
  if (!manifest.displayName.trim()) issues.push({ path: "$.displayName", message: "must not be empty" });
  if (!manifest.version.trim()) issues.push({ path: "$.version", message: "must not be empty" });
  if (manifest.scopeLevels.length === 0) issues.push({ path: "$.scopeLevels", message: "must contain at least one supported level" });
  if (manifest.availability === "nested" && !manifest.owner) issues.push({ path: "$.owner", message: "is required for nested modules" });
  if (manifest.availability !== "nested" && manifest.owner) issues.push({ path: "$.owner", message: "is only valid for nested modules" });
  const ids = new Set<string>();
  const routes = new Set<string>();
  manifest.operations.forEach((operation, index) => {
    if (!ID_PATTERN.test(operation.id) || !operation.id.startsWith(`${manifest.id}.`)) {
      issues.push({ path: `$.operations[${index}].id`, message: `must be namespaced with ${manifest.id}.` });
    }
    if (ids.has(operation.id)) issues.push({ path: `$.operations[${index}].id`, message: "duplicates another operation" });
    ids.add(operation.id);
    const route = normalizedRoute(operation);
    if (routes.has(route)) issues.push({ path: `$.operations[${index}].route`, message: "duplicates another route" });
    routes.add(route);
    if (!operation.permission.trim()) issues.push({ path: `$.operations[${index}].permission`, message: "must not be empty" });
    if (operation.safety.classification !== "read" && operation.safety.audit !== "required") {
      issues.push({ path: `$.operations[${index}].safety.audit`, message: "mutations must require audit" });
    }
    if (operation.safety.classification === "destructive" && !operation.safety.requiresConfirmation) {
      issues.push({ path: `$.operations[${index}].safety.requiresConfirmation`, message: "destructive operations must require confirmation" });
    }
    if (operation.safety.classification === "destructive" && !operation.target) {
      issues.push({ path: `$.operations[${index}].target`, message: "destructive operations must declare an exact target" });
    }
    for (const [kind, fields] of Object.entries(operation.redaction ?? {})) {
      const normalized = (fields ?? []).map((field) => field.trim().toLowerCase());
      if (normalized.some((field) => !field)) issues.push({ path: `$.operations[${index}].redaction.${kind}`, message: "must not contain blank field names" });
      if (new Set(normalized).size !== normalized.length) issues.push({ path: `$.operations[${index}].redaction.${kind}`, message: "must contain unique case-insensitive field names" });
    }
    if (operation.target) {
      if (!operation.target.resource.trim()) issues.push({ path: `$.operations[${index}].target.resource`, message: "must not be blank" });
      if (operation.target.idInput !== undefined && !operation.target.idInput.trim()) issues.push({ path: `$.operations[${index}].target.idInput`, message: "must not be blank" });
      if (operation.safety.classification === "destructive") {
        if (!operation.target.idInput) {
          issues.push({ path: `$.operations[${index}].target.idInput`, message: "destructive targets must declare an idInput" });
        } else if (!operation.inputSchema?.required?.includes(operation.target.idInput)) {
          issues.push({ path: `$.operations[${index}].inputSchema.required`, message: "must require the destructive target idInput" });
        }
      }
    }
    if (operation.mcp && typeof operation.mcp === "object") {
      const expectedRead = operation.safety.classification === "read";
      const expectedDestructive = operation.safety.classification === "destructive";
      if (operation.mcp.readOnlyHint !== undefined && operation.mcp.readOnlyHint !== expectedRead) issues.push({ path: `$.operations[${index}].mcp.readOnlyHint`, message: "must match the operation safety classification" });
      if (operation.mcp.destructiveHint !== undefined && operation.mcp.destructiveHint !== expectedDestructive) issues.push({ path: `$.operations[${index}].mcp.destructiveHint`, message: "must match the operation safety classification" });
      if (operation.mcp.idempotentHint !== undefined && operation.mcp.idempotentHint !== Boolean(operation.safety.idempotent)) issues.push({ path: `$.operations[${index}].mcp.idempotentHint`, message: "must match the operation idempotency declaration" });
    }
    try { operationSchemas(operation); } catch (error) {
      issues.push({ path: `$.operations[${index}]`, message: error instanceof Error ? error.message : "schemas are invalid" });
    }
  });
  return issues;
}

export function assertAdminCapabilityManifest(manifest: AdminCapabilityManifest): void {
  const issues = validateAdminCapabilityManifest(manifest);
  if (issues.length > 0) throw new AdminError("invalid_argument", `Invalid admin capability manifest: ${manifest.id}.`, { details: { issues } });
}

