    const fetcher = vi.fn(async (_input: RequestInfo | URL, init?: RequestInit) => {
      expect(new Headers(init?.headers).get('x-authfn-csrf')).toBe('csrf_token/1');
      expect(init?.credentials).toBe('same-origin');
