import { AdminError } from "./errors.js";
import type { AdminCapabilityRegistry, AdminRegistryOperation } from "./registry.js";
import type { AdminJsonSchema, AdminObjectSchema } from "./types.js";

export interface AdminOpenApiOptions {
  title?: string;
  version?: string;
  description?: string;
  serverUrl?: string;
  securitySchemes?: Readonly<Record<string, unknown>>;
}

export interface AdminOpenApiDocument {
  openapi: "3.1.0";
  info: { title: string; version: string; description?: string };
  servers?: readonly { url: string }[];
  paths: Record<string, Record<string, unknown>>;
  components: Record<string, unknown>;
  tags: readonly Record<string, unknown>[];
  [extension: `x-${string}`]: unknown;
}

const ERROR_SCHEMA: AdminObjectSchema = {
  type: "object",
  properties: {
    ok: { type: "boolean", const: false },
    error: {
      type: "object",
      properties: {
        code: { type: "string" },
        message: { type: "string" },
        status: { type: "integer" },
        details: {},
        retryable: { type: "boolean" },
      },
      required: ["code", "message", "status"],
      additionalProperties: false,
    },
    requestId: { type: "string" },
    correlationId: { type: "string" },
  },
  required: ["ok", "error"],
  additionalProperties: false,
};

function route(entry: AdminRegistryOperation): { method: string; path: string; parameterNames: string[] } {
  const method = typeof entry.operation.route === "string"
    ? entry.operation.route.trim().split(/\s+/, 1)[0]!.toUpperCase()
    : entry.operation.route.method;
  const parameterNames: string[] = [];
  const path = entry.routePath
    .replace(/:([A-Za-z_][A-Za-z0-9_]*)/g, (_, name: string) => { parameterNames.push(name); return `{${name}}`; })
    .replace(/\{([A-Za-z_][A-Za-z0-9_]*)\}/g, (_, name: string) => { if (!parameterNames.includes(name)) parameterNames.push(name); return `{${name}}`; });
  return { method, path, parameterNames };
}

function withoutProperties(schema: AdminJsonSchema, names: readonly string[]): AdminJsonSchema | undefined {
  if (schema.type !== "object" || !schema.properties) return schema;
  const properties = Object.fromEntries(Object.entries(schema.properties).filter(([name]) => !names.includes(name)));
  if (Object.keys(properties).length === 0) return undefined;
  return { ...schema, properties, required: schema.required?.filter((name) => !names.includes(name)) };
}

function parametersFor(schema: AdminJsonSchema, parameterNames: readonly string[], includeQuery: boolean): Record<string, unknown>[] {
  const parameters: Record<string, unknown>[] = [];
  for (const name of parameterNames) {
    parameters.push({ name, in: "path", required: true, schema: schema.properties?.[name] ?? { type: "string" } });
  }
  if (includeQuery && schema.type === "object") {
    for (const [name, property] of Object.entries(schema.properties ?? {})) {
      if (!parameterNames.includes(name)) parameters.push({ name, in: "query", required: schema.required?.includes(name) ?? false, schema: property });
    }
  }
  return parameters;
}

export function createAdminOpenApiDocument(
  registry: AdminCapabilityRegistry,
  options: AdminOpenApiOptions = {},
): AdminOpenApiDocument {
  const paths: Record<string, Record<string, unknown>> = {};
  for (const entry of registry.operations) {
    const { method, path, parameterNames } = route(entry);
    const input = entry.operation.inputSchema;
    const output = entry.operation.outputSchema;
    if (!input || !output) throw new AdminError("internal", `Operation ${entry.operation.id} has incomplete schemas.`);
    const isReadMethod = method === "GET" || method === "DELETE";
    const parameters = parametersFor(input, parameterNames, isReadMethod);
    const bodySchema = isReadMethod ? undefined : withoutProperties(input, parameterNames);
    const successSchema: AdminObjectSchema = {
      type: "object",
      properties: {
        ok: { type: "boolean", const: true },
        data: output,
        requestId: { type: "string" },
        correlationId: { type: "string" },
        auditId: { type: "string" },
      },
      required: ["ok", "data"],
      additionalProperties: true,
    };
    const operation: Record<string, unknown> = {
      operationId: entry.operation.id,
      summary: entry.operation.title,
      description: entry.operation.description,
      tags: [entry.manifest.displayName],
      security: [{ authFnSession: [] }, { authFnApiKey: [] }],
      ...(parameters.length ? { parameters } : {}),
      ...(bodySchema ? { requestBody: { required: true, content: { "application/json": { schema: bodySchema } } } } : {}),
      responses: {
        "200": { description: "Administration operation completed.", content: { "application/json": { schema: successSchema } } },
        "4XX": { description: "Administration request rejected.", content: { "application/json": { schema: { $ref: "#/components/schemas/AdminError" } } } },
        "5XX": { description: "Administration dependency or server failure.", content: { "application/json": { schema: { $ref: "#/components/schemas/AdminError" } } } },
      },
      "x-superfunctions-module": entry.moduleId,
      "x-superfunctions-capability-version": entry.manifest.version,
      "x-superfunctions-permission": entry.operation.permission,
      "x-superfunctions-safety": entry.operation.safety,
      ...(entry.operation.pagination ? { "x-superfunctions-pagination": entry.operation.pagination } : {}),
      ...(entry.operation.target ? { "x-superfunctions-target": entry.operation.target } : {}),
      ...(entry.operation.redaction ? { "x-superfunctions-redaction": entry.operation.redaction } : {}),
    };
    paths[path] ??= {};
    if (paths[path]![method.toLowerCase()]) throw new AdminError("conflict", `OpenAPI operation collision: ${method} ${path}.`);
    paths[path]![method.toLowerCase()] = operation;
  }

  return {
    openapi: "3.1.0",
    info: {
      title: options.title ?? "Super Console Administration API",
      version: options.version ?? "1.0.0",
      ...(options.description ? { description: options.description } : {}),
    },
    ...(options.serverUrl ? { servers: [{ url: options.serverUrl }] } : {}),
    paths,
    components: {
      schemas: { AdminError: ERROR_SCHEMA },
      securitySchemes: options.securitySchemes ?? {
        authFnSession: { type: "apiKey", in: "cookie", name: "authfn_session" },
        authFnApiKey: { type: "apiKey", in: "header", name: "Authorization" },
      },
    },
    tags: registry.manifests.map((manifest) => ({
      name: manifest.displayName,
      description: manifest.description,
      "x-superfunctions-module": manifest.id,
      ...(manifest.owner ? { "x-superfunctions-owner": manifest.owner } : {}),
    })),
    "x-superfunctions-enabled-modules": registry.enabledModuleIds,
    "x-superfunctions-registry-schema": "1.0",
  };
}

export const generateAdminOpenApi = createAdminOpenApiDocument;
import { AdminError } from "./errors.js";
import { assertAdminCapabilityManifest } from "./validator.js";
import type {
  AdminCapabilityAdapter,
  AdminCapabilityManifest,
  AdminNavigationDefinition,
  AdminOperationDefinition,
} from "./types.js";

export interface AdminRegistryOperation {
  moduleId: string;
  manifest: AdminCapabilityManifest;
  adapter: AdminCapabilityAdapter;
  operation: AdminOperationDefinition;
  routePath: string;
  mcpToolName: string;
}

export interface CreateAdminRegistryOptions {
  adapters: readonly AdminCapabilityAdapter[];
  /** Explicit allowlist. Omission enables every supplied adapter for small embedded deployments. */
  enabledModules: readonly string[];
  apiBasePath?: string;
}

function dependenciesOf(manifest: AdminCapabilityManifest): string[] {
  const dependencies = (manifest.dependencies ?? []).flatMap((dependency) => {
    if (typeof dependency === "string") return [dependency];
    return dependency.required === false ? [] : [dependency.moduleId];
  });
  if (manifest.owner) dependencies.push(manifest.owner.moduleId);
  return [...new Set(dependencies)];
}

function routeOf(operation: AdminOperationDefinition): { method: string; path: string } {
  if (typeof operation.route === "string") {
    const match = /^(GET|POST|PUT|PATCH|DELETE)\s+(.+)$/i.exec(operation.route.trim());
    if (!match) throw new AdminError("invalid_argument", `Invalid route for ${operation.id}.`);
    return { method: match[1]!.toUpperCase(), path: match[2]! };
  }
  return operation.route;
}

export function adminMcpToolName(operationId: string): string {
  return `superconsole_${operationId.replace(/[^a-zA-Z0-9]+/g, "_").replace(/^_+|_+$/g, "")}`.toLowerCase();
}

export class AdminCapabilityRegistry {
  readonly apiBasePath: string;
  readonly manifests: readonly AdminCapabilityManifest[];
  readonly operations: readonly AdminRegistryOperation[];
  readonly enabledModuleIds: readonly string[];
  readonly navigation: readonly { moduleId: string; ownerModuleId?: string; item: AdminNavigationDefinition }[];
  private readonly adaptersById: ReadonlyMap<string, AdminCapabilityAdapter>;
  private readonly operationsById: ReadonlyMap<string, AdminRegistryOperation>;
  private readonly operationsByRoute: ReadonlyMap<string, AdminRegistryOperation>;
  private readonly operationsByTool: ReadonlyMap<string, AdminRegistryOperation>;

  constructor(options: CreateAdminRegistryOptions) {
    const basePath = `/${options.apiBasePath?.replace(/^\/+|\/+$/g, "") || "api/admin/v1"}`;
    const supplied = new Map<string, AdminCapabilityAdapter>();
    for (const adapter of options.adapters) {
      assertAdminCapabilityManifest(adapter.manifest);
      if (supplied.has(adapter.manifest.id)) throw new AdminError("conflict", `Duplicate admin module: ${adapter.manifest.id}.`);
      supplied.set(adapter.manifest.id, adapter);
    }

    if (!Array.isArray(options.enabledModules)) {
      throw new AdminError("invalid_argument", "Admin registry requires an explicit enabledModules allowlist.");
    }
    const requested = [...new Set(options.enabledModules)];
    for (const moduleId of requested) {
      if (!supplied.has(moduleId)) throw new AdminError("dependency_unavailable", `Enabled admin module is not registered: ${moduleId}.`);
    }
    const enabled = new Set(requested);
    for (const moduleId of requested) {
      const manifest = supplied.get(moduleId)!.manifest;
      for (const dependency of dependenciesOf(manifest)) {
        if (!enabled.has(dependency)) {
          throw new AdminError("dependency_unavailable", `Admin module ${moduleId} requires enabled module ${dependency}.`, {
            details: { moduleId, dependency },
          });
        }
      }
    }

    const visiting = new Set<string>();
    const visited = new Set<string>();
    const ordered: string[] = [];
    const visit = (moduleId: string, path: string[]): void => {
      if (visiting.has(moduleId)) throw new AdminError("conflict", `Admin module dependency cycle: ${[...path, moduleId].join(" -> ")}.`);
      if (visited.has(moduleId)) return;
      visiting.add(moduleId);
      for (const dependency of dependenciesOf(supplied.get(moduleId)!.manifest)) visit(dependency, [...path, moduleId]);
      visiting.delete(moduleId);
      visited.add(moduleId);
      ordered.push(moduleId);
    };
    requested.forEach((moduleId) => visit(moduleId, []));

    const operationIds = new Map<string, AdminRegistryOperation>();
    const routes = new Map<string, AdminRegistryOperation>();
    const tools = new Map<string, AdminRegistryOperation>();
    for (const moduleId of ordered) {
      const adapter = supplied.get(moduleId)!;
      for (const operation of adapter.manifest.operations) {
        const route = routeOf(operation);
        const suffix = route.path.startsWith("/") ? route.path : `/${route.path}`;
        const routePath = `${basePath}/modules/${moduleId}${suffix}`;
        const routeKey = `${route.method} ${normalizeRoutePattern(routePath)}`;
        const mcpToolName = adminMcpToolName(operation.id);
        const entry: AdminRegistryOperation = { moduleId, manifest: adapter.manifest, adapter, operation, routePath, mcpToolName };
        if (operationIds.has(operation.id)) throw new AdminError("conflict", `Duplicate admin operation ID: ${operation.id}.`);
        if (routes.has(routeKey)) throw new AdminError("conflict", `Duplicate admin route: ${routeKey}.`);
        if (tools.has(mcpToolName)) throw new AdminError("conflict", `Duplicate admin MCP tool: ${mcpToolName}.`);
        operationIds.set(operation.id, entry);
        routes.set(routeKey, entry);
        tools.set(mcpToolName, entry);
      }
    }

    const navigation = ordered.flatMap((moduleId) => {
      const manifest = supplied.get(moduleId)!.manifest;
      const definitions = manifest.navigation ? (Array.isArray(manifest.navigation) ? manifest.navigation : [manifest.navigation]) : [];
      return definitions.map((item) => ({ moduleId, ...(manifest.owner ? { ownerModuleId: manifest.owner.moduleId } : {}), item }));
    }).sort((left, right) => (left.item.order ?? 0) - (right.item.order ?? 0) || left.item.label.localeCompare(right.item.label));

    this.apiBasePath = basePath;
    this.enabledModuleIds = Object.freeze(ordered);
    this.manifests = Object.freeze(ordered.map((moduleId) => supplied.get(moduleId)!.manifest));
    this.operations = Object.freeze([...operationIds.values()]);
    this.navigation = Object.freeze(navigation) as typeof this.navigation;
    this.adaptersById = supplied;
    this.operationsById = operationIds;
    this.operationsByRoute = routes;
    this.operationsByTool = tools;
  }

  hasModule(moduleId: string): boolean { return this.enabledModuleIds.includes(moduleId); }
  getManifest(moduleId: string): AdminCapabilityManifest | undefined {
    return this.hasModule(moduleId) ? this.adaptersById.get(moduleId)?.manifest : undefined;
  }
  requireManifest(moduleId: string): AdminCapabilityManifest {
    const manifest = this.getManifest(moduleId);
    if (!manifest || !this.hasModule(moduleId)) throw new AdminError("not_found", `Admin module is not enabled: ${moduleId}.`);
    return manifest;
  }
  getOperation(operationId: string): AdminRegistryOperation | undefined { return this.operationsById.get(operationId); }
  requireOperation(operationId: string): AdminRegistryOperation {
    const operation = this.getOperation(operationId);
    if (!operation) throw new AdminError("not_found", `Admin operation is not enabled: ${operationId}.`);
    return operation;
  }
  matchRoute(method: string, path: string): AdminRegistryOperation | undefined {
    return this.operationsByRoute.get(`${method.toUpperCase()} ${normalizeRoutePattern(path)}`)
      ?? this.operations.find((entry) => routeMatches(entry.operation, entry.routePath, method, path));
  }
  matchMcpTool(toolName: string): AdminRegistryOperation | undefined { return this.operationsByTool.get(toolName); }
  toJSON(): { schemaVersion: "1.0"; enabledModules: readonly AdminCapabilityManifest[] } {
    return { schemaVersion: "1.0", enabledModules: this.manifests };
  }
}

function normalizeRoutePattern(path: string): string {
  return path.replace(/:[A-Za-z_][A-Za-z0-9_]*/g, ":param").replace(/\{[A-Za-z_][A-Za-z0-9_]*\}/g, ":param");
}

function routeMatches(operation: AdminOperationDefinition, pattern: string, method: string, path: string): boolean {
  const operationMethod = typeof operation.route === "string" ? operation.route.trim().split(/\s+/, 1)[0] : operation.route.method;
  if (operationMethod?.toUpperCase() !== method.toUpperCase()) return false;
  const patternParts = pattern.split("/").filter(Boolean);
  const pathParts = path.split("?")[0]!.split("/").filter(Boolean);
  return patternParts.length === pathParts.length && patternParts.every((part, index) =>
    part.startsWith(":") || /^\{[^}]+\}$/.test(part) || part === pathParts[index]);
}

export function createAdminRegistry(options: CreateAdminRegistryOptions): AdminCapabilityRegistry {
  return new AdminCapabilityRegistry(options);
}
import type {
  AdminCapabilityManifest,
  AdminOperationContext,
  AdminResult,
} from "./types.js";

export interface AdminClientOptions {
  baseUrl: string;
  fetch?: typeof fetch;
  headers?: HeadersInit | (() => HeadersInit | Promise<HeadersInit>);
  context?: Partial<Pick<AdminOperationContext, "idempotencyKey" | "confirmationToken">>;
}

export interface AdminClientRequestOptions {
  signal?: AbortSignal;
  headers?: HeadersInit;
  idempotencyKey?: string;
  confirmationToken?: string;
}

export class AdminClientError extends Error {
  readonly status: number;
  readonly response?: AdminResult;
  constructor(message: string, status: number, response?: AdminResult) {
    super(message);
    this.name = "AdminClientError";
    this.status = status;
    this.response = response;
  }
}

function joinUrl(baseUrl: string, path: string): string {
  return `${baseUrl.replace(/\/+$/, "")}/${path.replace(/^\/+/, "")}`;
}

function encodeQuery(input: unknown): string {
  if (!input || typeof input !== "object" || Array.isArray(input)) return "";
  const query = new URLSearchParams();
  for (const [key, value] of Object.entries(input as Record<string, unknown>)) {
    if (value === undefined) continue;
    query.set(key, typeof value === "string" ? value : JSON.stringify(value));
  }
  const serialized = query.toString();
  return serialized ? `?${serialized}` : "";
}

export class AdminClient {
  private readonly baseUrl: string;
  private readonly fetcher: typeof fetch;
  private readonly configuredHeaders?: AdminClientOptions["headers"];
  private readonly defaults: AdminClientOptions["context"];

  constructor(options: AdminClientOptions) {
    this.baseUrl = options.baseUrl;
    this.fetcher = options.fetch ?? globalThis.fetch;
    if (!this.fetcher) throw new Error("AdminClient requires a fetch implementation.");
    this.configuredHeaders = options.headers;
    this.defaults = options.context;
  }

  async registry(options?: AdminClientRequestOptions): Promise<AdminCapabilityManifest[]> {
    const response = await this.request<{ enabledModules: AdminCapabilityManifest[] }>("GET", "registry", undefined, options);
    return response.enabledModules;
  }

  async openApi(options?: AdminClientRequestOptions): Promise<Record<string, unknown>> {
    return this.request("GET", "openapi.json", undefined, options);
  }

  async invoke<T = unknown>(
    moduleId: string,
    route: { method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE"; path: string },
    input?: unknown,
    options?: AdminClientRequestOptions,
  ): Promise<AdminResult<T>> {
    const path = `modules/${encodeURIComponent(moduleId)}${route.path.startsWith("/") ? route.path : `/${route.path}`}`;
    return this.request<AdminResult<T>>(route.method, path, input, options, false);
  }

  async invokeOperation<T = unknown>(
    operationId: string,
    input?: unknown,
    options?: AdminClientRequestOptions,
  ): Promise<AdminResult<T>> {
    return this.request<AdminResult<T>>(
      "POST",
      `operations/${encodeURIComponent(operationId)}`,
      input ?? {},
      options,
      false,
    );
  }

  private async request<T>(
    method: string,
    path: string,
    input?: unknown,
    options: AdminClientRequestOptions = {},
    unwrap = true,
  ): Promise<T> {
    const configured = typeof this.configuredHeaders === "function" ? await this.configuredHeaders() : this.configuredHeaders;
    const headers = new Headers(configured);
    new Headers(options.headers).forEach((value, key) => headers.set(key, value));
    headers.set("accept", "application/json");
    const idempotencyKey = options.idempotencyKey ?? this.defaults?.idempotencyKey;
    const confirmationToken = options.confirmationToken ?? this.defaults?.confirmationToken;
    if (idempotencyKey) headers.set("idempotency-key", idempotencyKey);
    if (confirmationToken) headers.set("x-admin-confirmation", confirmationToken);
    const isQuery = method === "GET" || method === "DELETE";
    if (!isQuery && input !== undefined) headers.set("content-type", "application/json");
    const response = await this.fetcher(joinUrl(this.baseUrl, `${path}${isQuery ? encodeQuery(input) : ""}`), {
      method,
      headers,
      signal: options.signal,
      ...(isQuery || input === undefined ? {} : { body: JSON.stringify(input) }),
    });
    const payload = await response.json().catch(() => undefined) as T | AdminResult | undefined;
    if (!response.ok) {
      const result = payload && typeof payload === "object" && "ok" in payload ? payload as AdminResult : undefined;
      throw new AdminClientError(result && result.ok === false ? result.error.message : `Administration request failed with HTTP ${response.status}.`, response.status, result);
    }
    if (unwrap && payload && typeof payload === "object" && "ok" in payload && (payload as AdminResult).ok !== false) {
      return (payload as { data: T }).data;
    }
    return payload as T;
  }
}

export function createAdminClient(options: AdminClientOptions): AdminClient { return new AdminClient(options); }
import type { AdminOperationError } from "./types.js";

export type AdminErrorCode =
  | "invalid_argument"
  | "unauthenticated"
  | "forbidden"
  | "not_found"
  | "conflict"
  | "rate_limited"
  | "precondition_failed"
  | "dependency_unavailable"
  | "internal";

const STATUS_BY_CODE: Record<AdminErrorCode, number> = {
  invalid_argument: 400,
  unauthenticated: 401,
  forbidden: 403,
  not_found: 404,
  conflict: 409,
  precondition_failed: 412,
  rate_limited: 429,
  dependency_unavailable: 503,
  internal: 500,
};

export class AdminError extends Error {
  readonly code: AdminErrorCode;
  readonly status: number;
  readonly details?: unknown;
  readonly retryable: boolean;

  constructor(
    code: AdminErrorCode,
    message: string,
    options: { status?: number; details?: unknown; retryable?: boolean; cause?: unknown } = {},
  ) {
    super(message, { cause: options.cause });
    this.name = "AdminError";
    this.code = code;
    this.status = options.status ?? STATUS_BY_CODE[code];
    this.details = options.details;
    this.retryable = options.retryable ?? (code === "rate_limited" || code === "dependency_unavailable");
  }
}

export function normalizeAdminError(
  error: unknown,
  identity: { requestId?: string; correlationId?: string } = {},
): AdminOperationError {
  const normalized = error instanceof AdminError
    ? error
    : new AdminError("internal", "The administration operation could not be completed.", { cause: error });
  return {
    ok: false,
    error: {
      code: normalized.code,
      message: normalized.message,
      status: normalized.status,
      ...(normalized.details === undefined ? {} : { details: normalized.details }),
      retryable: normalized.retryable,
    },
    ...identity,
  };
}

# REST and OpenAPI

## Base paths

- Administration API: `/api/admin/v1`
- Capability discovery: `/api/admin/v1/registry`
- Installation overview: `/api/admin/v1/overview`
- Enabled module operations: `/api/admin/v1/modules/{moduleId}/...`
- Global search: `/api/admin/v1/search`
- Audit stream/query: `/api/admin/v1/audit`
- Installation and module settings: `/api/admin/v1/settings`
- MCP discovery/configuration: `/api/admin/v1/mcp`
- OpenAPI 3.1 document: `/api/admin/v1/openapi.json`

Only enabled operations appear in routing and OpenAPI.

## Scope

Canonical scope is carried in route or validated headers according to the deployment adapter. The normalized context contains workspace, project, environment, optional function namespace, and optional region. An installation may bind workspace to organization terminology without changing API field identity.

Scope values are never trusted merely because they were sent by a client. AuthFn membership and the function's object-level authorization are evaluated for each request.

## Envelopes

Success:

```json
{
  "ok": true,
  "data": {},
  "page": { "nextCursor": null, "hasMore": false },
  "requestId": "req_...",
  "auditId": "audit_..."
}
```

Failure:

```json
{
  "ok": false,
  "error": {
    "code": "forbidden",
    "message": "The active actor cannot perform this operation.",
    "issues": [],
    "retryable": false
  },
  "requestId": "req_..."
}
```

`auditId` is returned for mutations whose execution reached audit recording, including audited failures. Secret or private domain payloads never appear in generic errors.

## Pagination, filtering, and sorting

- Cursor pagination is stable under the resource's declared ordering.
- Default and maximum page sizes are operation metadata.
- Filters and sort keys are enumerated by the manifest and reflected in OpenAPI.
- Unknown filters and sorts are validation errors rather than silently ignored.
- Cursors are opaque and scope-bound.

## Idempotency and concurrency

- Operations marked idempotent accept `Idempotency-Key`.
- Keys are scoped to actor, tenant, module, operation, and normalized request identity.
- Repeated matching requests return the stored outcome and original audit reference.
- Reusing a key for different input returns conflict.
- Operations that expose optimistic concurrency use an ETag or declared version token and `If-Match`.

## Authentication

Interactive requests use AuthFn sessions. Automation uses scoped service credentials or API keys. The OpenAPI document declares configured security schemes but never embeds credentials. CSRF rules remain active for cookie-authenticated mutations.

## OpenAPI projection

The generator emits OpenAPI 3.1 with:

- one tag per enabled module and nested grouping metadata;
- deterministic operation IDs;
- request, response, page, error, and audit schemas;
- security schemes and per-operation permissions;
- scope, confirmation, idempotency, safety, and deprecation extensions;
- module and capability versions;
- disabled modules omitted from paths and components when safe to do so.

Contract tests compare registry operations, paths, OpenAPI operation IDs, SDK methods, and MCP tools.

## Versioning

`v1` is the transport major version. Function capability versions are returned independently. A breaking transport change uses a new base path. Additive capability changes remain in the same transport version. Deprecations declare replacement and sunset metadata but do not fabricate dates when no policy exists.
# TypeScript admin SDK

## Purpose

The TypeScript client consumes the versioned REST API. It does not import SvelteKit or server domain implementations and can be used by Node, Bun, edge runtimes, browsers with an authorized proxy/session, scripts, and tests.

## Client model

Construction accepts:

- base URL;
- AuthFn-compatible authentication provider or explicit header callback;
- default workspace, project, environment, namespace, and region;
- fetch implementation;
- timeout and retry policy;
- user agent/client metadata;
- request and correlation ID factories.

Clients are immutable. `client.withScope(...)` returns a new scoped client rather than mutating global state.

## Surfaces

- `client.registry()` discovers enabled capabilities.
- `client.module(id)` creates a capability-aware dynamic module client.
- generated or composed typed module accessors expose stable operation methods.
- `client.pages(...)` and async iterators handle cursor pagination.
- `client.audit(...)`, `client.search(...)`, and `client.overview()` expose shared platform capabilities.
- `client.raw(...)` is an escape hatch that still applies authentication, scope, request IDs, errors, and abort behavior.

## Mutations

Mutation options support:

- idempotency key;
- optimistic version/ETag;
- explicit confirmation token when required by capability metadata;
- abort signal and timeout;
- correlation ID;
- dry-run only when the domain operation actually supports it.

The returned result exposes `auditId`, `requestId`, replay/deduplication status, and safe warnings in addition to domain data.

## Errors

The SDK throws typed normalized errors with status, code, message, issues, retryability, request ID, audit ID, and safe details. It preserves response access through the raw escape hatch without leaking authentication material into serialization.

Retry policy is conservative:

- safe reads may retry transient connection and dependency failures;
- mutations retry only when the operation is declared idempotent and an idempotency key is present;
- authentication, authorization, validation, not-found, and conflict errors are not automatically retried.

## Capability typing

The SDK can ship static types for known Superfunction manifests while runtime discovery determines which are enabled. A disabled module produces a capability-unavailable error before a request when discovery is loaded, but server not-found behavior remains authoritative.

## Verification

Contract tests assert that:

- every SDK method maps to one enabled registry operation;
- path, method, schema, scope, and idempotency metadata match OpenAPI;
- normalized errors and audit IDs survive decoding;
- disabled modules are not exposed by runtime capability access;
- authentication callbacks and scope headers are applied consistently.
# MCP through McpFn

## Role of McpFn

McpFn is the protocol and conformance layer for agent administration. It is not a separate dashboard. Super Console projects eligible operations from the enabled registry into McpFn manifests and server handlers.

## Tool projection

Each eligible operation yields a deterministic namespaced tool:

```text
superconsole_<module>_<resource>_<action>
```

The tool description includes the domain purpose, active scope, required permission, safety level, idempotency behavior, confirmation requirement, and deprecation status. Input JSON schema is derived from the same capability schema used by REST/OpenAPI.

Disabled modules and operations marked `mcp: false` do not appear in discovery.

## Invocation

McpFn authenticates the client or resolves a session-bound actor, constructs the canonical request context, and invokes the shared dispatcher. A tool cannot call a function adapter directly. Therefore MCP cannot bypass:

- AuthFn authentication;
- workspace/project/environment membership;
- namespace and region scope;
- operation and object-level authorization;
- schema validation;
- confirmation and idempotency;
- audit and observation emission;
- secret redaction.

## Mutations

Mutations are permitted because the user explicitly selected full API/MCP administration. They are controlled as follows:

- safety metadata is present in tool annotations and descriptions;
- sensitive and destructive tools require explicit confirmation input or host confirmation according to capability policy;
- idempotent mutations require or generate an exposed key the caller can safely reuse;
- irreversible bulk actions use narrow schemas and bounded selection rather than unscoped query strings;
- results include request and audit identifiers;
- raw secrets are accepted only by a schema designed for that secret and are never echoed.

## Resources and prompts

Where useful, McpFn may expose read-only resources for registry metadata, module health, OpenAPI, and audit records. Prompts may guide investigation workflows, but prompts never grant permission or substitute for operation handlers.

## Naming and compatibility

Tool names remain stable within a capability major version. Renames use deprecation metadata and a replacement tool during the compatibility window. The McpFn manifest records registry and function capability versions so clients can diff installations.

## Conformance

Verification covers:

- discovery contains only enabled modules;
- tool schema and operation metadata match OpenAPI;
- OAuth/API-key/session authentication through supported McpFn profiles;
- tenant and object-level policy denial;
- read and mutation results;
- confirmation, idempotency replay, and audit correlation;
- normalized and protocol-safe errors;
- secret redaction and bounded output.

import { buttonTailwindClasses } from '@uifn/recipes';
import { PUBLIC_TOKEN_GROUPS } from '@uifn/tokens';

export type TailwindErrorCode = 'UIFN_TAILWIND_DYNAMIC_CLASS_UNSAFE';

export class UIFnTailwindError extends Error {
  readonly name = 'UIFnTailwindError';
  readonly code: TailwindErrorCode;
  readonly details?: Record<string, unknown>;

  constructor(code: TailwindErrorCode, message: string, details?: Record<string, unknown>) {
    super(message);
    Object.setPrototypeOf(this, new.target.prototype);
    this.code = code;
    this.details = details;
  }
}

export interface TailwindPresetOptions {
  themeSelectors?: string[];
}

export interface TailwindPresetOutput {
  theme: {
    extend: {
      colors: Record<string, string>;
    };
  };
  safelist: string[];
  plugins: UIFnTailwindPlugin[];
}

export interface TailwindPluginApi {
  addUtilities: (utilities: Record<string, Record<string, string>>) => void;
}

/**
 * Tailwind accepts plugin objects with a `handler` function. Keep the named
 * utility map on the object as public, inspectable metadata for build tools
 * and tests while also returning a preset Tailwind can execute directly.
 */
export interface UIFnTailwindPlugin {
  name: string;
  utilities: Record<string, Record<string, string>>;
  handler: (api: TailwindPluginApi) => void;
  config: Record<string, never>;
}

const UNSAFE_DYNAMIC_FRAGMENT_PATTERN = /\$\{|computed|`|\+|:\$\{|hover:\$\{|hover:\{|\[object Object\]/;
const BUTTON_VARIANTS = ['primary', 'secondary', 'ghost', 'danger'] as const;
const BUTTON_SIZES = ['sm', 'md', 'lg'] as const;
const HOVER_CLASSES = ['uifn-hover--tint', 'uifn-hover--stripe', 'uifn-hover--border', 'uifn-hover--lift', 'uifn-hover--none'] as const;

function createSemanticColorMap(): Record<string, string> {
  return Object.fromEntries(
    Object.entries(PUBLIC_TOKEN_GROUPS.color).flatMap(([group, names]) =>
      names.map((name) => [`uifn-${group}-${name}`, `var(--uifn-color-${group}-${name})`])
    )
  );
}

function createUtilitiesPlugin(
  name: string,
  utilities: Record<string, Record<string, string>>
): UIFnTailwindPlugin {
  return {
    name,
    utilities,
    handler({ addUtilities }) {
      addUtilities(utilities);
    },
    config: {},
  };
}

export function assertSafeTailwindClassFragments(fragments: string[]): void {
  fragments.forEach((fragment) => {
    if (UNSAFE_DYNAMIC_FRAGMENT_PATTERN.test(fragment)) {
      throw new UIFnTailwindError(
        'UIFN_TAILWIND_DYNAMIC_CLASS_UNSAFE',
        'Tailwind class fragments must be statically discoverable.',
        {
          fragment,
        }
      );
    }
  });
}

export function createTailwindPreset(options: TailwindPresetOptions = {}): TailwindPresetOutput {
  const selectors = options.themeSelectors ?? [
    '[data-uifn-theme="uifn-light"]',
    '[data-uifn-theme="uifn-dark"]',
    '[data-uifn-theme="uifn-high-contrast-light"]',
    '[data-uifn-theme="uifn-high-contrast-dark"]',
  ];
  const button = buttonTailwindClasses({ variant: 'primary', hoverEffect: 'tint' });
  const safelist = [
    'uifn-button',
    ...BUTTON_VARIANTS.map((variant) => `uifn-button--${variant}`),
    ...BUTTON_SIZES.map((size) => `uifn-button--${size}`),
    ...HOVER_CLASSES,
    'uifn-surface',
  ];

  assertSafeTailwindClassFragments([...safelist, button.className]);

  return {
    theme: {
      extend: {
        colors: createSemanticColorMap(),
      },
    },
    safelist,
    plugins: [
      createUtilitiesPlugin('uifn-recipes', {
        '.uifn-surface': {
          color: 'var(--uifn-color-text-primary)',
          backgroundColor: 'var(--uifn-surface, var(--uifn-color-surface-canvas))',
        },
        '.uifn-button': {
          color: 'var(--uifn-button-foreground, var(--uifn-color-text-primary))',
          backgroundColor: 'var(--uifn-button-surface)',
          borderRadius: 'var(--uifn-button-radius, var(--uifn-radius-md))',
          transitionDuration: 'var(--uifn-motion-duration-fast)',
          transitionTimingFunction: 'var(--uifn-motion-easing-standard)',
        },
        '.uifn-button--primary': { '--uifn-button-surface': 'var(--uifn-color-accent-solid)' },
        '.uifn-button--secondary': { '--uifn-button-surface': 'var(--uifn-color-surface-raised)' },
        '.uifn-button--ghost': { '--uifn-button-surface': 'transparent' },
        '.uifn-button--danger': { '--uifn-button-surface': 'var(--uifn-color-danger-solid)' },
        '.uifn-button--sm': { '--uifn-button-density': 'var(--uifn-density-compact)' },
        '.uifn-button--md': { '--uifn-button-density': 'var(--uifn-density-comfortable)' },
        '.uifn-button--lg': { '--uifn-button-density': 'var(--uifn-density-spacious)' },
        '.uifn-hover--tint': { '--uifn-hover-effect': 'tint' },
        '.uifn-hover--stripe': { '--uifn-hover-effect': 'stripe' },
        '.uifn-hover--border': { '--uifn-hover-effect': 'border' },
        '.uifn-hover--lift': { '--uifn-hover-effect': 'lift' },
        '.uifn-hover--none': { '--uifn-hover-effect': 'none' },
      }),
      createUtilitiesPlugin(
        'uifn-theme-selectors',
        Object.fromEntries(selectors.map((selector) => [selector, {}]))
      ),
    ],
  };
}

export function buttonTailwindOutput() {
  const output = buttonTailwindClasses({ variant: 'primary', hoverEffect: 'tint' });
  assertSafeTailwindClassFragments([output.className]);
  return output;
}

