import type {
  AdminErrorViewModel,
  AdminModuleViewModel,
  OverviewViewModel,
  RegistryViewModel,
  ShellViewModel,
} from './view-models';

export const ADMIN_API_PREFIX = '/api/admin/v1';
export const ADMIN_SCOPE_QUERY_KEYS = [
  'organizationId',
  'workspaceId',
  'projectId',
  'environmentId',
] as const;

export type AdminFetch = (
  input: RequestInfo | URL,
  init?: RequestInit
) => Promise<Response>;

const SAFE_HTTP_METHODS = new Set(['GET', 'HEAD', 'OPTIONS']);

function readableCookies(): string | undefined {
  return typeof document === 'undefined' ? undefined : document.cookie;
}

/**
 * Resolves AuthFn's readable double-submit token. Session cookies are HTTP-only,
 * so the CSRF cookie itself is the browser-side source of truth.
 */
export function authFnCsrfToken(cookieHeader = readableCookies()): string | undefined {
  if (!cookieHeader) return undefined;
  const candidates: Array<{ name: string; value: string }> = [];
  for (const part of cookieHeader.split(';')) {
    const [rawName, ...rawValue] = part.trim().split('=');
    if (!rawName.endsWith('.csrf')) continue;
    const encoded = rawValue.join('=');
    try {
      candidates.push({ name: rawName, value: decodeURIComponent(encoded) });
    } catch {
      candidates.push({ name: rawName, value: encoded });
    }
  }
  return candidates.find((candidate) => candidate.name === 'authfn.csrf')?.value
    ?? candidates[0]?.value;
}

/** Same-origin console transport with AuthFn CSRF propagation for mutations. */
export async function fetchConsole(
  input: RequestInfo | URL,
  init: RequestInit = {},
  fetcher: AdminFetch = globalThis.fetch
): Promise<Response> {
  const headers = new Headers(init.headers);
  const method = (init.method ?? 'GET').toUpperCase();
  if (!SAFE_HTTP_METHODS.has(method) && !headers.has('x-authfn-csrf')) {
    const token = authFnCsrfToken();
    if (token) headers.set('x-authfn-csrf', token);
  }
  return fetcher(input, {
    ...init,
    method,
    headers,
    credentials: 'same-origin',
  });
}

export type AdminApiResult<T> =
  | { ok: true; data: T; requestId?: string }
  | { ok: false; error: AdminErrorViewModel };

export function withAdminScope(path: string, scope?: URLSearchParams): string {
  if (!scope) return path;
  const url = new URL(path, 'http://superconsole.local');
  for (const key of ADMIN_SCOPE_QUERY_KEYS) {
    const legacyKey = key.slice(0, -2);
    const value = scope.get(key) ?? scope.get(legacyKey);
    if (value) url.searchParams.set(key, value);
  }
  return `${url.pathname}${url.search}${url.hash}`;
}

export function scopedConsoleHref(path: string, current: URLSearchParams): string {
  return withAdminScope(path, current);
}

