import { describe, expect, it } from "vitest";
import { createAdminCapabilityAdapter } from "./adapter.js";
import { AdminError } from "./errors.js";
import { createAdminRegistry } from "./registry.js";
import { testAdapter, testManifest } from "./test-fixtures.js";
import { validateAdminCapabilityManifest } from "./validator.js";

describe("AdminCapabilityRegistry", () => {
  it("exposes only explicitly enabled modules and permits a shell-only install", () => {
    const first = testAdapter("firstfn");
    const second = testAdapter("secondfn");
    const registry = createAdminRegistry({ adapters: [first, second], enabledModules: ["secondfn"] });
    expect(registry.enabledModuleIds).toEqual(["secondfn"]);
    expect(registry.operations.every((entry) => entry.moduleId === "secondfn")).toBe(true);
    expect(registry.navigation.map((entry) => entry.moduleId)).toEqual(["secondfn"]);
    expect(registry.getManifest("firstfn")).toBeUndefined();
    expect(createAdminRegistry({ adapters: [first], enabledModules: [] }).operations).toEqual([]);
  });

  it("fails closed when the explicit allowlist is missing at runtime", () => {
    expect(() => createAdminRegistry({ adapters: [] } as never)).toThrowError(/explicit enabledModules/);
  });

  it("orders dependencies before dependents and requires nested owners", () => {
    const owner = testAdapter("ownerfn");
    const nested = testAdapter("nestedfn", {
      availability: "nested",
      owner: { moduleId: "ownerfn", mountPath: "nested" },
      dependencies: ["ownerfn"],
    });
    expect(() => createAdminRegistry({ adapters: [owner, nested], enabledModules: ["nestedfn"] })).toThrowError(/requires enabled module ownerfn/);
    const registry = createAdminRegistry({ adapters: [nested, owner], enabledModules: ["nestedfn", "ownerfn"] });
    expect(registry.enabledModuleIds).toEqual(["ownerfn", "nestedfn"]);
    expect(registry.navigation.find((entry) => entry.moduleId === "nestedfn")?.ownerModuleId).toBe("ownerfn");
  });

  it("detects dependency cycles", () => {
    const first = testAdapter("firstfn", { dependencies: ["secondfn"] });
    const second = testAdapter("secondfn", { dependencies: ["firstfn"] });
    expect(() => createAdminRegistry({ adapters: [first, second], enabledModules: ["firstfn", "secondfn"] })).toThrowError(/dependency cycle/);
  });

  it("detects operation and parameter-equivalent route collisions", () => {
    const manifest = testManifest("examplefn");
    const operation = manifest.operations[0]!;
    const invalid = testManifest("examplefn", {
      operations: [
        { ...operation, id: "examplefn.records.first", route: { method: "GET", path: "/records/:id" } },
        { ...operation, id: "examplefn.records.second", route: { method: "GET", path: "/records/{recordId}" } },
      ],
    });
    expect(validateAdminCapabilityManifest(invalid)).toContainEqual(expect.objectContaining({ message: "duplicates another route" }));
    expect(() => createAdminRegistry({
      adapters: [createAdminCapabilityAdapter(invalid, {})],
      enabledModules: ["examplefn"],
    })).toThrow(AdminError);
  });

  it("matches concrete paths against parameterized registry routes", () => {
    const manifest = testManifest("examplefn");
    const operation = manifest.operations[0]!;
    const adapter = createAdminCapabilityAdapter(testManifest("examplefn", {
      operations: [{ ...operation, route: { method: "GET", path: "/records/:id" } }],
    }), { [operation.id]: async () => ({ data: { items: [] } }) });
    const registry = createAdminRegistry({ adapters: [adapter], enabledModules: ["examplefn"] });
    expect(registry.matchRoute("GET", "/api/admin/v1/modules/examplefn/records/record-1")?.operation.id).toBe(operation.id);
  });
});

describe("manifest validation", () => {
  it("rejects unsafe destructive operations", () => {
    const manifest = testManifest("examplefn");
    const invalid = testManifest("examplefn", {
      operations: [{
        ...manifest.operations[0]!,
        safety: { classification: "destructive", idempotent: true, audit: "optional", requiresConfirmation: false },
      }],
    });
    const issues = validateAdminCapabilityManifest(invalid);
    expect(issues.map((issue) => issue.message)).toEqual(expect.arrayContaining([
      "mutations must require audit",
      "destructive operations must require confirmation",
    ]));
  });
});

