  private async moduleRequest(request: Request, relative: string, state: SuperConsoleRequestState): Promise<Response> {
    const [, encodedModuleId, ...rest] = relative.split('/');
    const moduleId = decodeURIComponent(encodedModuleId ?? '');
    if (!this.registry.hasModule(moduleId)) throw new SuperConsoleHttpError(`${moduleId || 'The requested module'} is not enabled.`, { status: 404, code: 'MODULE_NOT_ENABLED' });
    if (rest.length === 0 && (request.method === 'GET' || request.method === 'HEAD')) {
      const manifest = this.registry.requireManifest(moduleId);
      const entries = this.registry.operations.filter((entry) => entry.moduleId === moduleId);
      return this.headAware(request, success({
        module: moduleView(manifest, entries),
        summary: [
          { id: 'resources', label: 'Resources', value: new Set(entries.map(resourceId)).size },
          { id: 'operations', label: 'Operations', value: entries.length },
        ],
        notices: [],
      }, state.context.requestId));
    }

    const url = new URL(request.url);
    let matchedPath = url.pathname;
    let entry = this.registry.matchRoute(request.method, matchedPath);
    if (!entry && rest[0] !== 'resources') {
      const aliasPath = `${this.registry.apiBasePath}/modules/${encodeURIComponent(moduleId)}/resources/${rest.join('/')}`;
      entry = this.registry.matchRoute(request.method, aliasPath);
      if (entry) matchedPath = aliasPath;
    }
    let aliasInput: Record<string, unknown> = {};
    if (!entry && moduleId === 'cifn' && request.method === 'GET') {
      const artifactMatch = /^runs\/([^/]+)\/artifacts$/.exec(rest.join('/'));
      const logMatch = /^runs\/([^/]+)\/jobs\/([^/]+)\/logs$/.exec(rest.join('/'));
      if (artifactMatch) {
        entry = this.registry.getOperation('cifn.artifacts.list');
        aliasInput = { filter: { runId: decodeURIComponent(artifactMatch[1]!) } };
      } else if (logMatch) {
        entry = this.registry.getOperation('cifn.logs.list');
        aliasInput = { filter: { runId: decodeURIComponent(logMatch[1]!), jobKey: decodeURIComponent(logMatch[2]!) } };
      }
    }
    if (!entry) {
      const methodExists = this.registry.operations.some((candidate) => candidate.moduleId === moduleId &&
        this.registry.matchRoute(routeDefinition(candidate.operation).method, matchedPath)?.operation.id === candidate.operation.id);
      if (methodExists) throw new SuperConsoleHttpError('This module operation does not support the requested method.', { status: 405, code: 'METHOD_NOT_ALLOWED' });
    }
    if (!entry || entry.moduleId !== moduleId) throw new SuperConsoleHttpError('The requested module operation is not enabled.', { status: 404, code: 'OPERATION_NOT_ENABLED' });
    const input = { ...(await operationInput(request, entry, matchedPath)), ...aliasInput };
    const dispatched = await this.dispatcher.dispatch({ operationId: entry.operation.id, input, context: state.context });
    if (dispatched.ok !== false && moduleId === 'cifn' && rest.at(-1) === 'artifacts') {
      return response({ ...dispatched, data: { artifacts: (dispatched.data as { items?: unknown[] }).items ?? [] } }, 200);
    }
    if (dispatched.ok !== false && moduleId === 'cifn' && rest.at(-1) === 'logs') {
      return response({ ...dispatched, data: { lines: (dispatched.data as { items?: unknown[] }).items ?? [] } }, 200);
    }
    return resultResponse(dispatched);
  }

  private requirePermission(principal: SuperConsolePrincipal, permission: string): void {
    const permissions = principal.actor.permissions ?? [];
    if (!permissions.includes('*') && !permissions.includes(permission)) {
      throw new SuperConsoleHttpError('The active operator lacks the required permission.', { status: 403, code: 'PERMISSION_DENIED' });
    }
  }

  private async authorizeShell(surface: 'registry' | 'overview' | 'api' | 'mcp' | 'settings' | 'audit' | 'search', state: SuperConsoleRequestState): Promise<void> {
    if (!(await this.options.shellPolicy.authorize({ surface, principal: state.principal, context: state.context }))) {
      throw new SuperConsoleHttpError('The active operator cannot access this administration surface.', { status: 403, code: 'PERMISSION_DENIED' });
    }
  }

  private async authorizedSurfaces(state: SuperConsoleRequestState) {
    const policy = async (surface: 'overview' | 'api' | 'mcp' | 'settings' | 'audit' | 'search') =>
      this.options.shellPolicy.authorize({ surface, principal: state.principal, context: state.context });
    const hasPermission = (permission?: string) => !permission
      || state.principal.actor.permissions?.includes('*')
      || state.principal.actor.permissions?.includes(permission)
      || false;
    const [overview, api, mcp, settings, audit, search] = await Promise.all([
      policy('overview'),
      policy('api'),
      policy('mcp'),
      policy('settings'),
      policy('audit'),
      policy('search'),
    ]);
    return {
      overview: Boolean(overview) && hasPermission(this.options.overview?.permission),
      api: Boolean(api),
      mcp: Boolean(mcp) && this.mcpTools.length > 0,
      settings: Boolean(settings) && hasPermission(this.options.settings?.permission),
      audit: Boolean(audit) && Boolean(this.options.auditQuery) && hasPermission(this.options.auditQuery?.permission),
      search: Boolean(search) && this.registry.hasModule('searchfn') && Boolean(this.options.search) && hasPermission(this.options.search?.permission),
    };
  }

  private buildOpenApi() {
    const document = createAdminOpenApiDocument(this.registry, {
      title: `${this.options.serverName ?? 'Super Console'} Administration API`,
      version: '1.0.0',
      description: 'Self-hosted operator administration powered by enabled Superfunctions.',
    });
    Object.assign(document.paths, {
      [`${this.registry.apiBasePath}/registry`]: { get: { operationId: 'superconsole.registry.get', summary: 'Discover enabled modules', responses: { '200': { description: 'Enabled registry' } } } },
      [`${this.registry.apiBasePath}/overview`]: { get: { operationId: 'superconsole.overview.get', summary: 'Read operator overview', responses: { '200': { description: 'Overview' } } } },
      [`${this.registry.apiBasePath}/search`]: { get: { operationId: 'superconsole.search.query', summary: 'Search through SearchFn', responses: { '200': { description: 'Search results' } } } },
      [`${this.registry.apiBasePath}/audit`]: { get: { operationId: 'superconsole.audit.list', summary: 'Query the audit stream', responses: { '200': { description: 'Audit events' } } } },
      [`${this.registry.apiBasePath}/settings`]: { get: { operationId: 'superconsole.settings.get', summary: 'Read deployment settings', responses: { '200': { description: 'Settings' } } } },
      [`${this.registry.apiBasePath}/mcp`]: { get: { operationId: 'superconsole.mcp.get', summary: 'Read McpFn tool metadata', responses: { '200': { description: 'MCP metadata' } } } },
      [`${this.registry.apiBasePath}/confirmations`]: { post: { operationId: 'superconsole.confirmations.issue', summary: 'Issue an actor/scope/operation/input-bound confirmation token', responses: { '201': { description: 'Confirmation receipt' } } } },
    });
    return document;
  }
