async function envelope(response: Response): Promise<AuthFnEnvelope> {
  return response.clone().json().catch(() => ({})) as Promise<AuthFnEnvelope>;
}

function throwAuthResponse(response: Response, payload: AuthFnEnvelope): never {
  const error = new Error(payload.error?.message ?? 'AuthFn rejected the authentication request.') as Error & {
    authFnResponse?: Response;
    authFnCode?: string;
    authFnStatus?: number;
  };
  error.name = 'SuperConsoleAuthFnResponseError';
  error.authFnResponse = response;
  error.authFnCode = payload.error?.code;
  error.authFnStatus = response.status;
  throw error;
}

async function resolveSuccessfulOperator(
  authFn: ReturnType<typeof createAuthFn>,
  options: AuthFnOperatorAuthOptions,
  upstream: Response,
  payload: AuthFnEnvelope,
  request: Request,
): Promise<SuperConsoleSignInResult> {
  if (!upstream.ok || payload.ok === false || !payload.data?.session) throwAuthResponse(upstream, payload);
  const principal = await options.resolveOperator({ session: payload.data.session, request });
  if (!principal) {
    await authFn.revokeSession(payload.data.session.id, { userId: payload.data.session.actorId });
    const denied = new Response(JSON.stringify({
      ok: false,
      error: {
        code: 'SUPERCONSOLE_OPERATOR_FORBIDDEN',
        message: 'The authenticated identity is not an authorized Super Console operator.',
        status: 403,
      },
      requestId: payload.requestId,
    }), { status: 403, headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' } });
    throwAuthResponse(denied, await envelope(denied));
  }
  return { principal, headers: upstream.headers };
}

/**
 * Uses AuthFn's composed router for sign-in/sign-out, preserving plugins,
 * hooks, rate limits, 2FA challenge semantics, CSRF and cookie behavior.
 */
export function createAuthFnOperatorAuth(options: AuthFnOperatorAuthOptions): SuperConsoleOperatorAuth {
  const config = options.config;
  const authFn = createAuthFn(config);
  const basePath = config.basePath ?? '/auth';

  return {
    async authenticate(request) {
      const session = await authFn.provider.authenticate(request);
      return session ? options.resolveOperator({ session, request }) : null;
    },
    async authorizeScope(input) {
      return options.authorizeScope(input);
    },
    async authorizeMutation({ request }) {
      await authFn.authorizeMutation(request);
    },
    async signIn({ email, password, request }) {
      const upstream = await authFn.router.handle(authRequest(request, `${basePath}/sign-in/password`, {
        email,
        password,
        sessionMode: 'cookie',
      }));
      const payload = await envelope(upstream);
      // A 2FA-required response is non-success and contains no session/cookies;
      // preserve it as an AuthFn response instead of issuing a Console session.
      return resolveSuccessfulOperator(authFn, options, upstream, payload, request);
    },
    async completeTwoFactor({ challengeId, code, request }) {
      const upstream = await authFn.router.handle(authRequest(request, `${basePath}/2fa/challenge`, { challengeId, code }));
      const payload = await envelope(upstream);
      return resolveSuccessfulOperator(authFn, options, upstream, payload, request);
    },
    async signOut({ request }) {
      const upstream = await authFn.router.handle(authRequest(request, `${basePath}/sign-out`, {}));
      const payload = await envelope(upstream);
      if (!upstream.ok || payload.ok === false) throwAuthResponse(upstream, payload);
      return { headers: upstream.headers };
    },
  };
}

export function isAuthFnResponseError(error: unknown): error is Error & { authFnResponse: Response } {
  return error instanceof Error
    && error.name === 'SuperConsoleAuthFnResponseError'
    && 'authFnResponse' in error
    && error.authFnResponse instanceof Response;
}

  private async signIn(request: Request, requestId: string): Promise<Response> {
    if (request.method !== 'POST') throw new SuperConsoleHttpError('Sign-in requires POST.', { status: 405, code: 'METHOD_NOT_ALLOWED' });
    if (!this.options.auth.signIn) throw new SuperConsoleHttpError('This deployment does not expose password sign-in.', { status: 501, code: 'AUTH_SIGN_IN_UNAVAILABLE' });
    const body = await request.json().catch(() => undefined) as { email?: unknown; password?: unknown } | undefined;
    if (typeof body?.email !== 'string' || typeof body.password !== 'string' || !body.email || !body.password) {
      throw new SuperConsoleHttpError('Email and password are required.', { status: 400, code: 'AUTH_CREDENTIALS_REQUIRED' });
    }
    const result = await this.options.auth.signIn({ email: body.email, password: body.password, request });
    return success({ session: sessionView(result.principal) }, requestId, result.headers);
  }

  private async signOut(request: Request, requestId: string): Promise<Response> {
    if (request.method !== 'POST') throw new SuperConsoleHttpError('Sign-out requires POST.', { status: 405, code: 'METHOD_NOT_ALLOWED' });
    if (!this.options.auth.signOut) throw new SuperConsoleHttpError('This deployment does not expose sign-out.', { status: 501, code: 'AUTH_SIGN_OUT_UNAVAILABLE' });
    const principal = await this.options.auth.authenticate(request);
    const result = await this.options.auth.signOut({ principal, request });
    return success({ signedOut: true }, requestId, result.headers);
  }

  private async completeTwoFactor(request: Request, requestId: string): Promise<Response> {
    if (request.method !== 'POST') throw new SuperConsoleHttpError('Two-factor completion requires POST.', { status: 405, code: 'METHOD_NOT_ALLOWED' });
    if (!this.options.auth.completeTwoFactor) throw new SuperConsoleHttpError('This deployment does not expose two-factor sign-in.', { status: 501, code: 'AUTH_2FA_UNAVAILABLE' });
    const body = await request.json().catch(() => undefined) as { challengeId?: unknown; code?: unknown } | undefined;
    if (typeof body?.challengeId !== 'string' || typeof body.code !== 'string' || !body.challengeId || !body.code) {
      throw new SuperConsoleHttpError('challengeId and code are required.', { status: 400, code: 'AUTH_2FA_INPUT_REQUIRED' });
    }
    const result = await this.options.auth.completeTwoFactor({ challengeId: body.challengeId, code: body.code, request });
    return success({ session: sessionView(result.principal) }, requestId, result.headers);
  }

