function throwAuthResponse(response: Response, payload: AuthFnEnvelope): never {
  const error = new Error(payload.error?.message ?? 'AuthFn rejected the authentication request.') as Error & {
    authFnResponse?: Response;
    authFnCode?: string;
    authFnStatus?: number;
  };
  error.name = 'SuperConsoleAuthFnResponseError';
  error.authFnResponse = response;
