async function resolveSuccessfulOperator(
  authFn: ReturnType<typeof createAuthFn>,
  options: AuthFnOperatorAuthOptions,
  upstream: Response,
  payload: AuthFnEnvelope,
  request: Request,
): Promise<SuperConsoleSignInResult> {
