  private async confirmOperation(operationId: string, input: unknown, state: SuperConsoleRequestState) {
    const started = this.now();
    try {
      const receipt = await this.performConfirmOperation(operationId, input, state);
      await this.auditConfirmation(operationId, state.context, 'succeeded', started);
      return receipt;
    } catch (error) {
      await this.auditConfirmation(operationId, state.context, 'denied', started, normalizeAdminError(error).error.code);
      throw error;
    }
