  testfn: 'TestFn',
  userfn: 'UserFn',
  watchfn: 'WatchFn',
};

export const NESTED_OWNERS = {
  catchfn: 'watchfn',
  contentfn: 'cmsfn',
  logfn: 'watchfn',
} as const satisfies Record<(typeof NESTED_MODULE_IDS)[number], KnownModuleId>;

export const MODULE_CATALOG: readonly ModuleCatalogEntry[] = KNOWN_MODULE_IDS.map((id) => {
  const owner = NESTED_OWNERS[id as keyof typeof NESTED_OWNERS];
  return {
    id,
    displayName: DISPLAY_NAMES[id],
    availability: owner
      ? 'nested'
      : OPTIONAL_SET.has(id)
        ? 'optional-product'
        : 'required-product',
    ...(owner ? { owner } : {}),
  };
});

const KNOWN_SET = new Set<string>(KNOWN_MODULE_IDS);

export class ModuleSelectionError extends Error {
  readonly code = 'SUPERCONSOLE_INVALID_MODULE_SELECTION';

  constructor(message: string, readonly details: Record<string, unknown>) {
    super(message);
    this.name = 'ModuleSelectionError';
  }
}

export function isKnownModuleId(value: string): value is KnownModuleId {
  return KNOWN_SET.has(value);
}

export function parseModuleSelection(value: string | readonly string[] | undefined): KnownModuleId[] {
  if (value === undefined) return [];

  const candidates = (typeof value === 'string' ? value.split(',') : value)
    .map((candidate) => candidate.trim().toLowerCase())
    .filter(Boolean);
  const unknown = [...new Set(candidates.filter((candidate) => !isKnownModuleId(candidate)))];
  if (unknown.length > 0) {
    throw new ModuleSelectionError('The module selection contains unknown Superfunctions.', {
      unknown,
      known: KNOWN_MODULE_IDS,
    });
  }

  const selected = [...new Set(candidates)] as KnownModuleId[];
  const selectedSet = new Set<KnownModuleId>(selected);
  const missingOwners = selected
    .filter((id): id is keyof typeof NESTED_OWNERS => id in NESTED_OWNERS)
    .map((id) => ({ moduleId: id, ownerId: NESTED_OWNERS[id] }))
    .filter(({ ownerId }) => !selectedSet.has(ownerId));
  if (missingOwners.length > 0) {
    throw new ModuleSelectionError('Nested modules require their owning module to be selected.', {
      missingOwners,
    });
  }

  return selected.sort((left, right) =>
    KNOWN_MODULE_IDS.indexOf(left) - KNOWN_MODULE_IDS.indexOf(right)
  );
}

export function catalogForSelection(selected: readonly KnownModuleId[]): ModuleCatalogEntry[] {
  const selectedSet = new Set(selected);
  return MODULE_CATALOG.filter(({ id }) => selectedSet.has(id));
}

export function isRequiredProductModule(id: KnownModuleId): boolean {
  return REQUIRED_SET.has(id);
}
# SFN-21 — Super Console

This bundle is the source-controlled architecture and delivery record for [SFN-21](https://linear.app/21n/issue/SFN-21/build-super-console-as-the-modular-self-hosted-administration-control).

Super Console is the self-hosted operator control plane for a consumer-selected set of Superfunctions. A deployment registers modules explicitly. That registry is the only source for console navigation, server dispatch, REST/OpenAPI, the TypeScript admin client, and McpFn tool discovery. A function that is not registered is absent from every surface.

## Binding decisions

- Product and directory: **Super Console**, `superconsole/`.
- Runtime: self-hosted SvelteKit.
- Visual system: Tailwind configured through UIFn, with `@uifn/components-svelte` as the component boundary.
- UIFn defects or missing primitives are fixed in UIFn; local substitutes and secondary component libraries are prohibited.
- Relevant Superfunctions must power their corresponding console concern instead of local reimplementations.
- Operator administration stays separate from customer portals and embedded product UI.
- Each function owns its administration service interface and capability manifest.
- REST is versioned and language-neutral; OpenAPI is generated from enabled capabilities.
- The initial admin SDK is TypeScript.
- McpFn projects enabled capabilities to MCP; mutations use the same scope, policy, validation, idempotency, and audit path as REST.
- Tenancy is organization/workspace → project → environment.
- CatchFn and LogFn are nested under WatchFn. ContentFn is nested under CmsFn.
- CiFn's existing React dashboard behavior is migrated into the SvelteKit shell.
- Delivery remains local in coherent commits; no push or pull request is part of SFN-21.

