        message: "mutations must require audit",
      });
    }
    if (
      operation.safety.classification === "destructive" &&
      !operation.safety.requiresConfirmation
    ) {
      issues.push({
        path: `$.operations[${index}].safety.requiresConfirmation`,
        message: "destructive operations must require confirmation",
      });
    }
    if (
      operation.safety.classification === "destructive" &&
      !operation.target
    ) {
      issues.push({
        path: `$.operations[${index}].target`,
        message: "destructive operations must declare an exact target",
      });
    }
    for (const [kind, fields] of Object.entries(operation.redaction ?? {})) {
      const normalized = (fields ?? []).map((field) =>
        field.trim().toLowerCase(),
      );
      if (normalized.some((field) => !field))
        issues.push({
          path: `$.operations[${index}].redaction.${kind}`,
          message: "must not contain blank field names",
        });
      if (new Set(normalized).size !== normalized.length)
        issues.push({
          path: `$.operations[${index}].redaction.${kind}`,
          message: "must contain unique case-insensitive field names",
        });
    }
    if (
      [
        ...(operation.redaction?.inputFields ?? []),
        ...(operation.redaction?.outputFields ?? []),
      ].length > 0 &&
      operation.safety.audit !== "required"
    ) {
      issues.push({
        path: `$.operations[${index}].safety.audit`,
        message: "operations with declared sensitive fields must require audit",
      });
    }
    if (operation.target) {
      if (!operation.target.resource.trim())
        issues.push({
          path: `$.operations[${index}].target.resource`,
          message: "must not be blank",
        });
      if (
        operation.target.idInput !== undefined &&
        !operation.target.idInput.trim()
      )
        issues.push({
          path: `$.operations[${index}].target.idInput`,
          message: "must not be blank",
        });
      if (operation.target.collection === true && operation.target.idInput) {
        issues.push({
          path: `$.operations[${index}].target`,
          message: "must declare either a collection or an idInput, not both",
        });
      }
      if (
        operation.safety.classification === "destructive" &&
        operation.target.collection === true
      ) {
        issues.push({
          path: `$.operations[${index}].target`,
          message: "destructive targets must identify one resource",
        });
      }
      if (operation.target.collection !== true && !operation.target.idInput) {
        issues.push({
          path: `$.operations[${index}].target`,
          message: "must declare a collection or an idInput",
        });
      }
      if (
        operation.target.idInput &&
        !operation.inputSchema?.required?.includes(operation.target.idInput)
      ) {
        issues.push({
          path: `$.operations[${index}].inputSchema.required`,
          message: "must require the target idInput",
        });
      }
    }
    if (operation.mcp && typeof operation.mcp === "object") {
      const expectedRead = operation.safety.classification === "read";
      const expectedDestructive =
        operation.safety.classification === "destructive";
      if (
        operation.mcp.readOnlyHint !== undefined &&
        operation.mcp.readOnlyHint !== expectedRead
      )
        issues.push({
          path: `$.operations[${index}].mcp.readOnlyHint`,
          message: "must match the operation safety classification",
        });
      if (
        operation.mcp.destructiveHint !== undefined &&
        operation.mcp.destructiveHint !== expectedDestructive
      )
        issues.push({
          path: `$.operations[${index}].mcp.destructiveHint`,
          message: "must match the operation safety classification",
        });
      if (
        operation.mcp.idempotentHint !== undefined &&
        operation.mcp.idempotentHint !== Boolean(operation.safety.idempotent)
      )
        issues.push({
          path: `$.operations[${index}].mcp.idempotentHint`,
          message: "must match the operation idempotency declaration",
        });
    }
    try {
      operationSchemas(operation);
    } catch (error) {
      issues.push({
        path: `$.operations[${index}]`,
        message: error instanceof Error ? error.message : "schemas are invalid",
      });
    }
  });
  return issues;
}

export function assertAdminCapabilityManifest(
  manifest: AdminCapabilityManifest,
): void {
  const issues = validateAdminCapabilityManifest(manifest);
  if (issues.length > 0)
    throw new AdminError(
      "invalid_argument",
      `Invalid admin capability manifest: ${manifest.id}.`,
      { details: { issues } },
    );
}

export { stableSerialize };
import { AdminError } from "./errors.js";
import { assertAdminCapabilityManifest } from "./validator.js";
import type {
  AdminCapabilityAdapter,
  AdminCapabilityManifest,
  AdminNavigationDefinition,
  AdminOperationDefinition,
} from "./types.js";

export interface AdminRegistryOperation {
  moduleId: string;
  manifest: AdminCapabilityManifest;
  adapter: AdminCapabilityAdapter;
  operation: AdminOperationDefinition;
  routePath: string;
  mcpToolName: string;
}

export interface CreateAdminRegistryOptions {
  adapters: readonly AdminCapabilityAdapter[];
  /** Explicit allowlist. `[]` is a valid shell-only installation; omission is rejected. */
  enabledModules: readonly string[];
  apiBasePath?: string;
}

function dependenciesOf(manifest: AdminCapabilityManifest): string[] {
  const dependencies = (manifest.dependencies ?? []).flatMap((dependency) => {
    if (typeof dependency === "string") return [dependency];
    return dependency.required === false ? [] : [dependency.moduleId];
  });
  if (manifest.owner) dependencies.push(manifest.owner.moduleId);
  return [...new Set(dependencies)];
}

function routeOf(operation: AdminOperationDefinition): { method: string; path: string } {
  if (typeof operation.route === "string") {
    const match = /^(GET|POST|PUT|PATCH|DELETE)\s+(.+)$/i.exec(operation.route.trim());
    if (!match) throw new AdminError("invalid_argument", `Invalid route for ${operation.id}.`);
    return { method: match[1]!.toUpperCase(), path: match[2]! };
  }
  return operation.route;
}

export function adminMcpToolName(operationId: string): string {
  return `superconsole_${operationId.replace(/[^a-zA-Z0-9]+/g, "_").replace(/^_+|_+$/g, "")}`.toLowerCase();
}

export class AdminCapabilityRegistry {
  readonly apiBasePath: string;
  readonly manifests: readonly AdminCapabilityManifest[];
  readonly operations: readonly AdminRegistryOperation[];
  readonly enabledModuleIds: readonly string[];
  readonly navigation: readonly { moduleId: string; ownerModuleId?: string; item: AdminNavigationDefinition }[];
  private readonly adaptersById: ReadonlyMap<string, AdminCapabilityAdapter>;
  private readonly operationsById: ReadonlyMap<string, AdminRegistryOperation>;
  private readonly operationsByRoute: ReadonlyMap<string, AdminRegistryOperation>;
  private readonly operationsByTool: ReadonlyMap<string, AdminRegistryOperation>;

  constructor(options: CreateAdminRegistryOptions) {
    const basePath = `/${options.apiBasePath?.replace(/^\/+|\/+$/g, "") || "api/admin/v1"}`;
    const supplied = new Map<string, AdminCapabilityAdapter>();
    for (const adapter of options.adapters) {
      assertAdminCapabilityManifest(adapter.manifest);
      if (supplied.has(adapter.manifest.id)) throw new AdminError("conflict", `Duplicate admin module: ${adapter.manifest.id}.`);
      supplied.set(adapter.manifest.id, adapter);
    }

    if (!Array.isArray(options.enabledModules)) {
      throw new AdminError("invalid_argument", "Admin registry requires an explicit enabledModules allowlist.");
    }
    const requested = [...new Set(options.enabledModules)];
    for (const moduleId of requested) {
      if (!supplied.has(moduleId)) throw new AdminError("dependency_unavailable", `Enabled admin module is not registered: ${moduleId}.`);
    }
    const enabled = new Set(requested);
    for (const moduleId of requested) {
      const manifest = supplied.get(moduleId)!.manifest;
      for (const dependency of dependenciesOf(manifest)) {
        if (!enabled.has(dependency)) {
          throw new AdminError("dependency_unavailable", `Admin module ${moduleId} requires enabled module ${dependency}.`, {
            details: { moduleId, dependency },
          });
        }
      }
    }

    const visiting = new Set<string>();
    const visited = new Set<string>();
    const ordered: string[] = [];
    const visit = (moduleId: string, path: string[]): void => {
      if (visiting.has(moduleId)) throw new AdminError("conflict", `Admin module dependency cycle: ${[...path, moduleId].join(" -> ")}.`);
      if (visited.has(moduleId)) return;
      visiting.add(moduleId);
      for (const dependency of dependenciesOf(supplied.get(moduleId)!.manifest)) visit(dependency, [...path, moduleId]);
      visiting.delete(moduleId);
      visited.add(moduleId);
      ordered.push(moduleId);
    };
    requested.forEach((moduleId) => visit(moduleId, []));

    const operationIds = new Map<string, AdminRegistryOperation>();
    const routes = new Map<string, AdminRegistryOperation>();
    const tools = new Map<string, AdminRegistryOperation>();
    for (const moduleId of ordered) {
      const adapter = supplied.get(moduleId)!;
      for (const operation of adapter.manifest.operations) {
        const route = routeOf(operation);
        const suffix = route.path.startsWith("/") ? route.path : `/${route.path}`;
        const routePath = `${basePath}/modules/${moduleId}${suffix}`;
        const routeKey = `${route.method} ${normalizeRoutePattern(routePath)}`;
        const mcpToolName = adminMcpToolName(operation.id);
        const entry: AdminRegistryOperation = { moduleId, manifest: adapter.manifest, adapter, operation, routePath, mcpToolName };
        if (operationIds.has(operation.id)) throw new AdminError("conflict", `Duplicate admin operation ID: ${operation.id}.`);
        if (routes.has(routeKey)) throw new AdminError("conflict", `Duplicate admin route: ${routeKey}.`);
        if (tools.has(mcpToolName)) throw new AdminError("conflict", `Duplicate admin MCP tool: ${mcpToolName}.`);
        operationIds.set(operation.id, entry);
        routes.set(routeKey, entry);
        tools.set(mcpToolName, entry);
      }
    }

    const navigation = ordered.flatMap((moduleId) => {
      const manifest = supplied.get(moduleId)!.manifest;
      const definitions = manifest.navigation ? (Array.isArray(manifest.navigation) ? manifest.navigation : [manifest.navigation]) : [];
      return definitions.map((item) => ({ moduleId, ...(manifest.owner ? { ownerModuleId: manifest.owner.moduleId } : {}), item }));
    }).sort((left, right) => (left.item.order ?? 0) - (right.item.order ?? 0) || left.item.label.localeCompare(right.item.label));

    this.apiBasePath = basePath;
    this.enabledModuleIds = Object.freeze(ordered);
    this.manifests = Object.freeze(ordered.map((moduleId) => supplied.get(moduleId)!.manifest));
    this.operations = Object.freeze([...operationIds.values()]);
    this.navigation = Object.freeze(navigation) as typeof this.navigation;
    this.adaptersById = supplied;
    this.operationsById = operationIds;
    this.operationsByRoute = routes;
    this.operationsByTool = tools;
  }

  hasModule(moduleId: string): boolean { return this.enabledModuleIds.includes(moduleId); }
  getManifest(moduleId: string): AdminCapabilityManifest | undefined {
    return this.hasModule(moduleId) ? this.adaptersById.get(moduleId)?.manifest : undefined;
  }
  requireManifest(moduleId: string): AdminCapabilityManifest {
    const manifest = this.getManifest(moduleId);
    if (!manifest || !this.hasModule(moduleId)) throw new AdminError("not_found", `Admin module is not enabled: ${moduleId}.`);
    return manifest;
  }
  getOperation(operationId: string): AdminRegistryOperation | undefined { return this.operationsById.get(operationId); }
  requireOperation(operationId: string): AdminRegistryOperation {
    const operation = this.getOperation(operationId);
    if (!operation) throw new AdminError("not_found", `Admin operation is not enabled: ${operationId}.`);
    return operation;
  }
  matchRoute(method: string, path: string): AdminRegistryOperation | undefined {
    return this.operationsByRoute.get(`${method.toUpperCase()} ${normalizeRoutePattern(path)}`)
      ?? this.operations.find((entry) => routeMatches(entry.operation, entry.routePath, method, path));
  }
  matchMcpTool(toolName: string): AdminRegistryOperation | undefined { return this.operationsByTool.get(toolName); }
  toJSON(): { schemaVersion: "1.0"; enabledModules: readonly AdminCapabilityManifest[] } {
    return { schemaVersion: "1.0", enabledModules: this.manifests };
  }
}

function normalizeRoutePattern(path: string): string {
  return path.replace(/:[A-Za-z_][A-Za-z0-9_]*/g, ":param").replace(/\{[A-Za-z_][A-Za-z0-9_]*\}/g, ":param");
}

function routeMatches(operation: AdminOperationDefinition, pattern: string, method: string, path: string): boolean {
  const operationMethod = typeof operation.route === "string" ? operation.route.trim().split(/\s+/, 1)[0] : operation.route.method;
  if (operationMethod?.toUpperCase() !== method.toUpperCase()) return false;
  const patternParts = pattern.split("/").filter(Boolean);
  const pathParts = path.split("?")[0]!.split("/").filter(Boolean);
  return patternParts.length === pathParts.length && patternParts.every((part, index) =>
    part.startsWith(":") || /^\{[^}]+\}$/.test(part) || part === pathParts[index]);
}

export function createAdminRegistry(options: CreateAdminRegistryOptions): AdminCapabilityRegistry {
  return new AdminCapabilityRegistry(options);
}
import { AdminError } from "./errors.js";
import { stableSerialize } from "./validator.js";
import type { AdminResult, AdminScope } from "./types.js";

export interface AdminIdempotencyIdentity {
  key: string;
  actorId: string;
  scope: AdminScope;
  operationId: string;
}

export interface AdminIdempotencyRecord<T = unknown> {
  identity: AdminIdempotencyIdentity;
  fingerprint: string;
  result: AdminResult<T>;
  auditId?: string;
  createdAt: string;
}

export interface AdminIdempotencyClaim {
  identity: AdminIdempotencyIdentity;
  fingerprint: string;
  token: string;
}

export type AdminIdempotencyBeginResult<T = unknown> =
  | { status: "acquired"; claim: AdminIdempotencyClaim }
  | { status: "replay"; record: AdminIdempotencyRecord<T> }
  | {
      status: "in-progress";
      /** In-process stores may provide completion notification. Distributed stores normally return retryAfterMs. */
      wait?: Promise<AdminIdempotencyRecord<T> | undefined>;
      retryAfterMs?: number;
    };

/**
 * Atomic reservation contract. Durable implementations must make `begin` a
 * compare-and-create operation on the full identity and must fence `complete`
 * with the claim token. Cross-process stores should use a renewable lease or a
 * documented stale-claim recovery policy.
 */
export interface AdminIdempotencyStore {
  begin<T = unknown>(input: {
    identity: AdminIdempotencyIdentity;
    fingerprint: string;
  }): Promise<AdminIdempotencyBeginResult<T>> | AdminIdempotencyBeginResult<T>;
  complete<T = unknown>(
    claim: AdminIdempotencyClaim,
    record: AdminIdempotencyRecord<T>,
  ): Promise<void> | void;
}

export function adminIdempotencyStorageKey(identity: AdminIdempotencyIdentity): string {
  return stableSerialize(identity);
}

export function adminInputFingerprint(input: unknown): string { return stableSerialize(input); }

interface MemoryPendingEntry {
  status: "in-progress";
  fingerprint: string;
  token: string;
  wait: Promise<AdminIdempotencyRecord | undefined>;
  resolve: (record: AdminIdempotencyRecord | undefined) => void;
}

interface MemoryCompletedEntry {
  status: "completed";
  fingerprint: string;
  record: AdminIdempotencyRecord;
}

/** Process-local atomic test/development store. It is not durable or multi-process safe. */
export class MemoryAdminIdempotencyStore implements AdminIdempotencyStore {
  private readonly entries = new Map<string, MemoryPendingEntry | MemoryCompletedEntry>();

  begin<T = unknown>(input: {
    identity: AdminIdempotencyIdentity;
    fingerprint: string;
  }): AdminIdempotencyBeginResult<T> {
    const key = adminIdempotencyStorageKey(input.identity);
    const existing = this.entries.get(key);
    if (existing && existing.fingerprint !== input.fingerprint) {
      throw new AdminError("conflict", "The idempotency key was already used with different input.");
    }
    if (existing?.status === "completed") {
      return { status: "replay", record: structuredClone(existing.record) as AdminIdempotencyRecord<T> };
    }
    if (existing?.status === "in-progress") {
      return { status: "in-progress", wait: existing.wait as Promise<AdminIdempotencyRecord<T> | undefined> };
    }

    let resolve!: (record: AdminIdempotencyRecord | undefined) => void;
    const wait = new Promise<AdminIdempotencyRecord | undefined>((complete) => { resolve = complete; });
    const token = `claim_${crypto.randomUUID()}`;
    this.entries.set(key, { status: "in-progress", fingerprint: input.fingerprint, token, wait, resolve });
    return { status: "acquired", claim: { identity: input.identity, fingerprint: input.fingerprint, token } };
  }

  complete<T = unknown>(claim: AdminIdempotencyClaim, record: AdminIdempotencyRecord<T>): void {
    const key = adminIdempotencyStorageKey(claim.identity);
    const existing = this.entries.get(key);
    if (!existing || existing.status !== "in-progress" || existing.token !== claim.token) {
      throw new AdminError("conflict", "The idempotency reservation is no longer owned by this operation.");
    }
    if (existing.fingerprint !== claim.fingerprint || record.fingerprint !== claim.fingerprint) {
      throw new AdminError("conflict", "The idempotency completion fingerprint does not match its reservation.");
    }
    const snapshot = structuredClone(record) as AdminIdempotencyRecord;
    this.entries.set(key, { status: "completed", fingerprint: claim.fingerprint, record: snapshot });
    existing.resolve(structuredClone(snapshot));
  }
}

export async function beginAdminIdempotency<T>(
  store: AdminIdempotencyStore,
  identity: AdminIdempotencyIdentity,
  input: unknown,
): Promise<
  | { status: "acquired"; claim: AdminIdempotencyClaim }
  | { status: "replay"; record: AdminIdempotencyRecord<T> }
> {
  const fingerprint = adminInputFingerprint(input);
  // A released in-process claim may resolve without a record; retry its atomic begin once observed.
  for (;;) {
    const reservation = await store.begin<T>({ identity, fingerprint });
    if (reservation.status === "acquired" || reservation.status === "replay") return reservation;
    if (!reservation.wait) {
      throw new AdminError("conflict", "An operation with this idempotency key is already in progress.", {
        details: { retryAfterMs: reservation.retryAfterMs },
        retryable: true,
      });
    }
    const record = await reservation.wait;
    if (record) return { status: "replay", record };
  }
}
import type { AdminOperationError } from "./types.js";

export type AdminErrorCode =
  | "invalid_argument"
  | "unauthenticated"
  | "forbidden"
  | "not_found"
  | "conflict"
  | "rate_limited"
  | "precondition_failed"
  | "dependency_unavailable"
  | "internal";

const STATUS_BY_CODE: Record<AdminErrorCode, number> = {
  invalid_argument: 400,
  unauthenticated: 401,
  forbidden: 403,
  not_found: 404,
  conflict: 409,
  precondition_failed: 412,
  rate_limited: 429,
  dependency_unavailable: 503,
  internal: 500,
};

export class AdminError extends Error {
  readonly code: AdminErrorCode;
  readonly status: number;
  readonly details?: unknown;
  readonly retryable: boolean;

  constructor(
    code: AdminErrorCode,
    message: string,
    options: { status?: number; details?: unknown; retryable?: boolean; cause?: unknown } = {},
  ) {
    super(message, { cause: options.cause });
    this.name = "AdminError";
    this.code = code;
    this.status = options.status ?? STATUS_BY_CODE[code];
    this.details = options.details;
    this.retryable = options.retryable ?? (code === "rate_limited" || code === "dependency_unavailable");
  }
}

export function normalizeAdminError(
  error: unknown,
  identity: { requestId?: string; correlationId?: string } = {},
): AdminOperationError {
  const normalized = error instanceof AdminError
    ? error
    : new AdminError("internal", "The administration operation could not be completed.", { cause: error });
  return {
    ok: false,
    error: {
      code: normalized.code,
      message: normalized.message,
      status: normalized.status,
      ...(normalized.details === undefined ? {} : { details: normalized.details }),
      retryable: normalized.retryable,
    },
    ...identity,
  };
}

import type {
  AdminCapabilityAdapter,
  AdminCapabilityManifest,
  AdminOperationContext,
  AdminOperationHandlers,
  AdminOperationResult,
} from "./types.js";

export interface CreateAdminCapabilityAdapterOptions<
  TManifest extends AdminCapabilityManifest = AdminCapabilityManifest,
> {
  manifest: TManifest;
  handlers: AdminOperationHandlers;
}

function isResult(value: unknown): value is AdminOperationResult {
  return Boolean(value && typeof value === "object" && "data" in value && (value as { ok?: unknown }).ok !== false);
}

export function createAdminCapabilityAdapter<
  const TManifest extends AdminCapabilityManifest,
>(
  manifestOrOptions: TManifest | CreateAdminCapabilityAdapterOptions<TManifest>,
  providedHandlers?: AdminOperationHandlers,
): AdminCapabilityAdapter<TManifest> {
  const manifest = ("manifest" in manifestOrOptions
    ? manifestOrOptions.manifest
    : manifestOrOptions) as TManifest;
  const handlers = ("manifest" in manifestOrOptions
    ? manifestOrOptions.handlers
    : providedHandlers) ?? {};

  const invoke = async <T = unknown>(
    operationId: string,
    input: unknown,
    context: AdminOperationContext,
  ): Promise<AdminOperationResult<T>> => {
    const operation = manifest.operations.find((candidate) => candidate.id === operationId);
    if (!operation) {
      throw new Error(`Unknown admin operation: ${manifest.id}.${operationId}`);
    }
    const handler = handlers[operationId];
    if (!handler) {
      throw new Error(`No handler registered for admin operation: ${manifest.id}.${operationId}`);
    }
    const value = await handler({ input, context });
    return (isResult(value)
      ? value
      : {
          ok: true,
          data: value,
          requestId: context.requestId,
          correlationId: context.correlationId,
        }) as AdminOperationResult<T>;
  };

  return { manifest, handlers, invoke, execute: invoke };
}

