import { parseCookies, serializeSetCookie } from '@superfunctions/http';
import type { AuthFnConfig, AuthFnCookieConfig, AuthFnRuntimeResolution } from '../types.js';
export { resolveRuntime } from './runtime.js';

const DEFAULT_SESSION_MAX_AGE_SECONDS = 60 * 60 * 24 * 7;
const DEFAULT_CSRF_MAX_AGE_SECONDS = DEFAULT_SESSION_MAX_AGE_SECONDS;

export interface AuthFnResolvedCookiePolicy {
  prefix: string;
  path: string;
  domain?: string;
  secure: boolean;
  sameSite: 'lax' | 'strict' | 'none';
  sessionMaxAgeSeconds: number;
  csrfMaxAgeSeconds: number;
  sessionCookieName: string;
  csrfCookieName: string;
}

export interface AuthFnCookieBundle {
  sessionCookie: string;
  csrfCookie: string;
}

export function resolveCookiePolicy(
  config: Pick<AuthFnConfig, 'cookie'>,
  request: Request,
  runtime?: AuthFnRuntimeResolution
): AuthFnResolvedCookiePolicy {
  const effective: AuthFnCookieConfig = {
    ...config.cookie,
    ...runtime?.cookie
  };
  const prefix = effective.prefix?.trim() || 'authfn';
  const path = effective.path ?? '/';
  const secure = typeof effective.secure === 'function'
    ? effective.secure(request)
    : effective.secure ?? true;
  const sameSite = effective.sameSite ?? 'lax';
  const domain = typeof effective.domain === 'function'
    ? effective.domain({ request, regionId: runtime?.regionId })
    : effective.domain;

  return {
    prefix,
    path,
    domain,
    secure,
    sameSite,
    sessionMaxAgeSeconds: effective.sessionMaxAgeSeconds ?? DEFAULT_SESSION_MAX_AGE_SECONDS,
    csrfMaxAgeSeconds: effective.csrfMaxAgeSeconds ?? DEFAULT_CSRF_MAX_AGE_SECONDS,
    sessionCookieName: secure ? `__Secure-${prefix}.session` : `${prefix}.session`,
    csrfCookieName: `${prefix}.csrf`
  };
}

export function readCookieValues(
  request: Request,
  cookiePolicy: AuthFnResolvedCookiePolicy
): { sessionToken?: string; csrfToken?: string } {
  const cookies = parseCookies(request);
  return {
    sessionToken: cookies[cookiePolicy.sessionCookieName],
    csrfToken: cookies[cookiePolicy.csrfCookieName]
  };
}

export function issueSessionCookies(
  cookiePolicy: AuthFnResolvedCookiePolicy,
  sessionToken: string,
  csrfToken: string
): AuthFnCookieBundle {
  return {
    sessionCookie: serializeSetCookie({
      name: cookiePolicy.sessionCookieName,
      value: sessionToken,
      path: cookiePolicy.path,
      domain: cookiePolicy.domain,
      secure: cookiePolicy.secure,
      httpOnly: true,
      sameSite: cookiePolicy.sameSite,
      maxAge: cookiePolicy.sessionMaxAgeSeconds
    }),
    csrfCookie: serializeSetCookie({
      name: cookiePolicy.csrfCookieName,
      value: csrfToken,
      path: cookiePolicy.path,
      domain: cookiePolicy.domain,
      secure: cookiePolicy.secure,
      httpOnly: false,
      sameSite: cookiePolicy.sameSite,
      maxAge: cookiePolicy.csrfMaxAgeSeconds
    })
  };
}

export function clearSessionCookies(
  cookiePolicy: AuthFnResolvedCookiePolicy
): AuthFnCookieBundle {
  const expires = new Date(0);

  return {
    sessionCookie: serializeSetCookie({
      name: cookiePolicy.sessionCookieName,
      value: '',
      path: cookiePolicy.path,
      domain: cookiePolicy.domain,
      secure: cookiePolicy.secure,
      httpOnly: true,
      sameSite: cookiePolicy.sameSite,
      maxAge: 0,
      expires
    }),
    csrfCookie: serializeSetCookie({
      name: cookiePolicy.csrfCookieName,
      value: '',
      path: cookiePolicy.path,
      domain: cookiePolicy.domain,
      secure: cookiePolicy.secure,
      httpOnly: false,
    const document = createAdminOpenApiDocument(this.registry, {
      title: `${this.options.serverName ?? 'Super Console'} Administration API`,
      version: '1.0.0',
      description: 'Self-hosted operator administration powered by enabled Superfunctions.',
    });
    const authenticated = [{ authFnSession: [] }, { authFnApiKey: [] }];
    Object.assign(document.paths, {
      [`${this.registry.apiBasePath}/registry`]: { get: { operationId: 'superconsole.registry.get', summary: 'Discover enabled modules', security: authenticated, responses: { '200': { description: 'Enabled registry' } } } },
      [`${this.registry.apiBasePath}/overview`]: { get: { operationId: 'superconsole.overview.get', summary: 'Read operator overview', security: authenticated, responses: { '200': { description: 'Overview' } } } },
      [`${this.registry.apiBasePath}/search`]: { get: { operationId: 'superconsole.search.query', summary: 'Search through SearchFn', security: authenticated, responses: { '200': { description: 'Search results' } } } },
      [`${this.registry.apiBasePath}/audit`]: { get: { operationId: 'superconsole.audit.list', summary: 'Query the audit stream', security: authenticated, responses: { '200': { description: 'Audit events' } } } },
      [`${this.registry.apiBasePath}/settings`]: { get: { operationId: 'superconsole.settings.get', summary: 'Read deployment settings', security: authenticated, responses: { '200': { description: 'Settings' } } } },
      [`${this.registry.apiBasePath}/mcp`]: { get: { operationId: 'superconsole.mcp.get', summary: 'Read McpFn tool metadata', security: authenticated, responses: { '200': { description: 'MCP metadata' } } } },
      [`${this.registry.apiBasePath}/mcp/transport`]: { post: { operationId: 'superconsole.mcp.transport', summary: 'Authenticated McpFn streamable HTTP transport', security: authenticated, responses: { '200': { description: 'MCP JSON-RPC response' } } } },
      [`${this.registry.apiBasePath}/confirmations`]: { post: { operationId: 'superconsole.confirmations.issue', summary: 'Issue an actor/scope/operation/input-bound confirmation token', security: authenticated, parameters: [{ name: 'Idempotency-Key', in: 'header', required: false, schema: { type: 'string', minLength: 1 } }], responses: { '201': { description: 'Confirmation receipt' } } } },
      [`${this.registry.apiBasePath}/auth/sign-in`]: { post: { operationId: 'superconsole.auth.signIn', summary: 'Sign in through AuthFn password authentication', responses: { '200': { description: 'Operator session' }, '401': { description: 'Invalid credentials or two-factor challenge' } } } },
      [`${this.registry.apiBasePath}/auth/2fa`]: { post: { operationId: 'superconsole.auth.completeTwoFactor', summary: 'Complete an AuthFn two-factor sign-in challenge', responses: { '200': { description: 'Operator session' } } } },
      [`${this.registry.apiBasePath}/auth/sign-out`]: { post: { operationId: 'superconsole.auth.signOut', summary: 'Sign out through AuthFn', security: authenticated, responses: { '200': { description: 'Session revoked' } } } },
    });
    return document;
  }
}

export function createSuperConsole(options: SuperConsoleOptions): SuperConsole {
  return new SuperConsole(options);
}
