          auditId = failureAuditId;
        } catch {
          // The original safe error remains authoritative; deployments observe audit sink failures separately.
        }
      }
      const failedResult = auditId ? { ...safeNormalized, auditId } : safeNormalized;
      if (idempotencyClaim && idempotencyIdentity && this.idempotency) {
        try {
          await this.idempotency.complete(idempotencyClaim, {
            identity: idempotencyIdentity,
            fingerprint: adminInputFingerprint(idempotencyInput),
            result: failedResult,
            auditId,
            createdAt: this.now().toISOString(),
          });
        } catch {
          // Preserve the operation error. Durable stores retain/fence unresolved claims for recovery.
        }
      }
      return failedResult;
    }
  }

  private assertContext(context: AdminOperationContext): void {
    if (!context?.actor?.id) throw new AdminError("unauthenticated", "An authenticated administration actor is required.");
    if (!context.requestId || !context.source) throw new AdminError("invalid_argument", "Request identity and source are required.");
    const required = ["organizationId", "workspaceId", "projectId", "environmentId"] as const;
    for (const key of required) if (!context.scope?.[key]) throw new AdminError("invalid_argument", `Administration scope requires ${key}.`);
  }

  private scopeSupports(level: "organization" | "workspace" | "project" | "environment", context: AdminOperationContext): boolean {
    return level === "organization" ? Boolean(context.scope.organizationId)
      : level === "workspace" ? Boolean(context.scope.workspaceId)
      : level === "project" ? Boolean(context.scope.projectId)
      : Boolean(context.scope.environmentId);
  }

  private defaultPolicy(entry: AdminRegistryOperation, context: AdminOperationContext): AdminPolicyDecision {
    const permissions = context.actor.permissions ?? [];
    return { allowed: permissions.includes("*") || permissions.includes(entry.operation.permission) };
  }

  private idempotencyIdentity(entry: AdminRegistryOperation, context: AdminOperationContext): AdminIdempotencyIdentity | undefined {
    if (!context.idempotencyKey || !entry.operation.safety.idempotent) return undefined;
    return { key: context.idempotencyKey, actorId: context.actor.id, scope: context.scope, operationId: entry.operation.id };
  }

  private shouldAudit(entry: AdminRegistryOperation): boolean {
    return entry.operation.safety.audit === "required" || (entry.operation.safety.audit === "optional" && Boolean(this.audit));
  }

  private async writeAudit(
    entry: AdminRegistryOperation,
    request: AdminDispatchRequest,
    startedAt: Date,
    auditId: string,
    outcome: "succeeded" | "failed" | "denied" | "replayed",
    errorCode?: string,
    metadata?: Readonly<Record<string, unknown>>,
  ): Promise<void> {
    if (!this.audit) {
      if (entry.operation.safety.audit === "required") throw new AdminError("dependency_unavailable", "A required administration audit sink is unavailable.");
      return;
    }
    await this.audit.write({
      id: auditId,
      timestamp: this.now().toISOString(),
      actorId: request.context.actor.id,
      actorType: request.context.actor.type,
      scope: request.context.scope,
      moduleId: entry.moduleId,
function mcpInputSchema(entry: AdminRegistryOperation): McpFnObjectSchema {
  const input = entry.operation.inputSchema;
  if (!input || input.type !== "object") throw new AdminError("invalid_argument", `MCP operation ${entry.operation.id} requires an object input schema.`);
  if (entry.operation.safety.classification === "read") return input as McpFnObjectSchema;
  if (input.properties?._admin) throw new AdminError("conflict", `Operation ${entry.operation.id} uses the reserved MCP _admin input field.`);
  const required: string[] = [];
  const properties: Record<string, unknown> = {};
  if (entry.operation.safety.idempotent) {
    properties.idempotencyKey = { type: "string", minLength: 1, description: "Unique key for exactly-once administration execution." };
    required.push("idempotencyKey");
  }
  if (entry.operation.safety.requiresConfirmation) {
    properties.confirmationToken = { type: "string", minLength: 1, description: "Explicit confirmation token issued for this destructive operation." };
    required.push("confirmationToken");
  }
  return {
    ...input,
    properties: {
      ...(input.properties ?? {}),
      _admin: {
        type: "object",
        description: "Reserved Super Console mutation controls; removed before domain validation.",
        properties,
        required,
        additionalProperties: false,
      },
    },
    required: [...new Set([...(input.required ?? []), ...(required.length ? ["_admin"] : [])])],
  } as McpFnObjectSchema;
}

export function projectAdminMcpTools(
  options: AdminMcpProjectionOptions,
): McpFnToolDefinition<AdminOperationContext>[] {
  return options.registry.operations.filter((entry) => isMcpEnabled(entry.operation.mcp)).map((entry) => {
    const input = mcpInputSchema(entry);
    const output = entry.operation.outputSchema;
    const configured = typeof entry.operation.mcp === "object" ? entry.operation.mcp : undefined;
    const readOnly = entry.operation.safety.classification === "read";
    return {
      name: configured?.name ?? entry.mcpToolName,
      title: entry.operation.title,
      description: configured?.description ?? `${entry.operation.description} Requires ${entry.operation.permission}; safety=${entry.operation.safety.classification}${entry.operation.safety.requiresConfirmation ? "; explicit confirmation required" : ""}.`,
      inputSchema: input,
      ...(output?.type === "object" ? { outputSchema: output as McpFnObjectSchema } : {}),
      annotations: {
        readOnlyHint: configured?.readOnlyHint ?? readOnly,
        destructiveHint: configured?.destructiveHint ?? entry.operation.safety.classification === "destructive",
        idempotentHint: configured?.idempotentHint ?? Boolean(entry.operation.safety.idempotent),
