const SENSITIVE_ADMIN_FIELD = /(?:password|passwd|secret|token|credential|authorization|cookie|csrf|private[-_]?key|api[-_]?key|otp|salt|hash|^value$)/i;

export function isAdminRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isDisplayScalar(value: unknown): boolean {
  return value === null || ['string', 'number', 'boolean'].includes(typeof value);
}

function adminFieldLabel(key: string): string {
  return key
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .replace(/[-_]+/g, ' ')
    .replace(/^./, (character) => character.toUpperCase());
}

function adminFieldFormat(key: string, value: unknown): ResourceColumnViewModel['format'] {
  if (/(?:status|state|outcome|health)$/i.test(key)) return 'status';
  if (/(?:at|date|timestamp|time)$/i.test(key) && typeof value === 'string') return 'datetime';
  if (typeof value === 'number') return 'number';
  if (/(?:^id$|id$|key$|ref$|slug$)/i.test(key)) return 'code';
  return 'text';
}

function safeScalarEntries(record: Record<string, unknown>): Array<[string, unknown]> {
  return Object.entries(record).filter(
    ([key, value]) => !SENSITIVE_ADMIN_FIELD.test(key) && isDisplayScalar(value)
  );
}

/** Infer a compact, scalar-only table shape from the canonical `{ items }` contract. */
export function inferAdminResourceColumns(items: readonly unknown[]): ResourceColumnViewModel[] {
  const keys: string[] = [];
  for (const item of items) {
    if (!isAdminRecord(item)) continue;
    const values = isAdminRecord(item.values) ? item.values : item;
    for (const [key] of safeScalarEntries(values)) {
      if (!keys.includes(key)) keys.push(key);
      if (keys.length >= 8) break;
    }
    if (keys.length >= 8) break;
  }
  return keys.map((key) => {
    const sample = items
      .filter(isAdminRecord)
      .map((item) => isAdminRecord(item.values) ? item.values[key] : item[key])
      .find((value) => value !== null && value !== undefined);
    return { key, label: adminFieldLabel(key), format: adminFieldFormat(key, sample) };
  });
}

function adminItemId(item: Record<string, unknown>, resourceId: string): string | undefined {
  const singular = resourceId.endsWith('ies')
    ? `${resourceId.slice(0, -3)}y`
    : resourceId.endsWith('s')
      ? resourceId.slice(0, -1)
      : resourceId;
  for (const key of ['id', `…248 tokens truncated…?? [];
    const boundActions = identity
      ? sourceActions.filter((action) => Boolean(action.targetIdInput)).map((action) => ({
          ...action,
          input: { ...(action.input ?? {}), [action.targetIdInput!]: identity },
        }))
      : [];
    return [{
      id: identity ?? `row-${index}`,
      href: explicitHref ?? (identity ? `${resource.href}/${encodeURIComponent(identity)}` : undefined),
      values,
      actions: boundActions,
    }];
  });
}

export function inferAdminResourceFields(item: unknown): ResourceDetailViewModel['fields'] {
  if (!isAdminRecord(item)) return [];
  return safeScalarEntries(item).map(([key, value]) => ({
    label: adminFieldLabel(key),
    value,
    format: adminFieldFormat(key, value),
  }));
}

export function inferAdminResourceTitle(item: unknown, fallback: string): string {
  if (!isAdminRecord(item)) return fallback;
  for (const key of ['displayName', 'name', 'title', 'label', 'email', 'id', 'runId', 'key', 'slug']) {
    const value = item[key];
    if ((typeof value === 'string' || typeof value === 'number') && String(value)) return String(value);
  }
  return fallback;
<script lang="ts">
  import {
    AlertDialogAction,
    AlertDialogBackdrop,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogPortal,
    AlertDialogPositioner,
    AlertDialogRoot,
    AlertDialogTitle,
    AlertDialogTrigger,
  } from '@uifn/components-svelte/alert-dialog';
  import {
    ButtonLabel,
    ButtonRoot,
    ButtonSpinner,
  } from '@uifn/components-svelte/button';
  import { invalidateAll } from '$app/navigation';
  import { fetchConsole } from './admin-api';
  import type { AdminActionViewModel } from './view-models';

  let {
    action,
    compact = false,
  }: { action: AdminActionViewModel; compact?: boolean } = $props();

  let running = $state(false);
  let result = $state<{ ok: boolean; message: string } | undefined>();
  let dialogOpen = $state(false);
  let idempotencyKey: string | undefined;

  function actionInput(): Record<string, unknown> {
    return action.input ?? {};
  }

  function stableIdempotencyKey(): string {
    idempotencyKey ??= crypto.randomUUID();
    return idempotencyKey;
  }

  async function confirmationToken(): Promise<string | undefined> {
    if (!action.requiresConfirmation) return undefined;
    const response = await fetchConsole('/api/admin/v1/confirmations', {
      method: 'POST',
      headers: { accept: 'application/json', 'content-type': 'application/json' },
      body: JSON.stringify({ operationId: action.id, input: actionInput() }),
    });
    const payload = await response.json().catch(() => undefined) as
      | { data?: { token?: string }; error?: { message?: string } }
      | undefined;
    if (!response.ok || !payload?.data?.token) {
      throw new Error(payload?.error?.message ?? 'The operation confirmation could not be issued.');
    }
    return payload.data.token;
  }

  async function runAction() {
    const endpoint = action.apiHref ?? action.href;
    if (!endpoint || action.disabled || running) return;
    running = true;
    result = undefined;
    try {
      const method = (action.method ?? 'POST').toUpperCase();
      const token = await confirmationToken();
      const headers = new Headers({ accept: 'application/json', 'content-type': 'application/json' });
      if (!['GET', 'HEAD'].includes(method)) headers.set('idempotency-key', stableIdempotencyKey());
      if (token) headers.set('x-admin-confirmation', token);
      const response = await fetchConsole(endpoint, {
        method,
        headers,
        body: ['GET', 'HEAD'].includes(method) ? undefined : JSON.stringify(actionInput()),
      });
      const body = await response.json().catch(() => undefined) as
        | { error?: { message?: string }; message?: string }
        | undefined;
      if (!response.ok) throw new Error(body?.error?.message ?? `HTTP ${response.status}`);
      result = { ok: true, message: body?.message ?? `${action.label} completed.` };
      idempotencyKey = undefined;
      dialogOpen = false;
      await invalidateAll();
    } catch (cause) {
      result = {
        ok: false,
        message: cause instanceof Error ? cause.message : `${action.label} failed.`,
      };
    } finally {
      running = false;
    }
  }
</script>

{#if action.requiresConfirmation || action.tone === 'danger'}
  <AlertDialogRoot open={dialogOpen} onOpenChange={(open: boolean) => (dialogOpen = open)}>
    <AlertDialogTrigger
      class={`action-trigger ${action.tone === 'danger' ? 'action-trigger--danger' : ''}`}
      disabled={action.disabled}
    >
      {action.label}
    </AlertDialogTrigger>
    <AlertDialogPortal>
      <AlertDialogBackdrop />
      <AlertDialogPositioner>
        <AlertDialogContent class="confirm-dialog">
          <AlertDialogTitle>{action.label}?</AlertDialogTitle>
          <AlertDialogDescription>
            {action.description ?? 'This operator action is audited and may affect production resources.'}
          </AlertDialogDescription>
          <div class="confirm-dialog__actions">
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onclick={runAction} disabled={running}>
              {running ? 'Working…' : action.label}
            </AlertDialogAction>
          </div>
        </AlertDialogContent>
      </AlertDialogPositioner>
    </AlertDialogPortal>
  </AlertDialogRoot>
{:else}
  <ButtonRoot
    variant="outline"
    size={compact ? 'sm' : 'md'}
    disabled={action.disabled || running}
    loading={running}
    onclick={runAction}
  >
    <ButtonSpinner />
    <ButtonLabel>{action.label}</ButtonLabel>
  </ButtonRoot>
{/if}

{#if result}
  <span class:action-result--error={!result.ok} class="action-result" role="status">
    {result.message}
  </span>
{/if}
<script lang="ts">
  import { navigating, page } from '$app/state';
