import { ADMIN_API_PREFIX, fetchAdmin, withAdminScope } from '$lib/components/admin-api';
import {
  inferAdminResourceColumns,
  moduleById,
  normalizeAdminResourceRows,
  type ResourceListViewModel,
} from '$lib/components/view-models';
import type { PageLoad } from './$types';

export const load: PageLoad = async ({ fetch, params, parent, url, depends }) => {
  depends(`superconsole:module:${params.moduleId}:resource:${params.resource}`);
  const { shell } = await parent();
  const module = moduleById(shell.registry, params.moduleId);
  const resource = module?.resources?.find((candidate) => candidate.id === params.resource);
  if (!module || !resource) {
    return {
      view: undefined,
      loadError: {
        status: 404,
        code: 'RESOURCE_NOT_ENABLED',
        message: `${params.resource} is not an enabled ${params.moduleId} administration resource.`,
      },
    };
  }
  const apiHref = resource.apiHref ?? `${ADMIN_API_PREFIX}/modules/${encodeURIComponent(params.moduleId)}/${encodeURIComponent(params.resource)}`;
  const requestHref = new URL(apiHref, 'http://superconsole.local');
  for (const [key, value] of url.searchParams) requestHref.searchParams.set(key, value);
  const result = await fetchAdmin<Partial<ResourceListViewModel> & { items?: unknown[] }>(
    fetch,
    withAdminScope(`${requestHref.pathname}${requestHref.search}`, url.searchParams)
  );
  const payload = result.ok ? result.data : {};
  const canonicalItems = Array.isArray(payload.items) ? payload.items : [];
  const explicitRows = Array.isArray(payload.rows) ? payload.rows : undefined;
  const columnSource = explicitRows?.map((row) => ({ values: row.values })) ?? canonicalItems;
  const columns = Array.isArray(payload.columns) && payload.columns.length
    ? payload.columns
    : inferAdminResourceColumns(columnSource);
  const rows = explicitRows ?? normalizeAdminResourceRows(canonicalItems, columns, resource);
  return {
    view: {
      module,
      resource,
      columns,
      rows,
      total: payload.total,
      nextCursor: payload.nextCursor,
    } satisfies ResourceListViewModel,
    loadError: result.ok ? undefined : result.error,
    query: url.searchParams.get('q') ?? '',
  };
};
