describe('AuthFn operator transport', () => {
  const encryptionKey = Buffer.alloc(32, 9);
  const decodeBase32 = (secret: string) => {
    const alphabet = 'REDACTED';
    let buffer = 0;
    let bits = 0;
    const bytes: number[] = [];
    for (const char of secret.replace(/=+$/g, '').toUpperCase()) {
      const index = alphabet.indexOf(char);
      if (index < 0) continue;
      buffer = (buffer << 5) | index;
      bits += 5;
      if (bits >= 8) { bytes.push((buffer >>> (bits - 8)) & 0xff); bits -= 8; }
    }
      throw new Error("McpFn pageSize must be a positive integer");
    }
    const registryCapabilities = this.registry.capabilities();
    if (registryCapabilities.tasks && !options.taskStore) {
      throw new Error("Task-capable McpFn tools require a taskStore");
    }
    if (registryCapabilities.tasks && options.taskStore) {
      registryCapabilities.tasks = {
        ...registryCapabilities.tasks,
        list: {},
        cancel: {},
      };
    }
    this.capabilities = mergeCapabilities(registryCapabilities, options.additionalCapabilities);
    this.manifestOptions = {
      protocolVersions: options.protocolVersions,
      transports: options.transports,
      extensions: options.extensions,
      capabilities: this.capabilities,
      clientRequirements: options.clientRequirements,
    };
    this.protocol = new Server(
      { name: options.info.name, version: options.info.version },
      {
        capabilities: this.capabilities,
        instructions: options.info.instructions,
        taskStore: options.taskStore,
        taskMessageQueue: options.taskMessageQueue,
        defaultTaskPollInterval: options.defaultTaskPollInterval,
        maxTaskQueueSize: options.maxTaskQueueSize,
        enforceStrictCapabilities: options.enforceStrictCapabilities,
        debouncedNotificationMethods: [
          "notifications/tools/list_changed",
          "notifications/resources/list_changed",
          "notifications/prompts/list_changed",
        ],
      },
    );
    this.installHandlers();
  }

  private installHandlers(): void {
    if (this.capabilities.tools) {
      this.protocol.setRequestHandler(ListToolsRequestSchema, async (request) => {
        const result = page(this.registry.listTools(), request.params?.cursor, this.pageSize);
        return { tools: result.values, ...(result.nextCursor ? { nextCursor: result.nextCursor } : {}) };
      });
      this.protocol.setRequestHandler(CallToolRequestSchema, async (request, extra) => {
        const taskSupport = this.registry.taskSupport(request.params.name);
        const isTaskRequest = Boolean(request.params.task);
        if (taskSupport === "required" && !isTaskRequest) {
          throw new McpError(
            ErrorCode.MethodNotFound,
            `Tool ${request.params.name} requires task augmentation`,
          );
        }
        if (taskSupport === "forbidden" && isTaskRequest) {
          throw new McpError(
            ErrorCode.MethodNotFound,
            `Tool ${request.params.name} does not support task augmentation`,
          );
        }
        try {
          const context = await this.contextFactory(extra);
          if (isTaskRequest) {
            if (!extra.taskStore) throw new Error("No task store is available");
            return await this.registry.createToolTask(
              request.params.name,
              request.params.arguments,
              context,
              extra as McpFnTaskRequestExtra,
            );
          }
          return await this.registry.callTool(
            request.params.name,
            request.params.arguments,
            context,
            extra,
          );
        } catch (error) {
          if (isTaskRequest) throw error;
          return errorResult(error, {
            includeStructuredContent: !this.registry.hasOutputSchema(request.params.name),
          });
        }
      });
    }

    if (this.capabilities.resources) {
      this.protocol.setRequestHandler(ListResourcesRequestSchema, async (request, extra) => {
        const context = await this.contextFactory(extra);
      .sort((left, right) => left.name.localeCompare(right.name));
  }

  promptDefinitions(): McpFnPromptDefinition<TContext>[] {
    return [...this.prompts.values()]
      .map(({ definition }) => definition)
      .sort((left, right) => left.name.localeCompare(right.name));
  }

  capabilities(options: { listChanged?: boolean } = {}): ServerCapabilities {
    const capabilities: ServerCapabilities = {};
    if (this.tools.size) capabilities.tools = { listChanged: options.listChanged ?? true };
    if (this.resources.size || this.resourceTemplates.size) {
      capabilities.resources = {
        listChanged: options.listChanged ?? true,
        subscribe: [...this.resources.values()].some((value) => value.subscribe) ||
          [...this.resourceTemplates.values()].some(({ definition }) => definition.subscribe),
      };
    }
    if (this.prompts.size) capabilities.prompts = { listChanged: options.listChanged ?? true };
    if (
      [...this.resourceTemplates.values()].some(({ definition }) => definition.complete) ||
      [...this.prompts.values()].some(({ definition }) => definition.complete)
    ) capabilities.completions = {};
    if (this.definitions().some((definition) => {
      const support = definition.execution?.taskSupport;
      return support === "optional" || support === "required";
    })) capabilities.tasks = { requests: { tools: { call: {} } } };
    return capabilities;
  }

  listTools(): McpFnListedTool[] {
    return this.definitions().map((definition) => ({
      name: definition.name,
      ...(definition.title ? { title: definition.title } : {}),
      description: definition.description,
      inputSchema: definition.inputSchema as McpFnListedTool["inputSchema"],
      ...(definition.outputSchema
        ? { outputSchema: definition.outputSchema as McpFnListedTool["outputSchema"] }
        : {}),
      ...(definition.annotations ? { annotations: definition.annotations } : {}),
      ...(definition.execution ? { execution: definition.execution } : {}),
      ...(definition.icons ? { icons: definition.icons } : {}),
      ...(definition.metadata ? { _meta: definition.metadata } : {}),
    }));
  }

  async listResources(
    context: TContext,
    extra: McpFnRequestExtra,
  ): Promise<Resource[]> {
    const resources: Resource[] = this.resourceDefinitions().map((definition) => ({
      uri: definition.uri,
      name: definition.name,
      ...(definition.title ? { title: definition.title } : {}),
      ...(definition.description ? { description: definition.description } : {}),
      ...(definition.mimeType ? { mimeType: definition.mimeType } : {}),
      ...(definition.annotations ? { annotations: definition.annotations } : {}),
      ...(definition.icons ? { icons: definition.icons } : {}),
      ...(definition.metadata ? { _meta: definition.metadata } : {}),
    }));

