  }

  .module-card [data-uifn-part='header'] {
    grid-template-columns: auto 1fr auto;
  }

  .module-card [data-uifn-part='title'],
  .module-card [data-uifn-part='description'] {
    grid-column: 2;
  }

  .module-card [data-uifn-part='action'] {
    grid-column: 3;
  }

  .module-card__mark,
  .resource-card__icon,
  .artifact-card__icon,
  .job-card__number {
    @apply grid h-9 w-9 shrink-0 place-items-center rounded-lg text-[0.65rem] font-black;
    color: var(--uifn-color-accent-solid);
    border: 1px solid color-mix(in srgb, var(--uifn-color-accent-solid) 22%, var(--uifn-color-border-subtle));
    background: var(--uifn-color-accent-subtle);
  }

  .module-card__meta {
    @apply flex items-center justify-between gap-3 text-xs;
    color: var(--uifn-color-text-muted);
  }

  .module-card [data-uifn-part='footer'],
  .resource-card [data-uifn-part='footer'] {
    @apply justify-end py-2.5;
  }

  .alert-stack,
  .notice-stack {
    @apply grid gap-2.5;
  }

  .alert-card [data-uifn-part='header'] {
    grid-template-columns: auto 1fr;
  }

  .alert-card [data-uifn-part='title'],
  .alert-card [data-uifn-part='description'] {
    grid-column: 2;
  }

  .alert-card--critical {
    border-color: color-mix(in srgb, var(--uifn-color-danger-solid) 36%, var(--uifn-color-border-subtle));
  }

  .alert-card--warning {
    border-color: color-mix(in srgb, var(--uifn-color-warning-solid) 42%, var(--uifn-color-border-subtle));
  }

  .activity-section,
  .capability-section {
    @apply mt-8;
  }

  .status-badge {
    @apply gap-1.5 capitalize;
  }

  .status-badge__dot {
    @apply h-1.5 w-1.5 rounded-full bg-current;
  }

  .status-badge--warning {
    color: var(--uifn-color-warning-solid) !important;
    border-color: color-mix(in srgb, var(--uifn-color-warning-solid) 45%, transparent) !important;
    background: var(--uifn-color-warning-subtle) !important;
  }

  .status-badge--info {
    color: var(--uifn-color-accent-solid) !important;
    border-color: color-mix(in srgb, var(--uifn-color-accent-solid) 38%, transparent) !important;
    background: var(--uifn-color-accent-subtle) !important;
  }

  .status-badge--danger {
    color: var(--uifn-color-danger-contrast);
  }

  .state-panel {
    inline-size: 100% !important;
    @apply min-h-[10rem] place-content-center text-center;
    background: color-mix(in oklab, var(--uifn-color-surface-raised) 86%, transparent) !important;
  }

  .state-panel [data-uifn-part='header'] {
    @apply justify-items-center;
    grid-template-columns: 1fr;
  }

  .state-panel [data-uifn-part='title'],
  .state-panel [data-uifn-part='description'] {
    grid-column: 1;
  }

  .state-panel__icon {
    @apply mb-1 grid h-11 w-11 place-items-center rounded-xl;
    color: var(--uifn-color-text-muted);
    background: var(--uifn-color-surface-sunken);
  }

  .state-panel__skeletons {
    @apply mx-auto grid max-w-md gap-2;
  }

  .request-id {
    @apply mb-3 mt-0 text-xs;
    color: var(--uifn-color-text-muted);
  }

  .module-status-bar,
  .run-detail-meta,
  .mcp-status,
  .settings-overview {
    @apply mb-7 flex flex-wrap items-center gap-x-5 gap-y-2 rounded-lg border px-4 py-3 text-xs;
    border-color: var(--uifn-color-border-subtle);
    background: color-mix(in oklab, var(--uifn-color-surface-raised) 82%, transparent);
  }

  .notice {
    @apply flex items-start gap-3 rounded-lg border px-4 py-3;
    border-color: var(--uifn-color-border-subtle);
    background: var(--uifn-color-surface-raised);
  }

  .notice > div {
    @apply grid gap-0.5 text-xs;
  }

  .notice > div span {
    color: var(--uifn-color-text-secondary);
  }

  .notice--warning {
    border-color: color-mix(in srgb, var(--uifn-color-warning-solid) 38%, var(--uifn-color-border-subtle));
    background: var(--uifn-color-warning-subtle);
  }

  .notice--danger {
    border-color: color-mix(in srgb, var(--uifn-color-danger-solid) 38%, var(--uifn-color-border-subtle));
    background: var(--uifn-color-danger-subtle);
  }

  .summary-strip,
  .run-summary {
    @apply mb-7 grid overflow-hidden rounded-lg border;
    grid-template-columns: repeat(auto-fit, minmax(9rem, 1fr));
    border-color: var(--uifn-color-border-subtle);
    background: var(--uifn-color-surface-raised);
  }

  .summary-strip > div,
  .run-summary > div {
    @apply grid gap-0.5 border-r px-4 py-3 last:border-r-0;
    border-color: var(--uifn-color-border-subtle);
  }

  .summary-strip span,
  .run-summary span,
  .summary-strip small {
    @apply text-xs;
    color: var(--uifn-color-text-muted);
  }

  .summary-strip strong,
  .run-summary strong {
    @apply text-xl font-bold tracking-[-0.03em];
  }

  .resource-card__count {
    @apply mr-1 text-xl font-bold;
    @apply mr-1 text-xl font-bold;
  }

  .capability-list {
    @apply m-0 grid list-none gap-2 p-0;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
  }

  .capability-list li {
    @apply flex items-center gap-2 rounded-md border px-3 py-2 text-xs;
    border-color: var(--uifn-color-border-subtle);
    background: var(--uifn-color-surface-raised);
  }

  .capability-list li svg {
    color: var(--uifn-color-success-solid);
  }

  .resource-toolbar,
  .global-search {
    @apply mb-5 flex items-center gap-2 rounded-lg border p-2;
    border-color: var(--uifn-color-border-subtle);
    background: var(--uifn-color-surface-raised);
    box-shadow: var(--uifn-elevation-shadow-sm);
  }

  .resource-toolbar__search,
  .global-search {
    @apply flex min-w-0 flex-1 items-center gap-2;
  }

  .resource-toolbar__search > svg,
  .global-search > svg {
    @apply ml-2 shrink-0;
    color: var(--uifn-color-text-muted);
  }

  .resource-toolbar__search [data-uifn-component='input'],
  .global-search [data-uifn-component='input'] {
    @apply border-0 bg-transparent shadow-none outline-none;
  }

  .resource-toolbar__count {
    @apply px-2 text-xs;
    color: var(--uifn-color-text-muted);
  }

  .resource-table__actions {
    @apply flex items-center justify-end gap-1;
  }

  .resource-table [data-uifn-part='cell']:first-child,
  .runs-table [data-uifn-part='cell']:first-child {
    @apply font-semibold;
  }

  .table-secondary {
    @apply mt-0.5 block text-[0.7rem];
    color: var(--uifn-color-text-muted);
  }

  .pagination-bar {
    @apply mt-4 flex items-center justify-between gap-4 rounded-lg border px-4 py-3 text-xs;
    color: var(--uifn-color-text-secondary);
    border-color: var(--uifn-color-border-subtle);
    background: var(--uifn-color-surface-raised);
  }

  .detail-grid,
  .settings-grid,
  .mcp-grid {
    @apply grid items-start gap-5;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .detail-list {
    @apply m-0 grid;
  }

  .detail-list > div {
    @apply grid gap-3 border-b py-3 last:border-b-0;
    grid-template-columns: minmax(8rem, 0.45fr) minmax(0, 1fr);
    border-color: var(--uifn-color-border-subtle);
  }

  .detail-list dt {
    @apply text-xs font-semibold;
    color: var(--uifn-color-text-muted);
  }

  .detail-list dd {
    @apply m-0 break-words text-sm;
  }

  .detail-list dd.code-value {
    font-family: var(--uifn-typography-family-mono);
  }

  .audit-timeline {
    @apply relative m-0 grid list-none gap-5 p-0;
  }

  .audit-timeline::before {
    content: '';
    @apply absolute bottom-2 left-[0.29rem] top-2 w-px;
    background: var(--uifn-color-border-default);
  }

  .audit-timeline li {
    @apply relative flex gap-3;
  }

  .audit-timeline__dot {
    @apply relative z-[1] mt-1 h-2.5 w-2.5 shrink-0 rounded-full border-2;
    border-color: var(--uifn-color-surface-raised);
    background: var(--uifn-color-accent-solid);
    box-shadow: 0 0 0 1px var(--uifn-color-accent-solid);
  }

  .audit-timeline li > div {
    @apply grid gap-0.5 text-xs;
  }

  .audit-timeline li span,
  .audit-timeline li code {
    color: var(--uifn-color-text-muted);
  }

  .action-trigger {
    @apply inline-flex min-h-9 cursor-pointer items-center rounded-md border px-3 py-1.5 text-xs font-semibold;
    color: var(--uifn-color-text-primary);
    border-color: var(--uifn-color-border-default);
    background: var(--uifn-color-surface-raised);
  }

  .action-trigger--danger {
    color: var(--uifn-color-danger-solid);
    border-color: var(--uifn-color-danger-solid);
  }

  .action-result {
    @apply ml-2 text-xs;
    color: var(--uifn-color-success-solid);
  }

  .action-result--error {
    color: var(--uifn-color-danger-solid);
  }

  .confirm-dialog {
    @apply gap-3 p-6;
  }

  .confirm-dialog__actions {
    @apply mt-3 flex justify-end gap-2;
  }

  .filter-pills {
    @apply mb-4 flex flex-wrap gap-1;
  }

  .job-card [data-uifn-part='header'] {
    grid-template-columns: auto 1fr auto;
  }

  .job-card [data-uifn-part='title'],
  .job-card [data-uifn-part='description'] {
    grid-column: 2;
  }

  .step-list {
    @apply mb-4 mt-0 grid list-none gap-1.5 p-0;
  }

  .step-list li {
    @apply flex items-center gap-2 rounded-md border px-2.5 py-2 text-xs;
    border-color: var(--uifn-color-border-subtle);
    background: var(--uifn-color-surface-sunken);
  }

  .step-list li time {
    @apply ml-auto;
    color: var(--uifn-color-text-muted);
  }

  .log-console {
    @apply overflow-hidden rounded-xl border;
    color: var(--uifn-color-text-primary);
    border-color: var(--uifn-color-border-default);
    background: var(--uifn-color-surface-sunken);
    box-shadow: var(--uifn-elevation-shadow-lg);
  }

  .log-console__toolbar {
    @apply flex h-11 items-center gap-3 border-b px-4 text-xs;
    color: var(--uifn-color-text-muted);
    border-color: var(--uifn-color-border-default);
    background: var(--uifn-color-surface-raised);
  }

  .log-console__toolbar > span:last-child {
    @apply ml-auto;
  }

  .log-console__lights {
    @apply flex gap-1.5;
  }

  .log-console__lights i {
    @apply h-2.5 w-2.5 rounded-full;
    background: var(--uifn-color-text-disabled);
  }

  .log-console__lights i:first-child { background: var(--uifn-color-danger-solid); }
  .log-console__lights i:nth-child(2) { background: var(--uifn-color-warning-solid); }
  .log-console__lights i:last-child { background: var(--uifn-color-success-solid); }

  .log-console ol {
    @apply m-0 max-h-[65vh] list-none overflow-auto p-0 py-3 font-mono text-[0.72rem] leading-6;
  }

  .log-console li {
    @apply grid min-w-max px-4;
    grid-template-columns: 3rem 12rem minmax(5rem, auto) minmax(0, 1fr);
  }

  .log-console li:hover { background: color-mix(in srgb, var(--uifn-color-surface-overlay) 78%, var(--uifn-color-accent-subtle)); }
  .log-console li > span { @apply select-none pr-4 text-right; color: var(--uifn-color-text-disabled); }
  .log-console li time { color: var(--uifn-color-text-muted); }
  .log-console li em { @apply mr-3 not-italic; color: var(--uifn-color-accent-solid); }
  .log-console li code { @apply whitespace-pre-wrap; color: inherit; }
  .log-console--nowrap li code { @apply whitespace-pre; }
  .log-console__empty { @apply p-8 text-center font-mono text-xs; color: var(--uifn-color-text-muted); }

  .artifact-card [data-uifn-part='header'] {
    grid-template-columns: auto 1fr;
  }

  .artifact-card [data-uifn-part='title'],
  .artifact-card [data-uifn-part='description'] { grid-column: 2; }

  .artifact-card [data-uifn-part='content'] {
    @apply grid gap-1 text-xs;
  }

  .api-hero {
    @apply mb-8 grid items-end gap-6 rounded-xl border p-6;
    grid-template-columns: minmax(0, 1fr) auto;
    border-color: color-mix(in srgb, var(--uifn-color-accent-solid) 25%, var(--uifn-color-border-subtle));
    background:
      radial-gradient(circle at 92% 0%, var(--uifn-color-accent-subtle), transparent 15rem),
      var(--uifn-color-surface-raised);
  }

  .api-hero h2 { @apply mb-1 mt-3 text-2xl font-bold tracking-[-0.03em]; }
  .api-hero p { @apply m-0 max-w-2xl text-sm; color: var(--uifn-color-text-secondary); }
  .api-hero > div:last-child { @apply grid gap-x-6 gap-y-1; grid-template-columns: auto auto; }
  .api-hero > div:last-child span { @apply text-xs; color: var(--uifn-color-text-muted); }

  .operation-list,
  .tool-list,
  .search-results {
    @apply grid gap-2.5;
  }

  .operation-card [data-uifn-part='header'],
  .tool-card [data-uifn-part='header'] {
    grid-template-columns: auto 1fr;
  }

  .operation-card [data-uifn-part='title'],
  .operation-card [data-uifn-part='description'],
  .tool-card [data-uifn-part='title'],
  .tool-card [data-uifn-part='description'] { grid-column: 2; }

  .operation-card [data-uifn-part='content'],
  .tool-card [data-uifn-part='content'] {
    @apply flex flex-wrap items-center justify-between gap-3 text-xs;
  }

  .mcp-status > div,
  .settings-overview > div {
    @apply grid gap-0.5;
  }

  .mcp-status > div span,
  .settings-overview > div span {
    @apply text-[0.68rem];
    color: var(--uifn-color-text-muted);
  }

  .mcp-status > div:not(:last-child),
  .settings-overview > div:not(:last-child) {
    @apply border-r pr-5;
    border-color: var(--uifn-color-border-subtle);
  }

  .client-list,
  .policy-list {
    @apply grid gap-2;
  }

  .client-list > div,
  .policy-row {
    @apply flex w-full items-center justify-between gap-4 rounded-md border px-3 py-2.5;
    border-color: var(--uifn-color-border-subtle);
    background: var(--uifn-color-surface-sunken);
  }

  .client-list > div > span,
  .policy-row > span {
    @apply grid gap-0.5 text-xs;
  }

  .client-list small,
  .policy-row small {
    color: var(--uifn-color-text-muted);
  }

  .policy-row code {
    @apply mt-1 w-fit rounded px-1 py-0.5 text-[0.6rem];
    background: var(--uifn-color-surface-raised);
  }

  .settings-feedback {
    @apply mb-0 mt-3 text-xs;
    color: var(--uifn-color-accent-solid);
  }

  .global-search {
    @apply mx-auto mb-8 max-w-4xl p-3;
    box-shadow: var(--uifn-elevation-shadow-md);
  }

  .global-search [data-uifn-component='input'] {
    @apply text-base;
  }

  .search-results-heading {
    @apply mb-3 flex items-center gap-1.5 text-sm;
  }

  .search-results-heading span { color: var(--uifn-color-text-muted); }

  .search-result [data-uifn-part='header'] {
    grid-template-columns: auto 1fr auto;
  }

  .search-result [data-uifn-part='title'],
  .search-result [data-uifn-part='description'] { grid-column: 2; }

  .search-result [data-uifn-part='action'] { grid-column: 3; }

  .search-result [data-uifn-part='content'] {
    @apply flex items-center justify-between gap-3 text-xs;
    color: var(--uifn-color-text-muted);
  }

  .sign-in-card {
    @apply mx-auto max-w-md;
  }

  .sign-in-form {
    @apply grid gap-4;
  }

  .sign-in-form label {
    @apply grid gap-1.5 text-xs font-semibold;
  }

  .sign-in-form__error {
    @apply m-0 rounded-md border px-3 py-2 text-xs;
    color: var(--uifn-color-danger-solid);
    border-color: color-mix(in srgb, var(--uifn-color-danger-solid) 35%, transparent);
    background: var(--uifn-color-danger-subtle);
  }

  .sign-in-form__hint {
    @apply m-0 rounded-md px-3 py-2 text-xs;
    color: var(--uifn-color-text-secondary);
    background: var(--uifn-color-surface-sunken);
  }

  .command-dialog__positioner {
    @apply items-start pt-[12vh];
  }

  .command-dialog {
    inline-size: min(calc(100vw - 2rem), 40rem) !important;
    @apply overflow-hidden p-0 shadow-overlay;
  }

  .command-dialog [data-uifn-component='command'] {
    inline-size: 100%;
    @apply border-0 shadow-none;
  }

  .command-dialog__search {
    @apply flex h-14 items-center gap-3 border-b px-4;
    border-color: var(--uifn-color-border-subtle);
  }

  .command-dialog__search > svg { color: var(--uifn-color-text-muted); }

  .command-dialog__search [data-uifn-part='input'] {
    @apply h-full flex-1 border-0 bg-transparent px-0 text-sm outline-none;
  }

  .command-dialog__search [data-uifn-part='close'] {
    @apply min-h-0 border-0 bg-transparent p-0;
  }

  .command-dialog__search [data-uifn-part='close'] span {
    @apply rounded border px-1.5 py-0.5 text-[0.65rem];
    color: var(--uifn-color-text-muted);
    border-color: var(--uifn-color-border-default);
    background: var(--uifn-color-surface-sunken);
  }

  .command-dialog__list {
    @apply max-h-[25rem] overflow-auto p-2;

    @apply max-h-[25rem] overflow-auto p-2;
  }

  .command-dialog [data-uifn-part='groupHeading'] {
    @apply px-2 pb-1 pt-3 text-[0.65rem] font-bold uppercase tracking-[0.12em];
    color: var(--uifn-color-text-muted);
  }

  .command-dialog [data-uifn-part='item'] {
    @apply flex cursor-pointer items-center gap-3 rounded-md px-2.5 py-2 text-sm;
  }

  .command-dialog [data-uifn-part='item']:hover,
  .command-dialog [data-uifn-part='item'][data-highlighted='true'] {
    background: var(--uifn-color-accent-subtle);
  }

  .command-dialog__item-icon {
    @apply grid h-7 w-7 place-items-center rounded-md;
    color: var(--uifn-color-text-secondary);
    background: var(--uifn-color-surface-sunken);
  }

  .command-dialog [data-uifn-part='shortcut'] {
    @apply ml-auto text-[0.65rem];
    color: var(--uifn-color-text-muted);
  }

  .command-dialog [data-uifn-part='empty'] {
    @apply px-4 py-12 text-center text-sm;
    color: var(--uifn-color-text-muted);
  }
}

@media (max-width: 1180px) {
  .operator-shell {
    grid-template-columns: 14.5rem minmax(0, 1fr);
  }

  .context-switcher > [data-uifn-component='select']:nth-of-type(n + 3),
  .context-switcher__separator:nth-of-type(n + 3) {
    @apply hidden;
  }

  .operator-search-trigger {
    min-inline-size: auto;
  }

  .operator-search-trigger [data-uifn-part='label'] {
    @apply sr-only;
  }
}

@media (max-width: 940px) {
  .operator-shell {
    @apply block;
  }

  .operator-sidebar {
    @apply fixed left-0 top-0 -translate-x-full shadow-overlay transition-transform;
    inline-size: min(18rem, calc(100vw - 3rem));
  }

  .operator-shell--nav-open .operator-sidebar {
    @apply translate-x-0;
  }

  .operator-shell--nav-open .operator-shell__scrim {
    @apply block;
  }

  .operator-sidebar__close,
  .operator-topbar__menu {
    @apply inline-flex;
  }

  .operator-topbar {
    @apply px-3;
  }

  .operator-main {
    @apply px-4 pt-5;
  }

  .overview-grid,
  .detail-grid,
  .settings-grid,
  .mcp-grid {
    @apply grid-cols-1;
  }
}

@media (max-width: 680px) {
  .operator-topbar {
    @apply h-auto min-h-[4rem] flex-wrap gap-1 py-2;
  }

  .context-switcher {
    @apply order-3 w-full overflow-x-auto border-t pt-1;
    border-color: var(--uifn-color-border-subtle);
  }

  .context-switcher > [data-uifn-component='select']:nth-of-type(n + 3) {
    @apply block;
  }

  .operator-topbar__actions {
    @apply ml-auto;
  }

  .operator-search-trigger kbd {
    @apply hidden;
  }

  .page-header {
    @apply mb-5 grid gap-4;
  }

  .page-header__actions {
    @apply justify-start;
  }

  .metrics-grid,
  .module-grid,
  .resource-card-grid,
  .job-grid,
  .artifact-grid {
    @apply grid-cols-1;
  }

  .summary-strip,
  .run-summary {
    @apply grid-cols-2;
  }

