  private mcpToolVisible(tool: McpFnListedTool, context: AdminOperationContext): boolean {
    return this.mcpMetadataVisible(tool._meta, context);
  }

  private mcpMetadataVisible(metadata: Record<string, unknown> | undefined, context: AdminOperationContext): boolean {
    const projected = metadata?.['mcpfn/superconsole'];
    if (!projected || typeof projected !== 'object') return false;
    const values = projected as { operationId?: unknown; permission?: unknown };
    if (values.operationId === 'superconsole.confirmations.issue') {
      return this.registry.operations.some((entry) =>
        entry.operation.safety.requiresConfirmation
        && this.hasPermission(context.actor.permissions, entry.operation.permission));
    }
    return typeof values.permission === 'string'
      && this.hasPermission(context.actor.permissions, values.permission);
  }

  private async search(request: Request, state: SuperConsoleRequestState) {
    await this.authorizeShell('search', state);
    if (!this.registry.hasModule('searchfn')) throw new SuperConsoleHttpError('SearchFn is not enabled.', { status: 404, code: 'MODULE_NOT_ENABLED' });
    if (!this.options.search) throw new SuperConsoleHttpError('The SearchFn-backed console search service is unavailable.', { status: 503, code: 'SEARCH_UNAVAILABLE' });
    this.requirePermission(state.principal, this.options.search.permission);
    const url = new URL(request.url);
    const query = url.searchParams.get('q')?.trim() ?? '';
    if (!query) return { results: [], total: 0 };
    const result = await this.options.search.search({
      query,
      cursor: url.searchParams.get('cursor') ?? undefined,
    origin: window.location.origin,
    signedExternal: options.signedExternal,
    scope: new URL(window.location.href).searchParams,
  });
  if (!safeHref) return false;
  const popup = window.open(safeHref, '_blank', 'noopener,noreferrer');
  if (popup) popup.opener = null;
  return popup !== null;
}

export function safeAvatarHref(href: string | undefined): string | undefined {
  if (!href) return undefined;
  if (/^data:image\/(?:png|jpe?g|gif|webp|avif);base64,[a-z0-9+/=\s]+$/i.test(href)) return href;
  let candidate: URL;
  try {
    candidate = new URL(href, typeof window === 'undefined' ? 'http://superconsole.local' : window.location.origin);
  } catch {
    return undefined;
  }
  if (candidate.username || candidate.password) return undefined;
  const currentOrigin = typeof window === 'undefined'
    ? 'http://superconsole.local'
    : window.location.origin;
  if (candidate.origin === currentOrigin && ['http:', 'https:'].includes(candidate.protocol)) {
    return candidate.href;
  }
  return candidate.protocol === 'https:' ? candidate.href : undefined;
}

