const REQUIRED_SET = new Set<string>(REQUIRED_MODULE_IDS);
const OPTIONAL_SET = new Set<string>(OPTIONAL_MODULE_IDS);

const DISPLAY_NAMES: Record<KnownModuleId, string> = {
  apifn: 'ApiFn',
