          : {
              metadata: redactAdminValue(metadata, [
                ...(entry.operation.redaction?.inputFields ?? []),
                ...(entry.operation.redaction?.outputFields ?? []),
              ]) as Readonly<Record<string, unknown>>,
            }),
      });
