import type {
  AdminCapabilityAdapter,
  AdminCapabilityManifest,
  AdminOperationContext,
  AdminOperationHandlers,
  AdminOperationResult,
} from "./types.js";

export interface CreateAdminCapabilityAdapterOptions<
  TManifest extends AdminCapabilityManifest = AdminCapabilityManifest,
> {
  manifest: TManifest;
  handlers: AdminOperationHandlers;
}

function isResult(value: unknown): value is AdminOperationResult {
  return Boolean(
    value &&
      typeof value === "object" &&
      (value as { ok?: unknown }).ok === true &&
      "data" in value,
  );
}

export function createAdminCapabilityAdapter<
  const TManifest extends AdminCapabilityManifest,
>(
  manifestOrOptions: TManifest | CreateAdminCapabilityAdapterOptions<TManifest>,
  providedHandlers?: AdminOperationHandlers,
): AdminCapabilityAdapter<TManifest> {
  const manifest = ("manifest" in manifestOrOptions
    ? manifestOrOptions.manifest
    : manifestOrOptions) as TManifest;
  const handlers = ("manifest" in manifestOrOptions
    ? manifestOrOptions.handlers
    : providedHandlers) ?? {};

  const invoke = async <T = unknown>(
    operationId: string,
    input: unknown,
    context: AdminOperationContext,
  ): Promise<AdminOperationResult<T>> => {
    const operation = manifest.operations.find((candidate) => candidate.id === operationId);
    if (!operation) {
      throw new Error(`Unknown admin operation: ${manifest.id}.${operationId}`);
    }
    const handler = handlers[operationId];
    if (!handler) {
      throw new Error(`No handler registered for admin operation: ${manifest.id}.${operationId}`);
    }
    const value = await handler({ input, context });
    return (isResult(value)
      ? value
      : {
          ok: true,
          data: value,
          requestId: context.requestId,
          correlationId: context.correlationId,
        }) as AdminOperationResult<T>;
  };

  return { manifest, handlers, invoke, execute: invoke };
}

export const createAdminAdapter = createAdminCapabilityAdapter;
import type { McpFnObjectSchema, McpFnToolDefinition } from "@mcpfn/core";
import { AdminError } from "./errors.js";
import type { AdminDispatcher } from "./dispatcher.js";
import type { AdminCapabilityRegistry, AdminRegistryOperation } from "./registry.js";
import type { AdminOperationContext, AdminResult } from "./types.js";

export interface AdminMcpProjectionOptions {
  registry: AdminCapabilityRegistry;
  dispatcher: AdminDispatcher;
}

export interface McpFnCompatibleRegistry<TContext> {
  register(definition: McpFnToolDefinition<TContext>): unknown;
}

function isMcpEnabled(value: unknown): boolean {
  return value !== false && !(value && typeof value === "object" && "enabled" in value && (value as { enabled?: boolean }).enabled === false);
}

function structuredResult(result: AdminResult): { content: { type: "text"; text: string }[]; structuredContent?: Record<string, unknown>; isError?: boolean } {
  if (result.ok === false) {
    return { content: [{ type: "text", text: JSON.stringify(result) }], isError: true };
  }
  const structuredContent = result as unknown as Record<string, unknown>;
  return { content: [{ type: "text", text: JSON.stringify(structuredContent) }], structuredContent };
}

function mcpOutputSchema(entry: AdminRegistryOperation): McpFnObjectSchema | undefined {
  const output = entry.operation.outputSchema;
  if (!output) return undefined;
  return {
    type: "object",
    properties: {
      ok: { type: "boolean", const: true },
      data: output,
      page: {
        type: "object",
        properties: {
          nextCursor: { type: ["string", "null"] },
          hasMore: { type: "boolean" },
        },
        additionalProperties: false,
      },
      auditId: { type: "string" },
      warnings: { type: "array", items: { type: "string" } },
      requestId: { type: "string" },
      correlationId: { type: "string" },
      meta: { type: "object", additionalProperties: true },
    },
    required: ["ok", "data"],
    additionalProperties: false,
  } as McpFnObjectSchema;
}

function mcpInputSchema(entry: AdminRegistryOperation): McpFnObjectSchema {
  const input = entry.operation.inputSchema;
  if (!input || input.type !== "object") throw new AdminError("invalid_argument", `MCP operation ${entry.operation.id} requires an object input schema.`);
  if (entry.operation.safety.classification === "read") return input as McpFnObjectSchema;
  if (input.properties?._admin) throw new AdminError("conflict", `Operation ${entry.operation.id} uses the reserved MCP _admin input field.`);
  const required: string[] = [];
  const properties: Record<string, unknown> = {};
  if (entry.operation.safety.idempotent) {
    properties.idempotencyKey = { type: "string", minLength: 1, description: "Unique key for exactly-once administration execution." };
    required.push("idempotencyKey");
  }
  if (entry.operation.safety.requiresConfirmation) {
    properties.confirmationToken = { type: "string", minLength: 1, description: "Explicit confirmation token issued for this destructive operation." };
    required.push("confirmationToken");
  }
  return {
    ...input,
    properties: {
      ...(input.properties ?? {}),
      _admin: {
        type: "object",
        description: "Reserved Super Console mutation controls; removed before domain validation.",
        properties,
        required,
        additionalProperties: false,
      },
    },
    required: [...new Set([...(input.required ?? []), ...(required.length ? ["_admin"] : [])])],
  } as McpFnObjectSchema;
}

export function projectAdminMcpTools(
  options: AdminMcpProjectionOptions,
): McpFnToolDefinition<AdminOperationContext>[] {
  return options.registry.operations.filter((entry) => isMcpEnabled(entry.operation.mcp)).map((entry) => {
    const input = mcpInputSchema(entry);
    const output = mcpOutputSchema(entry);
    const configured = typeof entry.operation.mcp === "object" ? entry.operation.mcp : undefined;
    const readOnly = entry.operation.safety.classification === "read";
    return {
      name: entry.mcpToolName,
      title: entry.operation.title,
      description: configured?.description ?? `${entry.operation.description} Requires ${entry.operation.permission}; safety=${entry.operation.safety.classification}${entry.operation.safety.requiresConfirmation ? "; explicit confirmation required" : ""}.`,
      inputSchema: input,
      ...(output ? { outputSchema: output } : {}),
      annotations: {
        readOnlyHint: configured?.readOnlyHint ?? readOnly,
        destructiveHint: configured?.destructiveHint ?? entry.operation.safety.classification === "destructive",
        idempotentHint: configured?.idempotentHint ?? Boolean(entry.operation.safety.idempotent),
        openWorldHint: false,
      },
      metadata: {
        "mcpfn/superconsole": {
          moduleId: entry.moduleId,
          operationId: entry.operation.id,
          permission: entry.operation.permission,
          safety: entry.operation.safety,
          capabilityVersion: entry.manifest.version,
          ...(entry.operation.pagination ? { pagination: entry.operation.pagination } : {}),
          ...(entry.operation.target ? { target: entry.operation.target } : {}),
          ...(entry.operation.redaction ? { redaction: entry.operation.redaction } : {}),
        },
      },
      handler: async (args, context) => {
        const { _admin, ...domainInput } = args;
        const controls = _admin && typeof _admin === "object" && !Array.isArray(_admin)
          ? _admin as { idempotencyKey?: unknown; confirmationToken?: unknown }
          : {};
        return structuredResult(await options.dispatcher.dispatch({
          operationId: entry.operation.id,
          input: domainInput,
          context: {
            ...context,
            source: "mcp",
            idempotencyKey: typeof controls.idempotencyKey === "string" ? controls.idempotencyKey : undefined,
            confirmationToken: typeof controls.confirmationToken === "string" ? controls.confirmationToken : undefined,
          },
        }));
      },
    };
  });
}

export function registerAdminMcpTools(
  target: McpFnCompatibleRegistry<AdminOperationContext>,
  options: AdminMcpProjectionOptions,
): McpFnToolDefinition<AdminOperationContext>[] {
  const tools = projectAdminMcpTools(options);
  tools.forEach((tool) => target.register(tool));
  return tools;
}
import { AdminError } from "./errors.js";
import type { AdminCapabilityRegistry, AdminRegistryOperation } from "./registry.js";
import type { AdminJsonSchema, AdminObjectSchema } from "./types.js";

export interface AdminOpenApiOptions {
  title?: string;
  version?: string;
  description?: string;
  serverUrl?: string;
  securitySchemes?: Readonly<Record<string, unknown>>;
}

export interface AdminOpenApiDocument {
  openapi: "3.1.0";
  info: { title: string; version: string; description?: string };
  servers?: readonly { url: string }[];
  paths: Record<string, Record<string, unknown>>;
  components: Record<string, unknown>;
  tags: readonly Record<string, unknown>[];
  [extension: `x-${string}`]: unknown;
}

const ERROR_SCHEMA: AdminObjectSchema = {
  type: "object",
  properties: {
    ok: { type: "boolean", const: false },
    error: {
      type: "object",
      properties: {
        code: { type: "string" },
        message: { type: "string" },
        status: { type: "integer" },
        details: {},
        retryable: { type: "boolean" },
      },
      required: ["code", "message", "status"],
      additionalProperties: false,
    },
    requestId: { type: "string" },
    correlationId: { type: "string" },
    auditId: { type: "string" },
    meta: { type: "object", additionalProperties: true },
  },
  required: ["ok", "error"],
  additionalProperties: false,
};

const SCOPE_QUERY_PARAMETERS: readonly Record<string, unknown>[] = [
  { name: "organizationId", in: "query", required: false, description: "Override the authenticated organization. Also accepted as X-SuperConsole-Organization-Id or X-Admin-Organization-Id.", schema: { type: "string", minLength: 1 } },
  { name: "workspaceId", in: "query", required: false, description: "Override the authenticated workspace. Also accepted as X-SuperConsole-Workspace-Id or X-Admin-Workspace-Id.", schema: { type: "string", minLength: 1 } },
  { name: "projectId", in: "query", required: false, description: "Override the authenticated project. Also accepted as X-SuperConsole-Project-Id or X-Admin-Project-Id.", schema: { type: "string", minLength: 1 } },
  { name: "environmentId", in: "query", required: false, description: "Override the authenticated environment. Also accepted as X-SuperConsole-Environment-Id or X-Admin-Environment-Id.", schema: { type: "string", minLength: 1 } },
  { name: "namespace", in: "query", required: false, description: "Optional execution namespace; also accepted as X-SuperConsole-Namespace.", schema: { type: "string" } },
  { name: "region", in: "query", required: false, description: "Optional execution region; also accepted as X-SuperConsole-Region.", schema: { type: "string" } },
];

export function adminOpenApiScopeParameters(): Record<string, unknown>[] {
  return SCOPE_QUERY_PARAMETERS.map((parameter) => ({ ...parameter }));
}

function route(entry: AdminRegistryOperation): { method: string; path: string; parameterNames: string[] } {
  const method = typeof entry.operation.route === "string"
    ? entry.operation.route.trim().split(/\s+/, 1)[0]!.toUpperCase()
    : entry.operation.route.method;
  const parameterNames: string[] = [];
  const path = entry.routePath
    .replace(/:([A-Za-z_][A-Za-z0-9_]*)/g, (_, name: string) => { parameterNames.push(name); return `{${name}}`; })
    .replace(/\{([A-Za-z_][A-Za-z0-9_]*)\}/g, (_, name: string) => { if (!parameterNames.includes(name)) parameterNames.push(name); return `{${name}}`; });
  return { method, path, parameterNames };
}

function withoutProperties(schema: AdminJsonSchema, names: readonly string[]): AdminJsonSchema | undefined {
  if (schema.type !== "object" || !schema.properties) return schema;
  const properties = Object.fromEntries(Object.entries(schema.properties).filter(([name]) => !names.includes(name)));
  if (Object.keys(properties).length === 0) return undefined;
  return { ...schema, properties, required: schema.required?.filter((name) => !names.includes(name)) };
}

function parametersFor(schema: AdminJsonSchema, parameterNames: readonly string[], includeQuery: boolean): Record<string, unknown>[] {
  const parameters: Record<string, unknown>[] = [];
  for (const name of parameterNames) {
    parameters.push({ name, in: "path", required: true, schema: schema.properties?.[name] ?? { type: "string" } });
  }
  if (includeQuery && schema.type === "object") {
    for (const [name, property] of Object.entries(schema.properties ?? {})) {
      if (!parameterNames.includes(name)) {
        const types = property.type === undefined
          ? []
          : Array.isArray(property.type) ? property.type : [property.type];
        parameters.push({
          name,
          in: "query",
          required: schema.required?.includes(name) ?? false,
          ...(types.includes("object") || types.includes("array")
            ? {
                description: "JSON-encoded query parameter.",
                content: { "application/json": { schema: property } },
              }
            : { schema: property }),
        });
      }
    }
  }
  return parameters;
}

export function createAdminOpenApiDocument(
  registry: AdminCapabilityRegistry,
  options: AdminOpenApiOptions = {},
): AdminOpenApiDocument {
  const securitySchemes = options.securitySchemes ?? {
    authFnSession: { type: "apiKey", in: "cookie", name: "__Secure-authfn.session" },
    authFnApiKey: { type: "http", scheme: "bearer", bearerFormat: "AuthFn session or API key" },
  };
  if (!securitySchemes.authFnSession || !securitySchemes.authFnApiKey) {
    throw new AdminError(
      "invalid_argument",
      "OpenAPI security schemes must define authFnSession and authFnApiKey because protected operations reference both schemes.",
    );
  }
  const paths: Record<string, Record<string, unknown>> = {};
  for (const entry of registry.operations) {
    const { method, path, parameterNames } = route(entry);
    const input = entry.operation.inputSchema;
    const output = entry.operation.outputSchema;
    if (!input || !output) throw new AdminError("internal", `Operation ${entry.operation.id} has incomplete schemas.`);
    const isReadMethod = method === "GET" || method === "DELETE";
    const parameters = parametersFor(input, parameterNames, isReadMethod);
    for (const scopeParameter of adminOpenApiScopeParameters()) {
      if (!parameters.some((parameter) => parameter.name === scopeParameter.name && parameter.in === scopeParameter.in)) {
        parameters.push(scopeParameter);
      }
    }
    if (entry.operation.safety.classification !== "read" && entry.operation.safety.idempotent) {
      parameters.push({
        name: "Idempotency-Key",
        in: "header",
        required: true,
        description: "Unique key scoped to actor, tenant scope, and operation.",
        schema: { type: "string", minLength: 1 },
      });
    }
    if (entry.operation.safety.classification !== "read") {
      parameters.push({
        name: "X-AuthFn-CSRF",
        in: "header",
        required: false,
        description: "Required for unsafe requests authenticated by an AuthFn cookie session; bearer/API-key authentication does not use CSRF validation.",
        schema: { type: "string", minLength: 1 },
      });
    }
    if (entry.operation.safety.requiresConfirmation) {
      parameters.push({
        name: "X-Admin-Confirmation",
        in: "header",
        required: true,
        description: "Expiring actor/scope/operation/input-bound confirmation token.",
        schema: { type: "string", minLength: 1 },
      });
    }
    const bodySchema = isReadMethod ? undefined : withoutProperties(input, parameterNames);
    const successSchema: AdminObjectSchema = {
      type: "object",
      properties: {
        ok: { type: "boolean", const: true },
        data: output,
        requestId: { type: "string" },
        correlationId: { type: "string" },
        auditId: { type: "string" },
        page: {
          type: "object",
          properties: {
            nextCursor: { type: ["string", "null"] },
            hasMore: { type: "boolean" },
          },
          additionalProperties: false,
        },
        warnings: { type: "array", items: { type: "string" } },
        meta: { type: "object", additionalProperties: true },
      },
      required: ["ok", "data"],
      additionalProperties: true,
    };
    const operation: Record<string, unknown> = {
      operationId: entry.operation.id,
      summary: entry.operation.title,
      description: entry.operation.description,
      tags: [entry.manifest.displayName],
      security: [{ authFnSession: [] }, { authFnApiKey: [] }],
      ...(parameters.length ? { parameters } : {}),
      ...(bodySchema ? { requestBody: { required: true, content: { "application/json": { schema: bodySchema } } } } : {}),
      responses: {
        "200": { description: "Administration operation completed.", content: { "application/json": { schema: successSchema } } },
        "4XX": { description: "Administration request rejected.", content: { "application/json": { schema: { $ref: "#/components/schemas/AdminError" } } } },
        "5XX": { description: "Administration dependency or server failure.", content: { "application/json": { schema: { $ref: "#/components/schemas/AdminError" } } } },
      },
      "x-superfunctions-module": entry.moduleId,
      "x-superfunctions-capability-version": entry.manifest.version,
      "x-superfunctions-permission": entry.operation.permission,
      "x-superfunctions-safety": entry.operation.safety,
      ...(entry.operation.pagination ? { "x-superfunctions-pagination": entry.operation.pagination } : {}),
      ...(entry.operation.target ? { "x-superfunctions-target": entry.operation.target } : {}),
      ...(entry.operation.redaction ? { "x-superfunctions-redaction": entry.operation.redaction } : {}),
    };
    paths[path] ??= {};
    if (paths[path]![method.toLowerCase()]) throw new AdminError("conflict", `OpenAPI operation collision: ${method} ${path}.`);
    paths[path]![method.toLowerCase()] = operation;
  }

  return {
    openapi: "3.1.0",
    info: {
      title: options.title ?? "Super Console Administration API",
      version: options.version ?? "1.0.0",
      ...(options.description ? { description: options.description } : {}),
    },
    ...(options.serverUrl ? { servers: [{ url: options.serverUrl }] } : {}),
    paths,
    components: {
      schemas: { AdminError: ERROR_SCHEMA },
      securitySchemes,
    },
    tags: registry.manifests.map((manifest) => ({
      name: manifest.displayName,
      description: manifest.description,
      "x-superfunctions-module": manifest.id,
      ...(manifest.owner ? { "x-superfunctions-owner": manifest.owner } : {}),
    })),
    "x-superfunctions-enabled-modules": registry.enabledModuleIds,
    "x-superfunctions-registry-schema": "1.0",
  };
}

export const generateAdminOpenApi = createAdminOpenApiDocument;

