const JSON_HEADERS = { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' };
const READ_METHODS = new Set(['GET', 'HEAD', 'OPTIONS']);

interface HttpErrorOptions {
  status: number;
  code: string;
  details?: unknown;
}

class SuperConsoleHttpError extends Error {
  readonly status: number;
  readonly code: string;
  readonly details?: unknown;
  constructor(message: string, options: HttpErrorOptions) {
    super(message);
    this.name = 'SuperConsoleHttpError';
    this.status = options.status;
    this.code = options.code;
    this.details = options.details;
  }
}

function response(body: unknown, status = 200, extraHeaders?: HeadersInit): Response {
  const headers = new Headers(JSON_HEADERS);
  // AuthFn can emit both a session cookie and a CSRF cookie. Read an incoming
  // Headers instance directly so constructing a second Headers object cannot
  // coalesce Set-Cookie values containing Expires commas.
  const incoming = extraHeaders instanceof Headers ? extraHeaders : new Headers(extraHeaders);
  incoming.forEach((value, key) => {
    if (key !== 'set-cookie') headers.append(key, value);
  });
  const cookieHeaders = incoming as Headers & { getSetCookie?: () => string[] };
  for (const cookie of cookieHeaders.getSetCookie?.() ?? []) headers.append('set-cookie', cookie);
  if (!cookieHeaders.getSetCookie && incoming.has('set-cookie')) headers.append('set-cookie', incoming.get('set-cookie')!);
  return new Response(JSON.stringify(body), { status, headers });
}

function success(data: unknown, requestId?: string, headers?: HeadersInit, status = 200): Response {
  return response({ ok: true, data, ...(requestId ? { requestId } : {}) }, status, headers);
}

function failure(error: unknown, requestId?: string): Response {
  if (error instanceof SuperConsoleHttpError) {
    return response({
      ok: false,
      error: { code: error.code, message: error.message, status: error.status, ...(error.details === undefined ? {} : { details: error.details }) },
      ...(requestId ? { requestId } : {}),
    }, error.status);
  }
  if (error instanceof AuthFnError) {
    return response({
      ok: false,
      error: {
        code: error.code,
        message: error.message,
        status: error.status,
        retryable: error.retryable,
      },
      ...(requestId ? { requestId } : {}),
    }, error.status);
  }
  if (isAuthFnResponseError(error)) {
    const source = error.authFnResponse;
    const headers = new Headers();
    const sourceCookies = source.headers as Headers & { getSetCookie?: () => string[] };
    for (const cookie of sourceCookies.getSetCookie?.() ?? []) headers.append('set-cookie', cookie);
    for (const name of ['retry-after', 'x-request-id']) {
      const value = source.headers.get(name);
      if (value) headers.set(name, value);
    }
    headers.set('content-type', source.headers.get('content-type') ?? 'application/json; charset=utf-8');
    headers.set('cache-control', 'no-store');
    return new Response(source.body, { status: source.status, headers });
  }
  const normalized = normalizeAdminError(error, { requestId });
  return response(normalized, normalized.error.status);
}

function readScopeValue(url: URL, request: Request, name: 'organization' | 'workspace' | 'project' | 'environment'): string | undefined {
  return url.searchParams.get(`${name}Id`)
    ?? url.searchParams.get(name)
    ?? request.headers.get(`x-superconsole-${name}-id`)
    ?? request.headers.get(`x-admin-${name}-id`)
    ?? undefined;
}

function requestedScope(request: Request, principal: SuperConsolePrincipal): AdminScope {
  const url = new URL(request.url);
  return {
    organizationId: readScopeValue(url, request, 'organization') ?? principal.defaultScope.organizationId,
    workspaceId: readScopeValue(url, request, 'workspace') ?? principal.defaultScope.workspaceId,
    projectId: readScopeValue(url, request, 'project') ?? principal.defaultScope.projectId,
    environmentId: readScopeValue(url, request, 'environment') ?? principal.defaultScope.environmentId,
    namespace: url.searchParams.get('namespace') ?? request.headers.get('x-superconsole-namespace') ?? principal.defaultScope.namespace,
    region: url.searchParams.get('region') ?? request.headers.get('x-superconsole-region') ?? principal.defaultScope.region,
  };
}

function assertCompleteScope(scope: AdminScope): void {
  for (const key of ['organizationId', 'workspaceId', 'projectId', 'environmentId'] as const) {
