output.text:
# Super Console

Super Console is the self-hosted, explicitly composed operator administration
surface for Superfunctions. Enabled function adapters remain authoritative for
operations, schemas, policy targets, redaction, audit, REST/OpenAPI, the
TypeScript client, and McpFn tools. Customer-facing portals are separate apps.

## Installation module

Create a deployment module and compile it as part of your server application:

```ts
import {
  createAuthFnOperatorAuth,
  createSuperConsole,
  type SuperConsolePrincipal,
} from "superconsole/server";
import { authFnConfig } from "./authfn-config.js";
import { adminAdapters, services } from "./superfunctions.js";

const auth = createAuthFnOperatorAuth({
  config: authFnConfig,
  resolveOperator: async ({ session }): Promise<SuperConsolePrincipal | null> =>
    services.operators.resolve(session.actorId),
  authorizeScope: ({ principal, requested }) =>
    services.operators.authorizeScope(principal, requested),
});

export const superConsole = createSuperConsole({
  adapters: adminAdapters,
  enabledModules: [
    "authfn",
    "watchfn",
    "plugfn",
    "sendfn",
    "mailfn",
    "billfn",
    "filefn",
  ],
  auth,
  shellPolicy: services.shellPolicy,
  policy: services.adminPolicy,
  audit: services.watchFnAuditSink,
  auditQuery: services.watchFnAuditQuery,
  idempotency: services.durableIdempotency,
  confirmation: services.boundConfirmations,
  search: services.searchFn,
  overview: services.overview,
  settings: services.settings,
  // Set this when AuthFn's cookie prefix/policy differs from its secure default.
  // Keep the authFnSession/authFnApiKey keys used by protected operations.
  openApiSecuritySchemes: services.openApiSecuritySchemes,
});
```

Every enabled module must have a registered adapter. Use `[]` for a shell-only
installation. Nested `catchfn`/`logfn` require `watchfn`; `contentfn` requires
`cmsfn`. Startup fails closed when enabled operations require infrastructure
that was not injected: a required audit sink, atomic idempotency store,
AuthFn-owned mutation authorization, or a bound confirmation issuer/verifier.
Required-audit mutations and confirmation issuance append a sanitized
`attempted` event before invoking the mutable dependency, then append a
terminal outcome. The audit sink and function/confirmation store are separate
systems: this fail-closed preflight does not claim a cross-store transaction,
so deployments must monitor terminal-event failures and reconcile attempts.

Set `SUPERCONSOLE_INSTALLATION` to the absolute filesystem path or `file://`
URL of the compiled module. The loader accepts `superConsole`, `default`, or an
async `createSuperConsoleInstallation` export and loads it once per process.

```sh
SUPERCONSOLE_INSTALLATION=file:///srv/app/dist/super-console-installation.js \
  node build
```

The stable server-only package entry is `superconsole/server`; browser code
must not import it.

## Administration surfaces

- `/api/admin/v1/registry` discovers enabled manifests and authorized shell surfaces.
- `/api/admin/v1/openapi.json` exposes OpenAPI 3.1 after shell authorization.
- `/api/admin/v1/modules/:moduleId/**` dispatches enabled function operations.
- `/api/admin/v1/confirmations` issues actor/scope/operation/input-bound tokens.
- `/api/admin/v1/mcp/transport` is the authenticated McpFn streamable-HTTP endpoint.
- `/api/admin/v1/auth/sign-in`, `/auth/2fa`, and `/auth/sign-out` delegate to AuthFn.

Automation consumers can use `@superfunctions/admin`'s `createAdminClient` for
registry, overview, search, audit, settings, MCP metadata, confirmation
issuance, route invocation, and operation-ID invocation. McpFn mutations carry
reserved controls under `_admin`; those fields are stripped before domain
validation and never enter function storage.

HTTP requests are recorded with `source: "rest"`; callers cannot override
audit provenance with a request header. McpFn invocations are recorded as
`source: "mcp"`, while direct in-process SDK dispatchers set their own trusted
source in `AdminOperationContext`.

UIFn powers the operator shell and shared visual system. AuthFn, WatchFn,
SearchFn, McpFn, and enabled product functions power their respective runtime
capabilities; Super Console does not replace them with local substitutes.
import { describe, expect, it, vi } from 'vitest';
import {
  MemoryAdminAuditSink,
  MemoryAdminIdempotencyStore,
  AdminClient,
  createAdminCapabilityAdapter,
  defineAdminCapability,
  type AdminCapabilityManifest,
  type AdminOperationContext,
} from '@superfunctions/admin';
import { clearSuperConsoleForTesting, createSuperConsole, loadSuperConsoleInstallation, resolveSuperConsoleInstallationUrl, type SuperConsoleOperatorAuth, type SuperConsolePrincipal } from '../../src/lib/server';
import { authFnPasswordPlugin, authFnTwoFactorPlugin, confirmTwoFactorEnrollment, createAuthFn, createTwoFactorEnrollment, listActiveSessionsForUser } from '@authfn/core';
import { memoryAdapter } from '@superfunctions/db/testing';
import { createAuthFnOperatorAuth } from '../../src/lib/server/authfn';
import { createHmac } from 'node:crypto';

const scope = {
  organizationId: 'org_1',
  workspaceId: 'workspace_1',
  projectId: 'project_1',
  environmentId: 'environment_1',
  namespace: 'tenant_1',
  region: 'in-south',
};

const principal: SuperConsolePrincipal = {
  actor: { id: 'operator_1', permissions: ['*'] },
  displayName: 'Operator One',
  email: 'operator@example.test',
  role: 'installation administrator',
  defaultScope: scope,
};

function auth(overrides: Partial<SuperConsoleOperatorAuth> = {}): SuperConsoleOperatorAuth {
  return {
    authenticate: async () => principal,
    authorizeScope: async ({ requested }) => requested,
    authorizeMutation: async () => undefined,
    ...overrides,
  };
}

function manifest(options: { destructive?: boolean } = {}): AdminCapabilityManifest {
  const destructive = options.destructive ?? false;
  return defineAdminCapability({
    schemaVersion: '1.0',
    id: 'examplefn',
    displayName: 'ExampleFn',
    version: '1.0.0',
    description: 'Operate ExampleFn.',
    category: 'test',
    availability: 'optional-product',
    scopeLevels: ['organization', 'workspace', 'project', 'environment'],
    navigation: [{ id: 'examplefn', label: 'ExampleFn', path: '/modules/examplefn' }],
    operations: [{
      id: destructive ? 'examplefn.records.delete' : 'examplefn.records.list',
      title: destructive ? 'Delete record' : 'List records',
      description: destructive ? 'Delete one record.' : 'List records.',
      inputSchema: destructive
        ? { type: 'object', properties: { id: { type: 'string', minLength: 1 } }, required: ['id'], additionalProperties: false }
        : { type: 'object', properties: { limit: { type: 'integer', minimum: 1, maximum: 200 } }, additionalProperties: false },
      outputSchema: destructive
        ? { type: 'object', properties: { accepted: { type: 'boolean' } }, required: ['accepted'], additionalProperties: false }
        : { type: 'object', properties: { items: { type: 'array', items: { type: 'object' } } }, required: ['items'], additionalProperties: false },
      route: { method: destructive ? 'DELETE' : 'GET', path: destructive ? '/resources/records/:id' : '/resources/records' },
      permission: destructive ? 'examplefn.records.delete' : 'examplefn.records.read',
      safety: destructive
        ? { classification: 'destructive', idempotent: true, requiresConfirmation: true, audit: 'required' }
        : { classification: 'read', idempotent: true, audit: 'optional' },
      target: destructive ? { resource: 'records', idInput: 'id' } : { resource: 'records', collection: true },
      mcp: { readOnlyHint: !destructive, destructiveHint: destructive, idempotentHint: true },
    }],
  });
}

function installation(options: { destructive?: boolean; permissions?: string[] } = {}) {
  const capability = manifest({ destructive: options.destructive });
  const handler = vi.fn(async ({ input }: { input: unknown; context: AdminOperationContext }) => ({
    ok: true as const,
    data: options.destructive ? { accepted: true } : { items: [{ id: 'record_1', input }] },
  }));
  const operator = {
    ...principal,
    actor: { ...principal.actor, permissions: options.permissions ?? ['*'] },
  };
  const confirmation = {
    issue: vi.fn(async () => ({ token: 'bound-token', expiresAt: '2026-08-13T10:00:00.000Z' })),
    verify: vi.fn(async ({ token }: { token: string }) => token === 'bound-token'),
  };
  const audit = new MemoryAdminAuditSink();
  const console = createSuperConsole({
    adapters: [createAdminCapabilityAdapter(capability, { [capability.operations[0]!.id]: handler })],
    enabledModules: ['examplefn'],
    auth: auth({ authenticate: async () => operator }),
    shellPolicy: { authorize: () => true },
    audit,
    idempotency: new MemoryAdminIdempotencyStore(),
    confirmation,
  });
  return { console, handler, confirmation, audit };
}

function request(path: string, init: RequestInit = {}) {
  return new Request(`https://console.example.test${path}`, init);
}

function cookieHeader(cookies: string[]): string {
  return cookies.map((cookie) => cookie.slice(0, cookie.indexOf(';'))).join('; ');
}

describe('Super Console server composition', () => {
  it('rejects non-absolute self-host installation modules before import', async () => {
    clearSuperConsoleForTesting();
    await expect(loadSuperConsoleInstallation('./installation.js')).rejects.toThrow(/absolute filesystem path or file URL/);
    clearSuperConsoleForTesting();
    expect(resolveSuperConsoleInstallationUrl('/srv/app/installation.js')).toBe('file:///srv/app/installation.js');
    expect(resolveSuperConsoleInstallationUrl('file:///srv/app/installation.js')).toBe('file:///srv/app/installation.js');
    expect(() => resolveSuperConsoleInstallationUrl('https://example.test/installation.js')).toThrow(/absolute filesystem path or file URL/);
  });

  it('exposes only explicitly enabled module registry, OpenAPI, navigation and MCP tools', async () => {
    const { console } = installation();
    const registry = await console.handle(request('/api/admin/v1/registry'));
    expect(registry.status).toBe(200);
    expect(await registry.json()).toMatchObject({
      data: {
        modules: [{ id: 'examplefn', enabled: true }],
        enabledModules: [{ id: 'examplefn' }],
        surfaces: { overview: true, api: true, mcp: true, settings: true, audit: false, search: false },
      },
    });
    const client = new AdminClient({
      baseUrl: 'https://console.example.test/api/admin/v1',
      fetch: (input, init) => console.handle(new Request(input, init)),
    });
    expect((await client.registry()).map((capability) => capability.id)).toEqual(['examplefn']);
    expect(JSON.stringify(console.openApi)).toContain('examplefn.records.list');
    const genericInvoke = console.openApi.paths['/api/admin/v1/operations/{operationId}']?.post as { security?: unknown[]; parameters?: Array<{ name: string }> };
    expect(genericInvoke.security).toHaveLength(2);
    expect(genericInvoke.parameters?.map(({ name }) => name)).toEqual(expect.arrayContaining(['operationId', 'organizationId', 'workspaceId', 'projectId', 'environmentId', 'namespace', 'region']));
    expect(console.openApi.components.securitySchemes).toMatchObject({ authFnSession: { name: '__Secure-authfn.session' } });
    expect(console.mcpTools.map((tool) => tool.name)).toEqual(['superconsole_examplefn_records_list']);
    expect((await console.handle(request('/api/admin/v1/modules/disabledfn'))).status).toBe(404);
  });

  it('projects an installation-specific AuthFn cookie policy into OpenAPI', () => {
    const capability = manifest();
    const console = createSuperConsole({
      adapters: [createAdminCapabilityAdapter(capability, {
        'examplefn.records.list': async () => ({ ok: true as const, data: { items: [] } }),
      })],
      enabledModules: ['examplefn'],
      auth: auth(),
      shellPolicy: { authorize: () => true },
      openApiSecuritySchemes: {
        authFnSession: { type: 'apiKey', in: 'cookie', name: 'custom-authfn.session' },
        authFnApiKey: { type: 'http', scheme: 'bearer', bearerFormat: 'AuthFn API key' },
      },
    });

    expect(console.openApi.components.securitySchemes).toEqual({
      authFnSession: { type: 'apiKey', in: 'cookie', name: 'custom-authfn.session' },
      authFnApiKey: { type: 'http', scheme: 'bearer', bearerFormat: 'AuthFn API key' },
    });
    expect(() => createSuperConsole({
      adapters: [],
      enabledModules: [],
      auth: auth(),
      shellPolicy: { authorize: () => true },
      openApiSecuritySchemes: { authFnSession: { type: 'apiKey' } } as never,
    })).toThrow(/authFnSession and authFnApiKey/);
  });

  it('extracts all scope levels and routes a generic module call through the dispatcher', async () => {
    const { console, handler } = installation();
    const result = await console.handle(request('/api/admin/v1/modules/examplefn/records?limit=20&organizationId=org_2&workspaceId=workspace_2&projectId=project_2&environmentId=environment_2'));
    expect(result.status).toBe(200);
    expect(handler).toHaveBeenCalledWith(expect.objectContaining({
      input: { limit: 20 },
      context: expect.objectContaining({ scope: expect.objectContaining({ organizationId: 'org_2', workspaceId: 'workspace_2', projectId: 'project_2', environmentId: 'environment_2' }) }),
import { env } from '$env/dynamic/private';
import { bootConfiguredSuperConsole } from '$lib/server/transport';
import type { Handle } from '@sveltejs/kit';

/**
 * Self-host entry seam. Set SUPERCONSOLE_INSTALLATION to an absolute file URL
 * for a module exporting a fully composed `SuperConsole`. Startup validates
