type RenderIntent = 'thumbnail' | 'preview' | 'full' | 'download';
type RenderState = 'ready' | 'processing' | 'pending-local' | 'unsupported';
type RenderPlaceholderKind = 'generic-file' | 'pdf-processing' | 'unsupported-preview';

