import type { CompFnAPI, CompfnEnvelope } from "compfn";
import { AdminError, type AdminOperationResult } from "@superfunctions/admin";
import type { CompFnAdminService, CompFnAdminServiceRequest } from "./index.js";

type JsonRecord = Record<string, unknown>;

export interface CompFnDomainAdminServiceOptions {
  compfn: CompFnAPI;
}

function object(value: unknown, name: string): JsonRecord {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new AdminError("invalid_argument", `${name} must be an object.`);
  }
  return value as JsonRecord;
}

function string(value: unknown, name: string): string {
  if (typeof value !== "string" || value.length === 0) {
    throw new AdminError("invalid_argument", `${name} must be a non-empty string.`);
  }
  return value;
}

function unwrap<T>(value: CompfnEnvelope<T>): T {
  if (value.ok) return value.result;
  const code = value.error.code.endsWith("_NOT_FOUND")
    ? "not_found"
    : value.error.code === "RATE_LIMITED"
      ? "rate_limited"
      : value.error.code === "STORAGE_ERROR" || value.error.code === "ADAPTER_ERROR"
        ? "dependency_unavailable"
        : "invalid_argument";
  throw new AdminError(code, value.error.message, { details: value.error.details });
}

function list(values: object[]): AdminOperationResult<JsonRecord> {
  return { ok: true, data: { items: values.map((value) => ({ ...value })), nextCursor: null } };
}

function item(value: object): AdminOperationResult<JsonRecord> {
  return { ok: true, data: { item: { ...value } } };
}

function accepted(value: object): AdminOperationResult<JsonRecord> {
  return { ok: true, data: { accepted: true, item: { ...value } } };
}

/** Delegates every operation to the configured CompFn API and its namespaced database services. */
export function createCompFnDomainAdminService(
  options: CompFnDomainAdminServiceOptions,
): CompFnAdminService {
  const { compfn } = options;
  return {
    async execute(request: CompFnAdminServiceRequest) {
      const input = object(request.input ?? {}, "input");
      switch (request.operationId) {
        case "compfn.frameworks.list": return list(unwrap(await compfn.frameworks.list()));
        case "compfn.frameworks.get": return item(unwrap(await compfn.frameworks.get(string(input.id, "id"))));
        case "compfn.controls.list": return list(unwrap(await compfn.controls.list(object(input.filter ?? {}, "filter"))));
        case "compfn.controls.get": return item(unwrap(await compfn.controls.get(string(input.id, "id"))));
        case "compfn.checks.list": return list(unwrap(await compfn.checks.list()));
        case "compfn.checks.get": return item(unwrap(await compfn.checks.get(string(input.id, "id"))));
        case "compfn.evidence.list": return list(unwrap(await compfn.evidence.list(object(input.filter ?? {}, "filter"))));
        case "compfn.evidence.get": return item(unwrap(await compfn.evidence.get(string(input.id, "id"))));
        case "compfn.evidence.collect-evidence": {
          const payload = object(input.payload, "payload");
          return accepted(unwrap(await compfn.evidence.create(payload as Parameters<CompFnAPI["evidence"]["create"]>[0])));
        }
        case "compfn.reports.generate-report": {
          const payload = object(input.payload ?? {}, "payload");
          return accepted(unwrap(await compfn.export.auditorPack({
            frameworkId: typeof payload.frameworkId === "string" ? payload.frameworkId : undefined,
            since: typeof payload.since === "number" ? payload.since : undefined,
          })));
        }
        default:
          throw new AdminError("not_found", `Unsupported CompFn admin operation: ${request.operationId}.`);
      }
    },
  };
}

