  'secfn',
  'sendfn',
  'testfn',
  'userfn',
  'watchfn',
] as const;

export const OPTIONAL_MODULE_IDS = [
  'apifn',
  'botfn',
  'cachefn',
  'docsfn',
  'langfn',
  'probefn',
] as const;

export const NESTED_MODULE_IDS = ['catchfn', 'contentfn', 'logfn'] as const;

export const KNOWN_MODULE_IDS = [
  'apifn',
  'authfn',
  'billfn',
  'botfn',
  'browsefn',
  'cachefn',
  'catchfn',
  'cifn',
  'cmsfn',
