import { diffOpenAPI, parseOpenAPI, validateOpenAPI, type OpenAPIDocument } from "@apifn/core";
import { AdminError, type AdminOperationContext } from "@superfunctions/admin";

export interface ApiFnSpecRecord {
  id: string;
  projectId: string;
  name: string;
  version: string;
  document: OpenAPIDocument;
  createdAt: string;
  updatedAt: string;
}
export interface ApiFnEnvironmentRecord {
  id: string;
  projectId: string;
  name: string;
  baseUrl: string;
  enabled: boolean;
  createdAt: string;
  updatedAt: string;
}
export interface ApiFnOperatorStore {
  listSpecs(projectId: string): Promise<ApiFnSpecRecord[]>;
  getSpec(projectId: string, id: string): Promise<ApiFnSpecRecord | null>;
  putSpec(record: ApiFnSpecRecord): Promise<void>;
  deleteSpec(projectId: string, id: string): Promise<boolean>;
  listEnvironments(projectId: string): Promise<ApiFnEnvironmentRecord[]>;
  getEnvironment(projectId: string, id: string): Promise<ApiFnEnvironmentRecord | null>;
  putEnvironment(record: ApiFnEnvironmentRecord): Promise<void>;
  deleteEnvironment(projectId: string, id: string): Promise<boolean>;
}

export class MemoryApiFnOperatorStore implements ApiFnOperatorStore {
  private readonly specs = new Map<string, ApiFnSpecRecord>();
  private readonly environments = new Map<string, ApiFnEnvironmentRecord>();
  private key(projectId: string, id: string) { return `${projectId}\u0000${id}`; }
  async listSpecs(projectId: string) { return [...this.specs.values()].filter((value) => value.projectId === projectId).map((value) => structuredClone(value)); }
  async getSpec(projectId: string, id: string) { const value = this.specs.get(this.key(projectId, id)); return value ? structuredClone(value) : null; }
  async putSpec(record: ApiFnSpecRecord) { this.specs.set(this.key(record.projectId, record.id), structuredClone(record)); }
  async deleteSpec(projectId: string, id: string) { return this.specs.delete(this.key(projectId, id)); }
  async listEnvironments(projectId: string) { return [...this.environments.values()].filter((value) => value.projectId === projectId).map((value) => structuredClone(value)); }
  async getEnvironment(projectId: string, id: string) { const value = this.environments.get(this.key(projectId, id)); return value ? structuredClone(value) : null; }
  async putEnvironment(record: ApiFnEnvironmentRecord) { this.environments.set(this.key(record.projectId, record.id), structuredClone(record)); }
  async deleteEnvironment(projectId: string, id: string) { return this.environments.delete(this.key(projectId, id)); }
}

export interface ApiFnOperatorServiceOptions { store: ApiFnOperatorStore; now?: () => Date }
export interface ApiFnSpecView { id: string; name: string; version: string; title: string; endpointCount: number; createdAt: string; updatedAt: string }
export interface ApiFnRegisterSpecInput { id: string; name: string; document: string | Record<string, unknown> }
export interface ApiFnCompareSpecInput { id: string; candidate: string | Record<string, unknown> }
export interface ApiFnUpsertEnvironmentInput { id: string; name: string; baseUrl: string; enabled?: boolean }

function project(context: AdminOperationContext): string {
  if (!context.scope.projectId) throw new AdminError("invalid_argument", "ApiFn administration requires a project scope.");
  return context.scope.projectId;
}
function specView(record: ApiFnSpecRecord): ApiFnSpecView {
  const endpointCount = Object.values(record.document.paths ?? {}).reduce((count, item) => count + Object.keys(item ?? {}).filter((key) => ["get", "put", "post", "delete", "patch", "options", "head", "trace"].includes(key)).length, 0);
  return { id: record.id, name: record.name, version: record.version, title: record.document.info.title, endpointCount, createdAt: record.createdAt, updatedAt: record.updatedAt };
}
function page<T>(items: T[]) { return { items, nextCursor: null as null }; }
function required(value: string, label: string) { if (!value.trim()) throw new AdminError("invalid_argument", `${label} is required.`); return value; }

export function createApiFnOperatorService(options: ApiFnOperatorServiceOptions) {
  const now = () => (options.now ?? (() => new Date()))().toISOString();
  return {
    async listSpecs(_input: {}, context: AdminOperationContext) { return page((await options.store.listSpecs(project(context))).map(specView)); },
    async getSpec(input: { id: string }, context: AdminOperationContext) { const value = await options.store.getSpec(project(context), input.id); if (!value) throw new AdminError("not_found", "ApiFn spec was not found."); return { item: specView(value) }; },
    async registerSpec(input: ApiFnRegisterSpecInput, context: AdminOperationContext) {
      const projectId = project(context); const document = parseOpenAPI(input.document); const errors = await validateOpenAPI(document);
      if (errors.length) throw new AdminError("invalid_argument", "OpenAPI validation failed.", { details: { errors } });
      const existing = await options.store.getSpec(projectId, input.id); const timestamp = now();
      const record: ApiFnSpecRecord = { id: required(input.id, "id"), projectId, name: required(input.name, "name"), version: document.info.version, document, createdAt: existing?.createdAt ?? timestamp, updatedAt: timestamp };
      await options.store.putSpec(record); return { accepted: true as const, item: specView(record) };
    },
    async compareSpec(input: ApiFnCompareSpecInput, context: AdminOperationContext) { const value = await options.store.getSpec(project(context), input.id); if (!value) throw new AdminError("not_found", "ApiFn baseline spec was not found."); const candidate = parseOpenAPI(input.candidate); const errors = await validateOpenAPI(candidate); if (errors.length) throw new AdminError("invalid_argument", "Candidate OpenAPI validation failed.", { details: { errors } }); return { item: diffOpenAPI(value.document, candidate) }; },
    async deleteSpec(input: { id: string }, context: AdminOperationContext) { if (!await options.store.deleteSpec(project(context), input.id)) throw new AdminError("not_found", "ApiFn spec was not found."); return { accepted: true as const }; },
    async listEnvironments(_input: {}, context: AdminOperationContext) { return page(await options.store.listEnvironments(project(context))); },
    async getEnvironment(input: { id: string }, context: AdminOperationContext) { const value = await options.store.getEnvironment(project(context), input.id); if (!value) throw new AdminError("not_found", "ApiFn environment was not found."); return { item: value }; },
    async upsertEnvironment(input: ApiFnUpsertEnvironmentInput, context: AdminOperationContext) { const projectId = project(context); let parsed: URL; try { parsed = new URL(input.baseUrl); } catch { throw new AdminError("invalid_argument", "baseUrl must be an absolute URL."); } if (!['http:', 'https:'].includes(parsed.protocol)) throw new AdminError("invalid_argument", "baseUrl must use HTTP or HTTPS."); const existing = await options.store.getEnvironment(projectId, input.id); const timestamp = now(); const record: ApiFnEnvironmentRecord = { id: required(input.id, "id"), projectId, name: required(input.name, "name"), baseUrl: parsed.toString(), enabled: input.enabled ?? true, createdAt: existing?.createdAt ?? timestamp, updatedAt: timestamp }; await options.store.putEnvironment(record); return { accepted: true as const, item: record }; },
    async deleteEnvironment(input: { id: string }, context: AdminOperationContext) { if (!await options.store.deleteEnvironment(project(context), input.id)) throw new AdminError("not_found", "ApiFn environment was not found."); return { accepted: true as const }; },
  };
}
