import { AdminError, type AdminOperationContext } from "@superfunctions/admin";

export type BotFnPlatform = "discord" | "slack" | "github" | "linear";

export interface BotFnBotRecord {
  id: string;
  projectId: string;
  name: string;
  enabled: boolean;
  createdAt: string;
  updatedAt: string;
}

export interface BotFnChannelRecord {
  id: string;
  projectId: string;
  botId: string;
  platform: BotFnPlatform;
  externalId: string;
  credentialRef: string;
  enabled: boolean;
  createdAt: string;
  updatedAt: string;
}

export interface BotFnChannelView extends Omit<BotFnChannelRecord, "credentialRef"> {
  credentialConfigured: true;
}

/** Durable persistence boundary owned by BotFn. All methods are project-scoped. */
export interface BotFnOperatorStore {
  listBots(projectId: string): Promise<BotFnBotRecord[]>;
  getBot(projectId: string, id: string): Promise<BotFnBotRecord | null>;
  putBot(value: BotFnBotRecord): Promise<void>;
  deleteBot(projectId: string, id: string): Promise<boolean>;
  listChannels(projectId: string, botId?: string): Promise<BotFnChannelRecord[]>;
  getChannel(projectId: string, id: string): Promise<BotFnChannelRecord | null>;
  putChannel(value: BotFnChannelRecord): Promise<void>;
  deleteChannel(projectId: string, id: string): Promise<boolean>;
}

/** Explicit in-memory implementation for tests and local development. */
export class MemoryBotFnOperatorStore implements BotFnOperatorStore {
  private readonly bots = new Map<string, BotFnBotRecord>();
  private readonly channels = new Map<string, BotFnChannelRecord>();

  private key(projectId: string, id: string): string {
    return `${projectId}\0${id}`;
  }

  async listBots(projectId: string): Promise<BotFnBotRecord[]> {
    return [...this.bots.values()]
      .filter((value) => value.projectId === projectId)
      .map((value) => structuredClone(value));
  }

  async getBot(projectId: string, id: string): Promise<BotFnBotRecord | null> {
    const value = this.bots.get(this.key(projectId, id));
    return value ? structuredClone(value) : null;
  }

  async putBot(value: BotFnBotRecord): Promise<void> {
    this.bots.set(this.key(value.projectId, value.id), structuredClone(value));
  }

  async deleteBot(projectId: string, id: string): Promise<boolean> {
    return this.bots.delete(this.key(projectId, id));
  }

  async listChannels(projectId: string, botId?: string): Promise<BotFnChannelRecord[]> {
    return [...this.channels.values()]
      .filter((value) => value.projectId === projectId && (!botId || value.botId === botId))
      .map((value) => structuredClone(value));
  }

  async getChannel(projectId: string, id: string): Promise<BotFnChannelRecord | null> {
    const value = this.channels.get(this.key(projectId, id));
    return value ? structuredClone(value) : null;
  }

  async putChannel(value: BotFnChannelRecord): Promise<void> {
    this.channels.set(this.key(value.projectId, value.id), structuredClone(value));
  }

  async deleteChannel(projectId: string, id: string): Promise<boolean> {
    return this.channels.delete(this.key(projectId, id));
  }
}

export interface BotFnOperatorServiceOptions {
  store: BotFnOperatorStore;
  /** Verify the referenced credential against the platform before persistence. */
  verifyChannel(
    input: { platform: BotFnPlatform; externalId: string; credentialRef: string },
    context: AdminOperationContext,
  ): Promise<{ accountLabel?: string }>;
  now?: () => Date;
}

function requireProject(context: AdminOperationContext): string {
  if (!context.scope.projectId) {
    throw new AdminError("invalid_argument", "BotFn administration requires a project scope.");
  }
  return context.scope.projectId;
}

function page<T>(items: T[]): { items: T[]; nextCursor: null } {
  return { items, nextCursor: null };
}

function channelView(value: BotFnChannelRecord): BotFnChannelView {
  const { credentialRef: _credentialRef, ...record } = value;
  return { ...record, credentialConfigured: true };
}

export function createBotFnOperatorService(options: BotFnOperatorServiceOptions) {
  const now = () => (options.now?.() ?? new Date()).toISOString();

  return {
    async listBots(_input: Record<string, never>, context: AdminOperationContext) {
      return page(await options.store.listBots(requireProject(context)));
    },

    async getBot(input: { id: string }, context: AdminOperationContext) {
      const value = await options.store.getBot(requireProject(context), input.id);
      if (!value) throw new AdminError("not_found", "BotFn bot was not found.");
      return { item: value };
    },

    async upsertBot(
      input: { id: string; name: string; enabled?: boolean },
      context: AdminOperationContext,
    ) {
      const projectId = requireProject(context);
      if (!input.id.trim() || !input.name.trim()) {
        throw new AdminError("invalid_argument", "Bot id and name are required.");
      }
      const previous = await options.store.getBot(projectId, input.id);
      const updatedAt = now();
      const value: BotFnBotRecord = {
        id: input.id,
        projectId,
        name: input.name,
        enabled: input.enabled ?? true,
        createdAt: previous?.createdAt ?? updatedAt,
        updatedAt,
      };
      await options.store.putBot(value);
      return { accepted: true as const, item: value };
    },

    async deleteBot(input: { id: string }, context: AdminOperationContext) {
      const projectId = requireProject(context);
      if ((await options.store.listChannels(projectId, input.id)).length > 0) {
        throw new AdminError("precondition_failed", "Disconnect bot channels before deleting the bot.");
      }
      if (!await options.store.deleteBot(projectId, input.id)) {
        throw new AdminError("not_found", "BotFn bot was not found.");
      }
      return { accepted: true as const };
    },

    async listChannels(input: { botId?: string }, context: AdminOperationContext) {
      const values = await options.store.listChannels(requireProject(context), input.botId);
      return page(values.map(channelView));
    },

    async getChannel(input: { id: string }, context: AdminOperationContext) {
      const value = await options.store.getChannel(requireProject(context), input.id);
      if (!value) throw new AdminError("not_found", "BotFn channel was not found.");
      return { item: channelView(value) };
    },

    async connectChannel(
      input: {
        id: string;
        botId: string;
        platform: BotFnPlatform;
        externalId: string;
        credentialRef: string;
        enabled?: boolean;
      },
      context: AdminOperationContext,
    ) {
      const projectId = requireProject(context);
      if (!await options.store.getBot(projectId, input.botId)) {
        throw new AdminError("not_found", "BotFn bot was not found.");
      }
      await options.verifyChannel({
        platform: input.platform,
        externalId: input.externalId,
        credentialRef: input.credentialRef,
      }, context);
      const previous = await options.store.getChannel(projectId, input.id);
      const updatedAt = now();
      const value: BotFnChannelRecord = {
        id: input.id,
        projectId,
        botId: input.botId,
        platform: input.platform,
        externalId: input.externalId,
        credentialRef: input.credentialRef,
        enabled: input.enabled ?? true,
        createdAt: previous?.createdAt ?? updatedAt,
        updatedAt,
      };
      await options.store.putChannel(value);
      return { accepted: true as const, item: channelView(value) };
    },

    async disconnectChannel(input: { id: string }, context: AdminOperationContext) {
      if (!await options.store.deleteChannel(requireProject(context), input.id)) {
        throw new AdminError("not_found", "BotFn channel was not found.");
      }
      return { accepted: true as const };
    },
  };
}

export type BotFnOperatorService = ReturnType<typeof createBotFnOperatorService>;
