import { AdminError, type AdminOperationContext } from "@superfunctions/admin";
export interface DocsFnSiteRecord { id: string; projectId: string; name: string; config: ManifestConfig; createdAt: string; updatedAt: string }
export interface DocsFnBuildRecord { id: string; projectId: string; siteId: string; status: "succeeded" | "failed"; pageCount: number; postCount: number; apiCount: number; error?: string; createdAt: string }
export interface DocsFnOperatorStore { listSites(projectId: string): Promise<DocsFnSiteRecord[]>; getSite(projectId: string, id: string): Promise<DocsFnSiteRecord | null>; putSite(value: DocsFnSiteRecord): Promise<void>; deleteSite(projectId: string, id: string): Promise<boolean>; listBuilds(projectId: string, siteId?: string): Promise<DocsFnBuildRecord[]>; getBuild(projectId: string, id: string): Promise<DocsFnBuildRecord | null>; putBuild(value: DocsFnBuildRecord): Promise<void> }
export class MemoryDocsFnOperatorStore implements DocsFnOperatorStore { private sites = new Map<string, DocsFnSiteRecord>(); private builds = new Map<string, DocsFnBuildRecord>(); private key(p: string, i: string) { return `${p}\0${i}`; } async listSites(p: string) { return [...this.sites.values()].filter(v => v.projectId === p).map(structuredClone); } async getSite(p: string, i: string) { const v = this.sites.get(this.key(p, i)); return v ? structuredClone(v) : null; } async putSite(v: DocsFnSiteRecord) { this.sites.set(this.key(v.projectId, v.id), structuredClone(v)); } async deleteSite(p: string, i: string) { return this.sites.delete(this.key(p, i)); } async listBuilds(p: string, s?: string) { return [...this.builds.values()].filter(v => v.projectId === p && (!s || v.siteId === s)).map(structuredClone); } async getBuild(p: string, i: string) { const v = this.builds.get(this.key(p, i)); return v ? structuredClone(v) : null; } async putBuild(v: DocsFnBuildRecord) { this.builds.set(this.key(v.projectId, v.id), structuredClone(v)); } }
export interface DocsFnOperatorServiceOptions { store: DocsFnOperatorStore; provider(site: DocsFnSiteRecord, context: AdminOperationContext): DocsContentProvider | Promise<DocsContentProvider>; now?: () => Date; createId?: () => string }
function project(c: AdminOperationContext) { if (!c.scope.projectId) throw new AdminError("invalid_argument", "DocsFn administration requires a project scope."); return c.scope.projectId; }
function summary(v: DocsFnSiteRecord) { return { id: v.id, name: v.name, title: v.config.site.title, basePath: v.config.site.basePath ?? "/docs", createdAt: v.createdAt, updatedAt: v.updatedAt }; }
function page<T>(items: T[]) { return { items, nextCursor: null as null }; }
export function createDocsFnOperatorService(options: DocsFnOperatorServiceOptions) { const now = () => (options.now?.() ?? new Date()).toISOString(); const createId = options.createId ?? (() => crypto.randomUUID()); return {
  async listSites(_i: {}, c: AdminOperationContext) { return page((await options.store.listSites(project(c))).map(summary)); },
  async getSite(i: { id: string }, c: AdminOperationContext) { const v = await options.store.getSite(project(c), i.id); if (!v) throw new AdminError("not_found", "DocsFn site was not found."); return { item: summary(v) }; },
  async upsertSite(i: { id: string; name: string; config: ManifestConfig }, c: AdminOperationContext) { const p = project(c); if (!i.name.trim() || !i.config?.site?.title) throw new AdminError("invalid_argument", "Site name and config.site.title are required."); const old = await options.store.getSite(p, i.id); const at = now(); const v = { id: i.id, projectId: p, name: i.name, config: structuredClone(i.config), createdAt: old?.createdAt ?? at, updatedAt: at }; await options.store.putSite(v); return { accepted: true as const, item: summary(v) }; },
  async deleteSite(i: { id: string }, c: AdminOperationContext) { if (!await options.store.deleteSite(project(c), i.id)) throw new AdminError("not_found", "DocsFn site was not found."); return { accepted: true as const }; },
  async listBuilds(i: { siteId?: string }, c: AdminOperationContext) { return page(await options.store.listBuilds(project(c), i.siteId)); },
  async getBuild(i: { id: string }, c: AdminOperationContext) { const v = await options.store.getBuild(project(c), i.id); if (!v) throw new AdminError("not_found", "DocsFn build was not found."); return { item: v }; },
  async runBuild(i: { siteId: string; preview?: boolean }, c: AdminOperationContext) { const p = project(c); const site = await options.store.getSite(p, i.siteId); if (!site) throw new AdminError("not_found", "DocsFn site was not found."); const id = createId(); try { const manifest = await buildManifest(await options.provider(site, c), site.config, { preview: i.preview }); const v: DocsFnBuildRecord = { id, projectId: p, siteId: site.id, status: "succeeded", pageCount: Object.keys(manifest.pages).length, postCount: Object.keys(manifest.posts).length, apiCount: Object.keys(manifest.apis).length, createdAt: now() }; await options.store.putBuild(v); return { accepted: true as const, item: v }; } catch (error) { const v: DocsFnBuildRecord = { id, projectId: p, siteId: site.id, status: "failed", pageCount: 0, postCount: 0, apiCount: 0, error: error instanceof Error ? error.message : "Build failed", createdAt: now() }; await options.store.putBuild(v); throw new AdminError("precondition_failed", "DocsFn build failed.", { details: { buildId: id } }); } },
