    )
  );
  const payload = result.ok ? result.data : {};
  return {
    module: payload.module ? { ...registered, ...payload.module } : registered,
    summary: payload.summary ?? [],
    notices: payload.notices ?? [],
    loadError: result.ok ? undefined : result.error,
  };
};
