import { describe, expect, it, vi } from "vitest";
import {
  dataFnAdminCapability,
  createDataFnAdminClient,
  createDataFnAdminAdapter,
  createDataFnDomainAdminService,
} from "../index.js";
import { createAdminClient, validateAdminCapabilityManifest } from "@superfunctions/admin";
import { createDatafnServer } from "@datafn/server";
import { memoryAdapter } from "@superfunctions/db/adapters";

const context = {
  scope: {
    organizationId: "org_1",
    workspaceId: "workspace_1",
    projectId: "project_1",
    environmentId: "environment_1",
    namespace: "tenant_1",
    region: "in-south",
  },
  actor: { id: "operator_1", type: "user" as const, permissions: ["*"] },
  requestId: "request_1",
  correlationId: "correlation_1",
  source: "console" as const,
  idempotencyKey: "idempotency_1",
};

describe("@datafn/admin", () => {
  it("declares the inventoried operator surface and mutation policy", () => {
    expect(validateAdminCapabilityManifest(dataFnAdminCapability)).toEqual([]);
    expect(dataFnAdminCapability.schemaVersion).toBe("1.0");
    expect(dataFnAdminCapability.availability).toBe("required-product");
    expect(dataFnAdminCapability.scopeLevels).toEqual([
      "organization",
      "workspace",
      "project",
      "environment",
    ]);
    expect(
      dataFnAdminCapability.operations.some(
        (operation) => operation.id === "datafn.schemas.list",
      ),
    ).toBe(true);
    expect(dataFnAdminCapability.operations).toHaveLength(15);
    const mutation = dataFnAdminCapability.operations.find(
      (operation) => operation.safety.classification !== "read",
    );
    expect(mutation).toMatchObject({
      safety: {
        audit: "required",
        idempotent: true,
      },
    });
    expect(dataFnAdminCapability.operations.find(
      (operation) => operation.id === "datafn.queries.query",
    )).toMatchObject({
      safety: { classification: "read", idempotent: true },
      mcp: { readOnlyHint: true },
      target: { resource: "queries", collection: true },
    });
    expect(dataFnAdminCapability.resources?.map((resource) => resource.id)).toContain("queries");
    expect(dataFnAdminCapability.operations.some(
      (operation) => operation.id === "datafn.queries.list",
    )).toBe(false);
    const schemaList = dataFnAdminCapability.operations.find(
      (operation) => operation.id === "datafn.schemas.list",
    );
    expect(schemaList?.inputSchema?.properties).toEqual({
      cursor: expect.any(Object),
      limit: expect.any(Object),
    });
    const recordList = dataFnAdminCapability.operations.find(
      (operation) => operation.id === "datafn.records.list",
    );
    expect(recordList?.inputSchema).toMatchObject({
      required: ["filter"],
      properties: { filter: { required: ["resource"] } },
    });
    const mutationOperation = dataFnAdminCapability.operations.find(
      (operation) => operation.id === "datafn.records.mutate",
    );
    expect(mutationOperation?.inputSchema).toMatchObject({
      required: ["id", "payload"],
      additionalProperties: false,
    });
  });

  it("provides named typed client methods for every real resource family", async () => {
    const fetcher = vi.fn(async () => new Response(JSON.stringify({
      ok: true,
      data: { items: [], nextCursor: null },
    }), { status: 200, headers: { "content-type": "application/json" } }));
    const client = createDataFnAdminClient(createAdminClient({
      baseUrl: "https://console.example.test/api/admin/v1",
      fetch: fetcher as typeof fetch,
    }));

    await client.schemas.list({ limit: 25 });
    expect(fetcher).toHaveBeenCalledTimes(1);
    const [url, request] = fetcher.mock.calls[0]!;
    expect(String(url)).toContain("/operations/datafn.schemas.list");
    expect(JSON.parse(String(request?.body))).toEqual({ limit: 25 });
    expect(client.records).toEqual(expect.objectContaining({
      list: expect.any(Function),
      get: expect.any(Function),
      mutate: expect.any(Function),
      transact: expect.any(Function),
    }));
    expect(client.queries.query).toEqual(expect.any(Function));
  });

  it("binds schema, mutation, and record reads through the real DataFn executor", async () => {
    const server = await createDatafnServer<{ namespace: string; actorId: string }>({
      schema: {
        resources: [{
          name: "tasks",
          version: 1,
          fields: [{ name: "title", type: "string", required: true }],
          permissions: {
            read: { fields: ["title"] },
            write: { fields: ["title"] },
          },
        }],
      },
      db: memoryAdapter(),
      namespaceProvider: {
        getNamespace: (value) => value.namespace,
        getActorId: (value) => value.actorId,
      },
    });
    const service = createDataFnDomainAdminService({
        executor: server.executor,
        context: (admin) => ({
          namespace: admin.scope.namespace ?? admin.scope.projectId ?? "datafn",
          actorId: admin.actor.id,
        }),
      });
    const mutate = vi.spyOn(service, "mutate");
    const adapter = createDataFnAdminAdapter(service);
    expect(Object.keys(adapter.handlers).sort()).toEqual(
      dataFnAdminCapability.operations.map((operation) => operation.id).sort(),
    );
    await adapter.execute("datafn.records.mutate", {
      id: "tasks:task-1",
      payload: {
        resource: "tasks",
        version: "1",
        operation: "insert",
        clientId: "superconsole",
        mutationId: "create-task-1",
        id: "task-1",
        record: { title: "Ship Super Console" },
      },
    }, context);
    expect(mutate).toHaveBeenCalledWith(expect.objectContaining({
      id: "tasks:task-1",
    }), context);
    expect(service).not.toHaveProperty("execute");
    await expect(adapter.execute("datafn.records.mutate", {
      id: "tasks:another-task",
      payload: {
        resource: "tasks",
        version: "1",
        operation: "insert",
        clientId: "superconsole",
        mutationId: "mismatched-target",
        id: "task-2",
        record: { title: "Must not run" },
      },
    }, context)).rejects.toMatchObject({ code: "invalid_argument" });

    const records = await adapter.execute("datafn.records.list", {
      limit: 10,
      filter: { resource: "tasks", select: ["id", "title"] },
    }, context);
    expect(records.data).toMatchObject({
      items: [{ id: "task-1", title: "Ship Super Console" }],
    });
    const resources = await adapter.execute("datafn.resources.list", {}, context);
    expect(resources.data).toMatchObject({
      items: expect.arrayContaining([expect.objectContaining({ id: "tasks", version: 1 })]),
    });
    await server.close();
  });
});
import { createMemoryStore } from "@recfn/server";
import { describe, expect, it } from "vitest";
import {
  createRecFnDomainAdminAdapter,
  createRecFnDomainAdminService,
  recFnAdminCapability,
} from "../index.js";

const context = {
  scope: {
    organizationId: "org_1",
    workspaceId: "workspace_1",
    projectId: "project_1",
    environmentId: "environment_1",
    namespace: "tenant_1",
    region: "in-south",
  },
  actor: { id: "operator_1", type: "user" as const, permissions: ["*"] },
  requestId: "request_1",
  correlationId: "correlation_1",
  source: "console" as const,
  idempotencyKey: "idempotency_1",
  confirmationToken: "confirmation_1",
};

const config = {
  displayName: "Recorder",
  joinTimeout: 60_000,
  autoLeaveOnEmpty: true,
  autoLeaveEmptyTimeout: 60_000,
  consentMessage: "This meeting is recorded.",
  enableRealTimeTranscript: false,
  asrProvider: "whisper",
  recordingFormat: "audio_only" as const,
  language: "en-US",
};

describe("@recfn/admin", () => {
  it("publishes only domain-backed operations and exact safety policy", () => {
    const ids = recFnAdminCapability.operations.map((operation) => operation.id);

    expect(ids).toContain("recfn.bots.list");
    expect(ids).toContain("recfn.webhooks.create");
    expect(ids).not.toContain("recfn.recording-bots.schedule-bot");
    expect(ids.some((id) => id.includes("transcribe"))).toBe(false);
    expect(ids.some((id) => id.includes("calendar"))).toBe(false);
    expect(recFnAdminCapability.operations.find((operation) => operation.id === "recfn.bots.delete")?.safety).toMatchObject({
      classification: "destructive",
      requiresConfirmation: true,
      confirmation: { risk: "critical", method: "recent-auth" },
      audit: "required",
    });
  });

  it("executes through the real RecFn server and isolates namespaces", async () => {
    const store = createMemoryStore();
    const visible = await store.createBot({ meetingUrl: "https://meet.google.com/aaa-bbbb-ccc", platform: "meet", config, namespace: "tenant_1" });
    await store.createBot({ meetingUrl: "https://meet.google.com/ddd-eeee-fff", platform: "meet", config, namespace: "tenant_2" });
    const adapter = createRecFnDomainAdminAdapter({ projectId: "project_1", server: { store, environment: "test" } });

    const result = await adapter.execute("recfn.bots.list", { limit: 25 }, context);

    expect(result.ok).toBe(true);
    expect(result.data).toEqual({
      items: [expect.objectContaining({ id: visible.id, namespace: "[REDACTED]", meetingUrl: "[REDACTED]" })],
      nextCursor: null,
    });
  });

  it("uses RecFn webhook validation and never returns the signing secret", async () => {
    const store = createMemoryStore();
    const service = createRecFnDomainAdminService({ projectId: "project_1", server: { store, environment: "test" } });
    const adapter = createRecFnDomainAdminAdapter({ projectId: "project_1", server: { store, environment: "test" } });

    const result = await adapter.execute("recfn.webhooks.create", {
      url: "https://events.example.com/recfn",
      events: ["bot.joined"],
      secret: "do-not-return",
    }, context);
    const created = result.data;
    const listed = await service.listWebhooks({}, context);

    expect(created).toEqual({ item: expect.not.objectContaining({ secret: expect.anything() }) });
    expect(listed.items).toEqual([created.item]);
    await expect(service.createWebhook({ url: "file:///tmp/exfiltrate", events: ["bot.joined"] }, context)).rejects.toMatchObject({ code: "invalid_argument" });
  });

  it("rejects a mismatched project before touching the RecFn store", async () => {
    const store = createMemoryStore();
    const service = createRecFnDomainAdminService({ projectId: "project_1", server: { store, environment: "test" } });

    await expect(service.listBots({}, { ...context, scope: { ...context.scope, projectId: "project_2" } })).rejects.toMatchObject({ code: "forbidden" });
    expect((await store.listBots("tenant_1", {})).items).toEqual([]);
  });

  it("deletes only terminal bots through RecFn lifecycle rules", async () => {
    const store = createMemoryStore();
    const bot = await store.createBot({ meetingUrl: "https://meet.google.com/aaa-bbbb-ccc", platform: "meet", config, namespace: "tenant_1" });
    await store.updateBot(bot.id, "tenant_1", { status: "done", updatedAt: new Date().toISOString() });
    const service = createRecFnDomainAdminService({ projectId: "project_1", server: { store, environment: "test" } });

