  description: "Function-owned administration for persisted CatchFn bug reports.", category: "observability",
  availability: "nested", owner: { moduleId: "watchfn", mountPath: "/modules/watchfn/errors" },
  scopeLevels: ["organization", "workspace", "project", "environment"], dependencies: ["watchfn"],
  resources: [{ id: "bug-reports", label: "Bug reports", description: "Captured product feedback and bug evidence.", icon: "catchfn:bugs", risk: "sensitive", idField: "id", displayFields: ["id", "title", "severity", "timestamp"], searchableFields: ["id", "title"], filterableFields: ["severity", "environment", "timestamp"], sortableFields: ["timestamp", "severity"], sensitiveFields: ["user", "metadata", "attachments"] }],
  navigation: [{ id: "catchfn", label: "Bug reports", path: "/modules/watchfn/errors", parentId: "watchfn", group: "WatchFn", order: 30 }],
  operations,
});

export interface CatchFnAdminService {
  listBugReports(input: ListBugReportsInput, context: AdminOperationContext): Promise<BugReportListResult>;
  getBugReport(input: GetBugReportInput, context: AdminOperationContext): Promise<BugReportResult>;
  createBugReport(input: CreateBugReportInput, context: AdminOperationContext): Promise<BugReportResult>;
}

function assertScope(expected: CatchFnAdminScope, actual: AdminOperationContext["scope"]): void {
  for (const key of ["organizationId", "workspaceId", "projectId", "environmentId", "namespace", "region"] as const) {
    if (expected[key] !== undefined && actual[key] !== expected[key]) {
      throw new AdminError("forbidden", `CatchFn is not bound to the active ${key}.`);
    }
  }
}

export function createCatchFnAdminService(service: CatchFnService, scope: CatchFnAdminScope): CatchFnAdminService {
  return {
    async listBugReports(input, context) {
      assertScope(scope, context.scope);
      const limit = input.limit ?? 50;
      const offset = input.cursor
        ? decodeAdminCursor<{ offset: number }>(input.cursor, context.scope).offset
        : 0;
      if (!Number.isInteger(offset) || offset < 0) throw new AdminError("invalid_argument", "The bug-report cursor is invalid.");
      const items = await service.listBugs(limit + 1, offset);
      return {
        items: items.slice(0, limit),
        nextCursor: items.length > limit
          ? encodeAdminCursor(context.scope, { offset: offset + limit })
          : null,
      };
    },
    async getBugReport(input, context) {
      assertScope(scope, context.scope);
      const item = await service.getBug(input.id);
      if (!item) throw new AdminError("not_found", "Bug report not found.", { details: { id: input.id } });
      return { item };
    },
    async createBugReport(input, context) {
      assertScope(scope, context.scope);
      const item = await service.createBug(input as BugReportEvent);
      return { item };
    },
  };
  availability: "nested", owner: { moduleId: "watchfn", mountPath: "/modules/watchfn/logs" }, scopeLevels: ["organization", "workspace", "project", "environment"],
  dependencies: ["watchfn"],
  resources: [
    { id: "events", label: "Log events", description: "Structured events emitted through LogFn.", icon: "logfn:events", risk: "sensitive", idField: "requestId", displayFields: ["level", "message"], sensitiveFields: ["context"] },
    { id: "sinks", label: "Log sinks", description: "Configured LogFn output sinks.", icon: "logfn:sinks", risk: "standard", idField: "name", displayFields: ["name"] },
  ],
  navigation: [{ id: "logfn", label: "Logs", path: "/modules/watchfn/logs", parentId: "watchfn", group: "WatchFn", order: 20 }],
  operations,
});

export interface LogFnAdminService {
  emit(input: EmitLogInput, context: AdminOperationContext): Promise<EmitLogResult> | EmitLogResult;
  flush(context: AdminOperationContext): Promise<FlushLogsResult>;
}

function assertScope(expected: LogFnAdminScope, actual: AdminOperationContext["scope"]): void {
  for (const key of ["organizationId", "workspaceId", "projectId", "environmentId", "namespace", "region"] as const) {
    if (expected[key] !== undefined && actual[key] !== expected[key]) throw new AdminError("forbidden", `LogFn is not bound to the active ${key}.`);
  }
}

export function createLogFnAdminService(logger: Logger, scope: LogFnAdminScope): LogFnAdminService {
  return {
    emit(input, context) {
      assertScope(scope, context.scope);
      const eventContext = {
        ...input.context,
        adminActorId: context.actor.id,
        adminRequestId: context.requestId,
        adminCorrelationId: context.correlationId,
        organizationId: context.scope.organizationId,
        workspaceId: context.scope.workspaceId,
        projectId: context.scope.projectId,
        environmentId: context.scope.environmentId,
      };
      logger[input.level](input.message, eventContext, input.tags);
      return { emitted: true, level: input.level };
    },
    async flush(context) {
      assertScope(scope, context.scope);
      await logger.flush();
      return { flushed: true };
    },
  };
}

export function createLogFnAdminAdapter(service: LogFnAdminService) {
  return createKernelAdminCapabilityAdapter(logFnAdminCapability, {
    "logfn.events.emit": ({ input, context }) => service.emit(input as EmitLogInput, context),
    "logfn.sinks.flush": ({ context }) => service.flush(context),
  });
}

export function createLogFnAdminClient(adminClient: AdminClient) {
  const capability = createCapabilityAdminClient(logFnAdminCapability, adminClient);
  return Object.assign(capability, {
    const { limit, cursor, ...requestOptions } = options;
    return this.request("GET", "search", { q: query, limit, cursor }, requestOptions);
  }

  async audit(options: AdminAuditListOptions = {}): Promise<AdminAuditView> {
    const { limit, cursor, actor, module, outcome, query, ...requestOptions } = options;
    return this.request("GET", "audit", { limit, cursor, actor, module, outcome, q: query }, requestOptions);
  }

  async settings(options?: AdminClientRequestOptions): Promise<AdminSettingsView> {
    return this.request("GET", "settings", undefined, options);
  }

  async mcp(options?: AdminClientRequestOptions): Promise<AdminMcpView> {
    return this.request("GET", "mcp", undefined, options);
  }

  async issueConfirmation(operationId: string, input: unknown, options?: AdminClientRequestOptions): Promise<AdminConfirmationReceipt> {
    return this.request("POST", "confirmations", { operationId, input }, options);
  }

  async invoke<T = unknown>(
    moduleId: string,
    route: { method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE"; path: string },
    input?: unknown,
    options?: AdminClientRequestOptions,
  ): Promise<AdminOperationResult<T>> {
    const path = `modules/${encodeURIComponent(moduleId)}${route.path.startsWith("/") ? route.path : `/${route.path}`}`;
    return this.request<AdminOperationResult<T>>(route.method, path, input, options, false);
  }

  async invokeOperation<T = unknown>(
    operationId: string,
    input?: unknown,
    options?: AdminClientRequestOptions,
  ): Promise<AdminOperationResult<T>> {
    return this.request<AdminOperationResult<T>>(
      "POST",
      `operations/${encodeURIComponent(operationId)}`,
      input ?? {},
      options,
      false,
    );
  }

  async invokeOperationRaw<T = unknown>(
    operationId: string,
    input?: unknown,
    options?: AdminClientRequestOptions,
  ): Promise<AdminRawResponse<AdminResult<T>>> {
    return this.performRequest<AdminResult<T>>(
      "POST",
      `operations/${encodeURIComponent(operationId)}`,
      input ?? {},
      options,
    );
  }

  async invokeRaw<T = unknown>(
    moduleId: string,
    route: { method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE"; path: string },
    input?: unknown,
    options?: AdminClientRequestOptions,
  ): Promise<AdminRawResponse<AdminResult<T>>> {
    const path = `modules/${encodeURIComponent(moduleId)}${route.path.startsWith("/") ? route.path : `/${route.path}`}`;
    return this.performRequest<AdminResult<T>>(route.method, path, input, options);
  }

  private async request<T>(
    method: string,
    path: string,
    input?: unknown,
    options: AdminClientRequestOptions = {},
    unwrap = true,
  ): Promise<T> {
    const { response, payload } = await this.performRequest<T | AdminResult>(method, path, input, options);
    if (!response.ok) {
      const result = payload && typeof payload === "object" && "ok" in payload ? payload as AdminResult : undefined;
      throw new AdminClientError(result && result.ok === false ? result.error.message : `Administration request failed with HTTP ${response.status}.`, response.status, result, response);
    }
    if (unwrap && payload && typeof payload === "object" && "ok" in payload && (payload as AdminResult).ok !== false) {
      return (payload as { data: T }).data;
    }
    return payload as T;
  }

  private async performRequest<T>(
    method: string,
    path: string,
    input?: unknown,
    options: AdminClientRequestOptions = {},
