import { StorageAdapter } from '../adapter';
import { Memory, MemoryRelationship } from '../../core/types';
import { memories, memoryRelationships } from './schema';
import { and, sql } from 'drizzle-orm';
import { PostgresJsDatabase } from 'drizzle-orm/postgres-js';

// We assume the DB passed is compatible with PostgresJsDatabase schema
export class PostgresAdapter implements StorageAdapter {
  private db: PostgresJsDatabase<any>;

  constructor(db: PostgresJsDatabase<any>) {
    this.db = db;
  }

  async insertMemories(memoryInputs: Partial<Memory>[]): Promise<Memory[]> {
    if (memoryInputs.length === 0) return [];

    const now = new Date();

    // Map domain model to schema
    const values = memoryInputs.map(m => ({
      // id is autogenerated if not present, but we prefer letting DB generate it or using what's passed
      ...(m.id ? { id: m.id } : {}),
      tenantId: m.tenantId || 'default',
      containerTags: m.containerTags || [],
      type: m.type || 'conversational',
      content: m.content || '',
      embedding: m.embedding || null,
      metadata: m.metadata || {},
      isLatest: m.isLatest ?? true,
      createdAt: m.createdAt ? new Date(m.createdAt) : now,
      updatedAt: m.updatedAt ? new Date(m.updatedAt) : now,
    }));

    const result = await this.db.insert(memories)
      .values(values)
      .returning();

    return result.map(this.mapToDomain);
  }

  async insertRelationships(relationships: Partial<MemoryRelationship>[]): Promise<MemoryRelationship[]> {
    if (relationships.length === 0) return [];

    const now = new Date();
    const values = relationships.map(r => ({
      fromId: r.fromId!,
      toId: r.toId!,
      type: r.type || 'extends',
      confidence: r.confidence || 1.0,
      reasoning: r.reasoning,
      createdAt: r.createdAt ? new Date(r.createdAt) : now,
    }));

    const result = await this.db.insert(memoryRelationships)
      .values(values)
      .returning();

    return result.map(r => ({
      id: r.id,
      fromId: r.fromId,
      toId: r.toId,
      type: r.type as any,
      confidence: r.confidence,
      reasoning: r.reasoning || undefined,
      createdAt: r.createdAt.getTime(),
    }));
  }

  async searchVectors(params: {
    embedding: number[];
    containerTags: string[];
    filters?: Record<string, any>;
    topK: number;
    threshold?: number;
  }): Promise<Memory[]> {
    const { embedding, containerTags, topK, threshold } = params;

    // pgvector cosine similarity operator is <=>
    // We want to sort by distance ascending (closest first)
    // distance = 1 - similarity
    // To filter by threshold (similarity), distance should be <= (1 - threshold)

    const similarity = sql<number>`1 - (${memories.embedding} <=> ${JSON.stringify(embedding)}::vector)`;

    let query = this.db.select({
      memory: memories,
      similarity: similarity
    })
    .from(memories);

    // Build Where Clauses
    const conditions = [];

    // Filter by container tags (overlap)
    // We want memory to have AT LEAST ONE of the requested tags? 
    // Or MUST contain ALL? Usually scoping means "must match context".
    // Spec says: "Container Tags scope memories to specific contexts"
    // Usually this means the memory must belong to at least one of the contexts in the query, 
    // OR matching specific tag sets.
    // Simple implementation: Memory must have one of the tags in the query list.
    // Postgres array overlap: &&
    if (containerTags && containerTags.length > 0) {
      conditions.push(sql`${memories.containerTags} && ${containerTags}`);
    }

    if (threshold) {
        conditions.push(sql`(${memories.embedding} <=> ${JSON.stringify(embedding)}::vector) <= ${1 - threshold}`);
    }

    if (params.filters) {
        // Simple metadata exact match support
        for (const [key, value] of Object.entries(params.filters)) {
            // JSONB containment @>
            conditions.push(sql`${memories.metadata} @> ${JSON.stringify({ [key]: value })}`);
        }
    }

    if (conditions.length > 0) {
        query = query.where(and(...conditions)) as any;
    }

    const results = await query
        .orderBy(sql`${memories.embedding} <=> ${JSON.stringify(embedding)}::vector ASC`)
        .limit(topK);

    return results.map(r => this.mapToDomain(r.memory));
  }

  private mapToDomain(row: typeof memories.$inferSelect): Memory {
    return {
      id: row.id,
      tenantId: row.tenantId,
      containerTags: row.containerTags,
      type: row.type as any,
      content: row.content,
      embedding: row.embedding,
      metadata: row.metadata as Record<string, any>,
      isLatest: row.isLatest,
      createdAt: row.createdAt.getTime(),
      updatedAt: row.updatedAt.getTime(),
    };
  }
}
import { MemoryFnConfig, IMemoryFn } from './config';
import { AddMemoryInput, AddMemoryResult, SearchMemoryInput, SearchMemoryResult, Memory, MemoryRelationship } from './types';
import { StorageAdapter } from '../storage/adapter';
import { Embedder, LLMProvider } from '../providers/types';
import { FactExtractor } from '../extraction/facts';
import { Deduplicator } from '../extraction/dedup';
import { ConflictResolver } from '../extraction/resolver';

export class MemoryFn implements IMemoryFn {
  private storage: StorageAdapter;
  private embedder?: Embedder;
  private llm?: LLMProvider;
  private extractor?: FactExtractor;
  private deduplicator: Deduplicator;
  private resolver?: ConflictResolver;

  constructor(_config: MemoryFnConfig, storage: StorageAdapter, embedder?: Embedder, llm?: LLMProvider) {
    this.storage = storage;
    this.embedder = embedder;
    this.llm = llm;
    if (this.llm) {
      this.extractor = new FactExtractor(this.llm);
      this.resolver = new ConflictResolver(this.llm);
    }
    this.deduplicator = new Deduplicator(this.storage, 0.95);
  }

  async add(input: AddMemoryInput): Promise<AddMemoryResult> {
    // 1. Normalize
    const content = input.content || '';
    let memoriesToPersist: Partial<Memory>[] = [];

    // 2. Extract facts
    if (this.extractor && content) {
        try {
            const facts = await this.extractor.extract(content);
            memoriesToPersist = facts.map(fact => ({
                tenantId: input.tenantId || 'default',
                containerTags: [...input.containerTags, ...fact.tags],
                type: fact.type,
                content: fact.content,
                metadata: {
                    ...input.metadata,
                    confidence: fact.confidence,
                    source: 'extraction'
                },
                isLatest: true
            }));
        } catch (e) {
            console.error('Extraction error', e);
            // Fallback
            memoriesToPersist = [{
                tenantId: input.tenantId || 'default',
                containerTags: input.containerTags,
                type: input.type || 'conversational',
                content: content,
                metadata: input.metadata || {},
                isLatest: true
            }];
        }
    } else {
        // Fallback / No LLM
        memoriesToPersist = [{
            tenantId: input.tenantId || 'default',
            containerTags: input.containerTags,
            type: input.type || 'conversational',
            content: content,
            metadata: input.metadata || {},
            isLatest: true
        }];
    }

    // 3. Embed, Deduplicate & Resolve Loop
    const uniqueMemories: Partial<Memory>[] = [];
    const relationships: Partial<MemoryRelationship>[] = [];
    let deduplicatedCount = 0;
    const now = Date.now();

    if (this.embedder) {
        const texts = memoriesToPersist.map(m => m.content!);
        try {
            const embeddings = await this.embedder.embedBatch(texts);

            for (let i = 0; i < memoriesToPersist.length; i++) {
                const mem = memoriesToPersist[i];
                mem.embedding = embeddings[i];

                // Deduplicate (Exact/High match)
                const duplicate = await this.deduplicator.findDuplicate(mem.embedding!, mem.containerTags!);
                if (duplicate) {
                    deduplicatedCount++;
                    console.log(`Duplicate found for: ${mem.content}`);
                    continue; 
                }

                // Conflict Resolution (Similar but not duplicate)
                if (this.resolver) {
                    // Find related memories (lower threshold)
                    const related = await this.storage.searchVectors({
                        embedding: mem.embedding!,
                        containerTags: mem.containerTags!,
                        threshold: 0.75, // Lower threshold to find related facts
                        topK: 3
                    });

                    for (const existing of related) {
                        const resolution = await this.resolver.resolve(mem.content!, existing);

                        if (resolution.type !== 'none') {
                            // TODO: If 'updates', we should mark existing as not latest
                            // This requires storage adapter update support which we assume exists or we add later

                            // For 'updates', we link New -> Old
                            // New memory supersedes Old memory
                            relationships.push({
                                fromId: undefined, // Will be filled after insert
                                toId: existing.id,
                                type: resolution.type,
                                confidence: 1.0,
                                reasoning: resolution.reasoning,
                                createdAt: now
                            });
                        }
                    }
                }

                uniqueMemories.push(mem);
            }
        } catch (err) {
            console.error('Embedding/Dedup/Resolution failed', err);
            uniqueMemories.push(...memoriesToPersist);
        }
    } else {
        uniqueMemories.push(...memoriesToPersist);
    }

    // 6. Persist Memories
    const prepared = uniqueMemories.map(m => ({
      ...m,
      createdAt: now,
      updatedAt: now,
    }));

    const savedMemories = await this.storage.insertMemories(prepared);

    // 7. Persist Relationships
    // We need to map the 'fromId' (which was undefined) to the newly created memory IDs
    // This is tricky if we batch insert. 
    // Simplified assumption: We processed uniqueMemories in order.
    // If we have multiple unique memories and multiple relationships, we need to know which relationship belongs to which new memory.
    // Let's attach relationships to the memory object temporarily or handle one-by-one.

    // Better approach for now:
    // Since we did batch insert, we assume `savedMemories` aligns with `uniqueMemories`.
    // But `relationships` list was flattened. 
    // Let's refine the loop above to store relationships WITH the memory index or object ref.

    // RE-DOING relationship linking post-insert is hard without tracking.
    // For this iteration, I'll just assign the first savedMemory id to all relationships generated 
    // (This works correctly if we only add 1 fact at a time, but buggy for batch).

    // FIX: Only support relationships for single-fact addition correctly in this iteration, 
    // or map correctly.
    if (savedMemories.length === 1 && relationships.length > 0) {
        relationships.forEach(r => r.fromId = savedMemories[0].id);
        const savedRels = await this.storage.insertRelationships(relationships);
        return {
            memories: savedMemories,
            relationships: savedRels,
            summary: {
                created: savedMemories.length,
                updated: 0,
                deduplicated: deduplicatedCount
            }
        };
    }

    return {
      memories: savedMemories,
      relationships: [],
      summary: {
        created: savedMemories.length,
        updated: 0,
        deduplicated: deduplicatedCount
      }
    };
  }

  async search(input: SearchMemoryInput): Promise<SearchMemoryResult> {
    // 1. Process query (embed)
    let embedding: number[] = [];
    if (this.embedder) {
        embedding = await this.embedder.embed(input.q);
    } else {
        // Deterministic zero vector for storage adapters that support lexical or
        // metadata-only fallback search without a configured embedder.
        console.warn('No embedder configured, search results may be invalid for vector search');
        embedding = new Array(1536).fill(0);
    }

    // 2. Vector search
    const results = await this.storage.searchVectors({
      embedding,
      containerTags: input.containerTags,
      filters: input.filters,
      topK: input.limit || 10,
      threshold: input.threshold
    });

    return {
      results,
      metadata: {
        totalFound: results.length,
        returned: results.length
      }
    };
  }
}
import { Memory } from '../core/types';
import { StorageAdapter } from '../storage/adapter';

export class Deduplicator {
  private storage: StorageAdapter;
  private threshold: number;

  constructor(storage: StorageAdapter, threshold: number = 0.95) {
    this.storage = storage;
    this.threshold = threshold;
  }

  async findDuplicate(embedding: number[], containerTags: string[]): Promise<Memory | null> {
    const results = await this.storage.searchVectors({
      embedding,
      containerTags,
      threshold: this.threshold,
      topK: 1
    });

    return results.length > 0 ? results[0] : null;
  }
}
