import type {
  IMemoryFn,
  Memory,
  MemoryType,
  SearchMemoryInput,
} from '@memoryfn/core';
import type { AdminOperationContext } from '@superfunctions/admin';

/** Deliberately omits embeddings, tenant keys, scope tags, and arbitrary metadata. */
export type MemoryFnAdminMemory = Pick<
  Memory,
  'id' | 'type' | 'content' | 'isLatest' | 'createdAt' | 'updatedAt'
>;

export type MemoryFnSearchMemoriesInput = Omit<SearchMemoryInput, 'containerTags'>;

export interface MemoryFnSearchMemoriesOutput {
  items: MemoryFnAdminMemory[];
  totalFound: number;
  returned: number;
}

export interface MemoryFnIngestMemoryInput {
  content: string;
  type?: MemoryType;
  metadata?: Record<string, unknown>;
}

export interface MemoryFnIngestMemoryOutput {
  items: MemoryFnAdminMemory[];
  summary: {
    created: number;
    updated: number;
    deduplicated: number;
  };
  relationshipsCreated: number;
  cost?: {
    llm: number;
    embeddings: number;
    total: number;
  };
}

export interface MemoryFnAdminService {
  searchMemories(
    input: MemoryFnSearchMemoriesInput,
    context: AdminOperationContext,
  ): Promise<MemoryFnSearchMemoriesOutput>;
  ingestMemory(
    input: MemoryFnIngestMemoryInput,
    context: AdminOperationContext,
  ): Promise<MemoryFnIngestMemoryOutput>;
}

export interface MemoryFnDomainAdminServiceOptions {
  /** Project that owns the configured MemoryFn runtime or runtime resolver. */
  projectId: string;
  /** Public MemoryFn API. A resolver may select a region-local configured runtime. */
  memory:
    | IMemoryFn
    | ((context: AdminOperationContext) => IMemoryFn | Promise<IMemoryFn>);
}
import { describe, it, expect } from 'vitest';
import { memoryfn, AddMemoryInput } from '../src';

describe('MemoryFn Pipeline', () => {
  it('should initialize successfully', () => {
    const memory = memoryfn({
      storage: {
        kind: 'sqlite',
        path: ':memory:'
      }
    });
    expect(memory).toBeDefined();
  });

  it('should add a memory', async () => {
    const memory = memoryfn({
      storage: {
        kind: 'sqlite',
        path: ':memory:'
      }
    });

    const input: AddMemoryInput = {
      content: 'The sky is blue',
      containerTags: ['user:test'],
      type: 'conversational'
    };

    const result = await memory.add(input);

    expect(result).toBeDefined();
    expect(result.memories).toHaveLength(1);
    expect(result.memories[0].content).toBe('The sky is blue');
    expect(result.summary.created).toBe(1);
  });

  it('should persist and search memories in the process-local adapter', async () => {
    const memory = memoryfn({
      storage: {
        kind: 'sqlite',
        path: ':memory:'
      }
    });

    await memory.add({
      content: 'The sky is blue',
      containerTags: ['user:test'],
      type: 'conversational'
    });

    const result = await memory.search({
      q: 'sky',
      containerTags: ['user:test']
    });

    expect(result).toBeDefined();
    expect(result.results).toHaveLength(1);
    expect(result.results[0]?.content).toBe('The sky is blue');
  });
});
import { createRouter, Route } from '@superfunctions/http';
import { IMemoryFn } from '../core/config';
import { AddMemoryInput, SearchMemoryInput } from '../core/types';

export function createMemoryRouter(memory: IMemoryFn) {
  const routes: Route[] = [
    {
      method: 'POST',
      path: '/v1/memories',
      handler: async (_req, ctx) => {
        const body = await ctx.json();
        // Validate body (using Zod in a real implementation)
        const input = body as AddMemoryInput;
        const result = await memory.add(input);
        return Response.json(result);
      }
    },
    {
      method: 'POST',
      path: '/v1/memories/search',
      handler: async (_req, ctx) => {
        const body = await ctx.json();
        const input = body as SearchMemoryInput;
        const result = await memory.search(input);
        return Response.json(result);
      }
    }
  ];

  return createRouter({ routes });
}

