import type { IMemoryFn, Memory } from '@memoryfn/core';
import { AdminError, type AdminOperationContext } from '@superfunctions/admin';
import type {
  MemoryFnAdminMemory,
  MemoryFnAdminService,
  MemoryFnDomainAdminServiceOptions,
} from './types.js';

function encoded(value: string): string {
  return encodeURIComponent(value);
}

function assertScope(
  options: MemoryFnDomainAdminServiceOptions,
  context: AdminOperationContext,
): { tenantId: string; scopeTag: string } {
  if (!context.scope.projectId || context.scope.projectId !== options.projectId) {
    throw new AdminError('forbidden', 'The active project cannot access this MemoryFn runtime.');
  }
  const environmentId = context.scope.environmentId?.trim();
  if (!environmentId) {
    throw new AdminError('precondition_failed', 'MemoryFn administration requires an environment scope.');
  }
  const namespace = context.scope.namespace?.trim();
  if (!namespace) {
    throw new AdminError('precondition_failed', 'MemoryFn administration requires a namespace.');
  }
  const region = context.scope.region?.trim() || 'global';
  const scopeTag = [
    'sfn-scope:v1',
    encoded(options.projectId),
    encoded(environmentId),
    encoded(namespace),
    encoded(region),
  ].join(':');
  return { tenantId: scopeTag, scopeTag };
}

async function resolveMemory(
  options: MemoryFnDomainAdminServiceOptions,
  context: AdminOperationContext,
): Promise<IMemoryFn> {
  return typeof options.memory === 'function'
    ? options.memory(context)
    : options.memory;
}

function isInScope(memory: Memory, tenantId: string, scopeTag: string): boolean {
  return memory.tenantId === tenantId && memory.containerTags.includes(scopeTag);
}

function outwardMemory(memory: Memory): MemoryFnAdminMemory {
  return {
    id: memory.id,
    type: memory.type,
    content: memory.content,
    isLatest: memory.isLatest,
    createdAt: memory.createdAt,
    updatedAt: memory.updatedAt,
  };
}

/**
 * Binds admin calls to MemoryFn's public API. Tenant identifiers and the
 * mandatory isolation tag are derived exclusively from the active scope.
 */
export function createMemoryFnDomainAdminService(
  options: MemoryFnDomainAdminServiceOptions,
): MemoryFnAdminService {
  if (!options.projectId.trim()) {
    throw new AdminError('invalid_argument', 'MemoryFn admin binding requires a projectId.');
  }

  return {
    async searchMemories(input, context) {
      const { tenantId, scopeTag } = assertScope(options, context);
      const memory = await resolveMemory(options, context);
      const result = await memory.search({ ...input, tenantId, containerTags: [scopeTag] });
      const scoped = result.results.filter((item) => isInScope(item, tenantId, scopeTag));
      return {
        items: scoped.map(outwardMemory),
        totalFound: scoped.length,
        returned: scoped.length,
      };
    },

    async ingestMemory(input, context) {
      const { tenantId, scopeTag } = assertScope(options, context);
      const memory = await resolveMemory(options, context);
      const result = await memory.add({
        content: input.content,
        type: input.type,
        metadata: input.metadata,
        tenantId,
        // This must remain the only container tag: MemoryFn storage adapters
        // use tag overlap, so adding caller labels would weaken scope isolation.
        containerTags: [scopeTag],
      });
      if (result.memories.some((item) => !isInScope(item, tenantId, scopeTag))) {
        throw new AdminError(
          'dependency_unavailable',
          'MemoryFn returned a record outside the active scope.',
          { retryable: false },
        );
      }
      return {
        items: result.memories.map(outwardMemory),
        summary: result.summary,
        relationshipsCreated: result.relationships.length,
        ...(result.cost ? { cost: result.cost } : {}),
      };
    },
  };
}
import type { Memory, MemoryRelationship } from '../../core/types';
import type { StorageAdapter } from '../adapter';

function cloneMemory(memory: Memory): Memory {
  return {
    ...memory,
    containerTags: [...memory.containerTags],
    embedding: memory.embedding ? [...memory.embedding] : null,
    metadata: structuredClone(memory.metadata),
  };
}

function cloneRelationship(relationship: MemoryRelationship): MemoryRelationship {
  return { ...relationship };
}

function cosineSimilarity(left: number[], right: number[]): number {
  if (left.length === 0 || left.length !== right.length) return Number.NEGATIVE_INFINITY;
  let dot = 0;
  let leftMagnitude = 0;
  let rightMagnitude = 0;
  for (let index = 0; index < left.length; index += 1) {
    const leftValue = left[index] ?? 0;
    const rightValue = right[index] ?? 0;
    dot += leftValue * rightValue;
    leftMagnitude += leftValue * leftValue;
    rightMagnitude += rightValue * rightValue;
  }
  if (leftMagnitude === 0 || rightMagnitude === 0) return 0;
  return dot / (Math.sqrt(leftMagnitude) * Math.sqrt(rightMagnitude));
}

function metadataMatches(
  metadata: Record<string, unknown>,
  filters: Record<string, unknown> | undefined,
): boolean {
  if (!filters) return true;
  return Object.entries(filters).every(([key, value]) => jsonContains(metadata[key], value));
}

function jsonContains(actual: unknown, expected: unknown): boolean {
  if (Array.isArray(expected)) {
    return Array.isArray(actual)
      && expected.every((candidate) => actual.some((value) => jsonContains(value, candidate)));
  }
  if (expected && typeof expected === 'object') {
    if (!actual || typeof actual !== 'object' || Array.isArray(actual)) return false;
    return Object.entries(expected as Record<string, unknown>)
      .every(([key, value]) => jsonContains((actual as Record<string, unknown>)[key], value));
  }
  return Object.is(actual, expected);
}

/**
 * A process-local StorageAdapter for self-hosted development and tests. It
 * preserves records for the lifetime of this adapter instance and applies the
 * same tag-overlap and metadata-filter semantics as the Postgres adapter. Use
 * the Postgres adapter when storage must survive process restarts.
 */
export class MemoryStorageAdapter implements StorageAdapter {
  private readonly memories = new Map<string, Memory>();
  private readonly relationships = new Map<string, MemoryRelationship>();
  private sequence = 0;

  async insertMemories(inputs: Partial<Memory>[]): Promise<Memory[]> {
    const now = Date.now();
    const saved = inputs.map((input) => {
      const memory: Memory = {
        id: input.id ?? `memory-${now}-${++this.sequence}`,
        tenantId: input.tenantId ?? 'default',
        containerTags: [...(input.containerTags ?? [])],
        type: input.type ?? 'conversational',
        content: input.content ?? '',
        embedding: input.embedding ? [...input.embedding] : null,
        metadata: structuredClone(input.metadata ?? {}),
        isLatest: input.isLatest ?? true,
        createdAt: input.createdAt ?? now,
        updatedAt: input.updatedAt ?? now,
      };
      return memory;
    });
    const ids = new Set<string>();
    for (const memory of saved) {
      if (ids.has(memory.id) || this.memories.has(memory.id)) {
        throw new Error(`Memory already exists: ${memory.id}`);
      }
      ids.add(memory.id);
    }
    for (const memory of saved) this.memories.set(memory.id, cloneMemory(memory));
    return saved.map(cloneMemory);
  }

  async insertRelationships(inputs: Partial<MemoryRelationship>[]): Promise<MemoryRelationship[]> {
    const now = Date.now();
    const saved = inputs.map((input) => {
      if (!input.fromId || !input.toId) {
        throw new Error('Memory relationships require fromId and toId.');
      }
      const relationship: MemoryRelationship = {
        id: input.id ?? `relationship-${now}-${++this.sequence}`,
        fromId: input.fromId,
        toId: input.toId,
        type: input.type ?? 'extends',
        confidence: input.confidence ?? 1,
        ...(input.reasoning === undefined ? {} : { reasoning: input.reasoning }),
        createdAt: input.createdAt ?? now,
      };
      this.relationships.set(relationship.id, cloneRelationship(relationship));
      return relationship;
    });
    return saved.map(cloneRelationship);
  }

  async searchVectors(params: {
    tenantId: string;
    embedding: number[];
    containerTags: string[];
    filters?: Record<string, unknown>;
    topK: number;
    threshold?: number;
  }): Promise<Memory[]> {
    const requestedTags = new Set(params.containerTags);
    return [...this.memories.values()]
      .filter((memory) => (
        memory.tenantId === params.tenantId
        && (requestedTags.size === 0 || memory.containerTags.some((tag) => requestedTags.has(tag)))
        && metadataMatches(memory.metadata, params.filters)
      ))
      .map((memory) => ({
        memory,
        similarity: memory.embedding ? cosineSimilarity(params.embedding, memory.embedding) : 0,
      }))
      .filter(({ similarity }) => Number.isFinite(similarity) && (params.threshold === undefined || similarity >= params.threshold))
      .sort((left, right) => right.similarity - left.similarity || right.memory.updatedAt - left.memory.updatedAt)
      .slice(0, Math.max(0, params.topK))
      .map(({ memory }) => cloneMemory(memory));
  }
}
import { StorageAdapter } from '../adapter';
import { Memory, MemoryRelationship } from '../../core/types';
import { memories, memoryRelationships } from './schema';
import { and, eq, sql } from 'drizzle-orm';
import { PostgresJsDatabase } from 'drizzle-orm/postgres-js';

// We assume the DB passed is compatible with PostgresJsDatabase schema
export class PostgresAdapter implements StorageAdapter {
  private db: PostgresJsDatabase<any>;

  constructor(db: PostgresJsDatabase<any>) {
    this.db = db;
  }

  async insertMemories(memoryInputs: Partial<Memory>[]): Promise<Memory[]> {
    if (memoryInputs.length === 0) return [];

    const now = new Date();

    // Map domain model to schema
    const values = memoryInputs.map(m => ({
      // id is autogenerated if not present, but we prefer letting DB generate it or using what's passed
      ...(m.id ? { id: m.id } : {}),
      tenantId: m.tenantId || 'default',
      containerTags: m.containerTags || [],
      type: m.type || 'conversational',
      content: m.content || '',
      embedding: m.embedding || null,
      metadata: m.metadata || {},
      isLatest: m.isLatest ?? true,
      createdAt: m.createdAt ? new Date(m.createdAt) : now,
      updatedAt: m.updatedAt ? new Date(m.updatedAt) : now,
    }));

    const result = await this.db.insert(memories)
      .values(values)
      .returning();

    return result.map(this.mapToDomain);
  }

  async insertRelationships(relationships: Partial<MemoryRelationship>[]): Promise<MemoryRelationship[]> {
    if (relationships.length === 0) return [];

    const now = new Date();
    const values = relationships.map(r => ({
      fromId: r.fromId!,
      toId: r.toId!,
      type: r.type || 'extends',
      confidence: r.confidence || 1.0,
      reasoning: r.reasoning,
      createdAt: r.createdAt ? new Date(r.createdAt) : now,
    }));

    const result = await this.db.insert(memoryRelationships)
      .values(values)
      .returning();

    return result.map(r => ({
      id: r.id,
      fromId: r.fromId,
      toId: r.toId,
      type: r.type as any,
      confidence: r.confidence,
      reasoning: r.reasoning || undefined,
      createdAt: r.createdAt.getTime(),
    }));
  }

  async searchVectors(params: {
    tenantId: string;
    embedding: number[];
    containerTags: string[];
    filters?: Record<string, any>;
    topK: number;
    threshold?: number;
  }): Promise<Memory[]> {
    const { tenantId, embedding, containerTags, topK, threshold } = params;

    // pgvector cosine similarity operator is <=>
    // We want to sort by distance ascending (closest first)
    // distance = 1 - similarity
    // To filter by threshold (similarity), distance should be <= (1 - threshold)

    const similarity = sql<number>`1 - (${memories.embedding} <=> ${JSON.stringify(embedding)}::vector)`;

    let query = this.db.select({
      memory: memories,
      similarity: similarity
    })
    .from(memories);

    // Build Where Clauses
    const conditions = [eq(memories.tenantId, tenantId)];

    // Filter by container tags (overlap)
    // We want memory to have AT LEAST ONE of the requested tags? 
    // Or MUST contain ALL? Usually scoping means "must match context".
    // Spec says: "Container Tags scope memories to specific contexts"
    // Usually this means the memory must belong to at least one of the contexts in the query, 
    // OR matching specific tag sets.
    // Simple implementation: Memory must have one of the tags in the query list.
    // Postgres array overlap: &&
    if (containerTags && containerTags.length > 0) {
      conditions.push(sql`${memories.containerTags} && ${containerTags}`);
    }

    if (threshold) {
        conditions.push(sql`(${memories.embedding} <=> ${JSON.stringify(embedding)}::vector) <= ${1 - threshold}`);
    }

    if (params.filters) {
        // Simple metadata exact match support
        for (const [key, value] of Object.entries(params.filters)) {
            // JSONB containment @>
            conditions.push(sql`${memories.metadata} @> ${JSON.stringify({ [key]: value })}`);
        }
    }

    if (conditions.length > 0) {
        query = query.where(and(...conditions)) as any;
    }

    const results = await query
        .orderBy(sql`${memories.embedding} <=> ${JSON.stringify(embedding)}::vector ASC`)
        .limit(topK);

    return results.map(r => this.mapToDomain(r.memory));
  }

