import {
  MAILFN_SCOPES,
  type Actor,
  type MailFn,
  MailFnError,
  type MailFnStore,
  type Message,
  type MessageFilter,
} from "@mailfn/core";
import {
  AdminError,
  decodeAdminCursor,
  encodeAdminCursor,
  normalizeAdminPageLimit,
  type AdminOperationContext,
  type AdminOperationResult,
} from "@superfunctions/admin";
import type {
  MailFnAdminRecord,
  MailFnAdminService,
  MailFnItemOutput,
  MailFnListOutput,
  MailFnMutationOutput,
} from "./types.js";

type JsonRecord = Record<string, unknown>;

export interface MailFnDomainAdminServiceOptions {
  mailfn: MailFn;
  store: MailFnStore;
}

interface ListInput {
  cursor?: string;
  limit?: number;
  search?: string;
  filter?: JsonRecord;
}

function record(value: unknown, label: string): JsonRecord {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new AdminError("invalid_argument", `${label} must be an object.`);
  }
  return value as JsonRecord;
}

function optionalRecord(value: unknown, label: string): JsonRecord | undefined {
  return value === undefined ? undefined : record(value, label);
}

function string(value: unknown, label: string): string {
