import {
  createAdminCapabilityAdapter as createKernelAdminCapabilityAdapter,
  type AdminCapabilityAdapter,
  type AdminOperationContext,
  type AdminOperationRequest,
} from "@superfunctions/admin";
import { flowFnAdminCapability } from "./capability.js";
import type { FlowFnAdminService } from "./types.js";

function bind<TInput, TOutput>(handler: (input: TInput, context: AdminOperationContext) => Promise<TOutput>) {
  return ({ input, context }: AdminOperationRequest) => handler(input as TInput, context);
}

export function createFlowFnAdminAdapter(service: FlowFnAdminService): AdminCapabilityAdapter<typeof flowFnAdminCapability> {
  return createKernelAdminCapabilityAdapter(flowFnAdminCapability, {
    "flowfn.queues.list": bind(service.listQueues),
    "flowfn.queues.get": bind(service.getQueue),
    "flowfn.queues.pause": bind(service.pauseQueue),
    "flowfn.queues.resume": bind(service.resumeQueue),
    "flowfn.jobs.list": bind(service.listJobs),
    "flowfn.jobs.get": bind(service.getJob),
    "flowfn.jobs.enqueue": bind(service.enqueueJob),
    "flowfn.workers.list": bind(service.listWorkers),
    "flowfn.workers.get": bind(service.getWorker),
    "flowfn.workers.run": bind(service.runWorker),
    "flowfn.workers.close": bind(service.closeWorker),
    "flowfn.dead-letters.list": bind(service.listDeadLetters),
    "flowfn.dead-letters.get": bind(service.getDeadLetter),
    "flowfn.dead-letters.redrive": bind(service.redriveDeadLetter),
    "flowfn.dead-letters.delete": bind(service.deleteDeadLetter),
    "flowfn.dead-letters.clean": bind(service.cleanDeadLetters),
    "flowfn.events.list": bind(service.listEvents),
  });
}

export const createAdminAdapter = createFlowFnAdminAdapter;

import {
  diffOpenAPI,
  parseOpenAPI,
  validateOpenAPI,
  type OpenAPIDocument,
} from "@apifn/core";
import { AdminError, type AdminOperationContext } from "@superfunctions/admin";

export interface ApiFnOperatorScope {
  installationId: string;
  workspaceId: string;
  projectId: string;
  environmentId: string | null;
}
export interface ApiFnPageInput { cursor?: string; limit?: number }

export interface ApiFnSpecRecord {
  id: string;
  scope: ApiFnOperatorScope;
  name: string;
  version: string;
  document: OpenAPIDocument;
  createdAt: string;
  updatedAt: string;
}
export interface ApiFnSpecView {
  id: string;
  scope: ApiFnOperatorScope;
  name: string;
  version: string;
  title: string;
  endpointCount: number;
  createdAt: string;
  updatedAt: string;
}
export interface ApiFnEnvironmentRecord {
  id: string;
  scope: ApiFnOperatorScope;
  name: string;
  baseUrl: string;
  enabled: boolean;
  createdAt: string;
  updatedAt: string;
}
export interface ApiFnDiffEntryView {
  type: "added" | "removed" | "modified";
  breaking: boolean;
  path: string;
  description: string;
}
export interface ApiFnDiffView {
  breaking: ApiFnDiffEntryView[];
  nonBreaking: ApiFnDiffEntryView[];
  hasBreakingChanges: boolean;
  summary: { added: number; removed: number; modified: number; breaking: number; nonBreaking: number };
}

/** Durable persistence boundary owned by ApiFn. */
export interface ApiFnOperatorStore {
  listSpecs(scope: ApiFnOperatorScope): Promise<ApiFnSpecRecord[]>;
  getSpec(scope: ApiFnOperatorScope, id: string): Promise<ApiFnSpecRecord | null>;
  putSpec(record: ApiFnSpecRecord): Promise<void>;
  deleteSpec(scope: ApiFnOperatorScope, id: string): Promise<boolean>;
  listEnvironments(scope: ApiFnOperatorScope): Promise<ApiFnEnvironmentRecord[]>;
  getEnvironment(scope: ApiFnOperatorScope, id: string): Promise<ApiFnEnvironmentRecord | null>;
  putEnvironment(record: ApiFnEnvironmentRecord): Promise<void>;
  deleteEnvironment(scope: ApiFnOperatorScope, id: string): Promise<boolean>;
}

/** Explicit in-memory implementation for tests and local development. */
  async deleteEnvironment(scope: ApiFnOperatorScope, id: string): Promise<boolean> {
    return this.environments.delete(this.key(scope, id));
  }
}

export interface ApiFnOperatorServiceOptions { store: ApiFnOperatorStore; now?: () => Date }
export interface ApiFnRegisterSpecInput { id: string; name: string; document: string | Record<string, unknown> }
export interface ApiFnCompareSpecInput { id: string; candidate: string | Record<string, unknown> }
export interface ApiFnUpsertEnvironmentInput { id: string; name: string; baseUrl: string; enabled?: boolean }

function requireScope(context: AdminOperationContext): ApiFnOperatorScope {
  const { installationId, workspaceId, projectId, environmentId } = context.scope;
  if (!installationId || !workspaceId || !projectId) {
    throw new AdminError(
      "invalid_argument",
      "ApiFn administration requires installation, workspace, and project scope identifiers.",
    );
  }
  return { installationId, workspaceId, projectId, environmentId: environmentId ?? null };
}

function specView(record: ApiFnSpecRecord): ApiFnSpecView {
  const endpointCount = Object.values(record.document.paths ?? {}).reduce(
    (count, item) => count + Object.keys(item ?? {}).filter((key) =>
      ["get", "put", "post", "delete", "patch", "options", "head", "trace"].includes(key),
    ).length,
    0,
  );
  return {
    id: record.id,
    scope: record.scope,
  store: BotFnOperatorStore;
  /** Verify the referenced credential against the platform before persistence. */
  verifyChannel(
    input: { platform: BotFnPlatform; externalId: string; credentialRef: string },
    context: AdminOperationContext,
  ): Promise<{ accountLabel?: string }>;
  now?: () => Date;
}

function requireScope(context: AdminOperationContext): BotFnOperatorScope {
  const { installationId, workspaceId, projectId, environmentId } = context.scope;
  if (!installationId || !workspaceId || !projectId) {
    throw new AdminError(
      "invalid_argument",
      "BotFn administration requires installation, workspace, and project scope identifiers.",
    );
  }
  return { installationId, workspaceId, projectId, environmentId: environmentId ?? null };
}

function page<T extends { id: string }>(items: T[], input: BotFnPageInput): {
  items: T[];
  nextCursor: string | null;
} {
  const limit = Math.min(Math.max(input.limit ?? 50, 1), 100);
  const offset = input.cursor === undefined ? 0 : Number(input.cursor);
  if (!Number.isSafeInteger(offset) || offset < 0) {
    throw new AdminError("invalid_argument", "BotFn cursor is invalid.");
  }
  const ordered = [...items].sort((left, right) => left.id.localeCompare(right.id));
  const values = ordered.slice(offset, offset + limit);
  const next = offset + values.length;
  return { items: values, nextCursor: next < ordered.length ? String(next) : null };
}

function channelView(value: BotFnChannelRecord): BotFnChannelView {
  const { credentialRef: _credentialRef, ...record } = value;
  return { ...record, credentialConfigured: true };
}

