  return { ...(toJson(job) as Omit<FlowFnAdminJob, "queue">), queue };
}

function adminDeadLetter(job: DLQJob): FlowFnAdminDeadLetter {
  return { ...(toJson(job) as Omit<FlowFnAdminDeadLetter, "queue">), queue: job.originalQueue };
}

